    ].map((value) => contentToText(value)).join('').trim();
    const reasoning = contentToText(message.reasoning_content || message.reasoning || message.analysis);
    if (reasoning.trim() && !visibleText) return '外接模型只返回了思考内容，没有生成最终正文';
    if ((message.tool_calls || message.function_call) && !visibleText) return '外接模型只返回了工具调用，没有生成最终正文';
    return '';
  }

  function responseFinishReason(body) {
    const rootBody = body?.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : body;
    return String(rootBody?.choices?.[0]?.finish_reason || rootBody?.incomplete_details?.reason || rootBody?.status || '').trim();
  }

  function extractResponseText(body, responseText = '') {
    const roots = [body];
    if (body?.data && typeof body.data === 'object' && !Array.isArray(body.data)) roots.push(body.data);
    for (const rootBody of roots) {
      if (!rootBody || typeof rootBody !== 'object') continue;
      const chat = contentToText(rootBody?.choices?.[0]?.message?.content);
      if (chat.trim()) return { text: chat, format: 'chat_completions', root: rootBody };
      const chatMessageText = contentToText(rootBody?.choices?.[0]?.message?.output_text)
        || contentToText(rootBody?.choices?.[0]?.message?.text);
      if (chatMessageText.trim()) return { text: chatMessageText, format: 'chat_message_text', root: rootBody };
      const chatDelta = contentToText(rootBody?.choices?.[0]?.delta?.content);
      if (chatDelta.trim()) return { text: chatDelta, format: 'chat_completion_delta', root: rootBody };
      const outputText = contentToText(rootBody.output_text);
      if (outputText.trim()) return { text: outputText, format: 'responses_output_text', root: rootBody };
      const responseParts = [];
      for (const item of Array.isArray(rootBody.output) ? rootBody.output : []) {
        if (item?.type && item.type !== 'message') continue;
        for (const part of Array.isArray(item?.content) ? item.content : []) {
          if (part?.type && !['output_text', 'text'].includes(part.type)) continue;
          const text = contentToText(part);
          if (text) responseParts.push(text);
        }
      }
      if (responseParts.join('').trim()) return { text: responseParts.join(''), format: 'responses_output', root: rootBody };
      const completion = contentToText(rootBody?.choices?.[0]?.text);
      if (completion.trim()) return { text: completion, format: 'completions', root: rootBody };
      const choiceContent = contentToText(rootBody?.choices?.[0]?.content);
      if (choiceContent.trim()) return { text: choiceContent, format: 'choice_content', root: rootBody };
      const directContent = contentToText(rootBody.content);
      if (directContent.trim()) return { text: directContent, format: 'direct_content', root: rootBody };
      if (typeof rootBody.text === 'string' && rootBody.text.trim()) return { text: rootBody.text, format: 'direct_text', root: rootBody };
      const directJsonKeys = ['state', 'change_evidence', 'summary', 'guidance', 'affected_modules', 'ok'];
      if (directJsonKeys.some((key) => Object.prototype.hasOwnProperty.call(rootBody, key))) {
        return { text: JSON.stringify(rootBody), format: 'direct_json', root: rootBody };
      }
    }
    if (!body && String(responseText || '').trim()) return { text: String(responseText), format: 'raw_text', root: null };
    return { text: '', format: 'missing', root: body };
  }

  function responseShapeSummary(body) {
    if (!body || typeof body !== 'object') return '非 JSON 响应';
    const rootBody = body?.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : body;
    const parts = [`顶层字段：${Object.keys(rootBody).slice(0, 12).join(', ') || '无'}`];
    if (Object.prototype.hasOwnProperty.call(rootBody, 'choices')) {
      const choices = Array.isArray(rootBody.choices) ? rootBody.choices : [];
      parts.push(`choices：${choices.length}`);
      if (choices[0] && typeof choices[0] === 'object') {
        parts.push(`choice字段：${Object.keys(choices[0]).slice(0, 12).join(', ') || '无'}`);
        if (choices[0].message && typeof choices[0].message === 'object') {
          parts.push(`message字段：${Object.keys(choices[0].message).slice(0, 12).join(', ') || '无'}`);
        }
        if (choices[0].finish_reason !== undefined) parts.push(`finish_reason：${String(choices[0].finish_reason)}`);
      }
    }
    return parts.join('；');
  }

  function traceEndpoint(value) {
    const source = String(value || '');
    if (!source) return '';
    try {
      const url = new URL(source);
      url.username = '';
      url.password = '';
      for (const key of [...url.searchParams.keys()]) {
        if (/key|token|secret|auth|password/i.test(key)) url.searchParams.set(key, '***');
      }
      return url.toString();
    } catch (_) {
      return source.replace(/([?&](?:api[_-]?key|token|secret|auth|password)=)[^&]*/gi, '$1***');
    }
  }

  function buildExternalOutputExample(schema) {
    const batch = schema?.properties?.turns;
    const makeRow = (envelope, turn) => {
      const stateSchema = envelope?.properties?.state?.oneOf?.find(item => item.type === 'object');
      const characterSchema = stateSchema?.properties?.characters?.additionalProperties?.oneOf?.find(item => item.properties?.mode?.const === 'detailed');
      if (!characterSchema) return null;
      const fields = characterSchema.properties;
      const character = { mode: 'detailed' };
      if (fields.needs) character.needs = Object.fromEntries(Object.keys(fields.needs.properties).map(key => [key,
        key === 'sleep' ? { wake_at: 'D1 08:00', sleeping: false, stage: '平稳期' }
          : { last_at: 'D1 10:00', stage: '平稳期' }]));
      if (fields.effects) character.effects = {};
      if (fields.sexual_desire_update) character.sexual_desire_update = null;
      if (fields.stamina_update) character.stamina_update = null;
      if (fields.reproductive?.properties?.menstrual_cycle) character.reproductive = {
        menstrual_cycle: { cycle_day: 8, phase: '卵泡期', user_awareness: '未知' },
      };
      const evidence = Object.fromEntries(Object.entries(envelope.properties.change_evidence?.properties || {})
        .map(([key, value]) => [key, value.type === 'array' ? [] : false]));
      return { ...(turn ? { turn } : {}), state: { version: 5, timeline: { day: 1, time: '10:10' }, scene: null,
        characters: { 示例人物: character } }, change_evidence: evidence,
        ...(envelope.properties.conception_updates ? { conception_updates: [] } : {}) };
    };
    if (!batch) return makeRow(schema);
    const turns = Array.from({ length: batch.minItems || 1 }, (_, index) => makeRow(batch.items.oneOf?.[index] || batch.items, index + 1));
    return turns.every(Boolean) ? { turns } : null;
  }

  function buildTranslatorRequest(input = {}) {
    const request = Array.isArray(input.turns) ? { turns: input.turns.map(row => ({ ...row })) } : {
      user_message: String(input.user_message || ''),
      assistant_narrative: String(input.assistant_narrative || ''),
    };

    if (request.turns?.length > 1) {
      const rules = request.turns[0].judgment_rules;
      if (typeof rules === 'string' && rules && request.turns.every(row => row.judgment_rules === rules)) {
        request.shared_judgment_rules = rules;
        request.turns.forEach(row => { delete row.judgment_rules; });
      }
    }
    if (input.analysis_mode === 'independent') request.analysis_mode = 'independent';
    if (input.previous_state !== null && input.previous_state !== undefined) request.previous_state = input.previous_state;
    if (input.modules?.sexual_desire === true && input.sexual_desire_state) request.sexual_desire_state = input.sexual_desire_state;
    if (input.modules?.stamina === true && input.stamina_state) request.stamina_state = input.stamina_state;
    if (Array.isArray(input.recent_context) && input.recent_context.length > 0) request.recent_context = input.recent_context;
    if (String(input.state_handoff || '').trim()) request.state_handoff = String(input.state_handoff);
    if (Array.isArray(input.manually_kept_characters) && input.manually_kept_characters.length) request.manually_kept_characters = input.manually_kept_characters;
    if (input.pending_restore && typeof input.pending_restore === 'object') request.restore_request = input.pending_restore;
    if (Array.isArray(input.effects_contracts) && input.effects_contracts.length > 0) request.allowed_effects = input.effects_contracts;
    if (Array.isArray(input.reserved_conception_ids) && input.reserved_conception_ids.length > 0) {
      request.reserved_conception_ids = input.reserved_conception_ids;
    }
    if (Array.isArray(input.conception_event_ledger) && input.conception_event_ledger.length > 0) {
      request.conception_event_ledger = input.conception_event_ledger;
    }
    request.current_state_schema = input.state_schema;
    const example = buildExternalOutputExample(input.state_schema);
    if (example) request.output_example = example;
    return request;
  }

  function manualStateEditRule(input) {
    if (!input.turns?.some(row => row.manual_state_edits_before?.length || row.manual_state_edits_after?.length)) return '';
    return '\n\n用户手动修改：manual_state_edits_before 在该轮开始前生效，manual_state_edits_after 在该轮结束后由脚本应用，不要提前写入该轮结果；后续轮从修改后的状态继续。path 的 snapshot 指状态本身，stamina_profiles 是脚本维护的只读体力起点，不能把它作为 state 字段输出；exists:false 表示移除该字段；只变更给出的字段。anchor_offset 用本轮对应时点减去 hours 还原时间锚点。不要把旧正文中的旧值覆盖回用户已修改的起点，也不要每轮重复重置；window 只适用于同一受孕窗口。';
  }

  function buildTranslatorMessages(input = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const request = buildTranslatorRequest(input);
    const effectEnabled = input.play_library_enabled === true
      || input.effect_mode === 'open'
      || (Array.isArray(input.effects_contracts) && input.effects_contracts.length > 0);
    return {
      request,
      messages: [
        { role: 'system', content: prompts.buildTranslatorSystemPrompt({
          analysisMode: input.analysis_mode,
          batch: Array.isArray(input.turns),
          modules: input.modules,
          effectMode: input.effect_mode,
          effectEnabled,
          userTrackingEnabled: input.user_tracking_enabled === true,
          autoProfileEnabled: input.auto_profile_enabled !== false,
          userName: input.user_name,
          sexualDesireRules: input.sexual_desire_rules,
          sexualDesireDeltas: input.sexual_desire_deltas,
        }) + (input.builtin_cycle_rule ? `\n\n# 内置周期记录（独立于玩法使用）\n${input.builtin_cycle_rule}` : '') + manualStateEditRule(input) },
        { role: 'user', content: JSON.stringify(request) },
      ],
    };
  }

  function buildRepairMessages(input = {}, repair = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const request = repair.original_request || buildTranslatorRequest(input);
    const effectEnabled = input.play_library_enabled === true
      || input.effect_mode === 'open'
      || (Array.isArray(input.effects_contracts) && input.effects_contracts.length > 0);
    const repairPayload = {
      candidate: repair.candidate ?? null,
      validation_errors: Array.isArray(repair.validation_errors) ? repair.validation_errors : [],
    };
    for (const key of [
      'previous_state', 'recent_context', 'user_message', 'assistant_narrative', 'state_handoff',
      'restore_request', 'allowed_effects', 'reserved_conception_ids', 'conception_event_ledger',
      'current_state_schema', 'turns', 'sexual_desire_state', 'stamina_state', 'analysis_mode',
      'shared_judgment_rules', 'output_example', 'manually_kept_characters',
    ]) {
      if (Object.prototype.hasOwnProperty.call(request, key)) repairPayload[key] = request[key];
    }
    return {
      request,
      messages: [
        { role: 'system', content: prompts.buildRepairSystemPrompt({
          analysisMode: input.analysis_mode,
          batch: Array.isArray(input.turns),
          modules: input.modules,
          effectMode: input.effect_mode,
          effectEnabled,
          userTrackingEnabled: input.user_tracking_enabled === true,
          autoProfileEnabled: input.auto_profile_enabled !== false,
          userName: input.user_name,
          sexualDesireRules: input.sexual_desire_rules,
          sexualDesireDeltas: input.sexual_desire_deltas,
        }) + (input.builtin_cycle_rule ? `\n\n# 内置周期记录（独立于玩法使用）\n${input.builtin_cycle_rule}` : '') + manualStateEditRule(input) },
        { role: 'user', content: JSON.stringify(repairPayload) },
      ],
    };
  }

  function buildPreflightRequest(input = {}) {
    const request = {
      user_message: String(input.user_message || ''),
    };
    if (input.previous_state !== null && input.previous_state !== undefined) request.previous_state = input.previous_state;
    if (Array.isArray(input.pending_context) && input.pending_context.length) request.pending_context = input.pending_context;
    const activeEffects = input.active_effects && typeof input.active_effects === 'object' ? input.active_effects : null;
    const hasActiveEffects = activeEffects && Object.values(activeEffects).some((effects) => (
      effects && typeof effects === 'object' && Object.keys(effects).length > 0
    ));
    if (hasActiveEffects) request.active_effects = activeEffects;
    if (Array.isArray(input.effects_contracts) && input.effects_contracts.length > 0) request.allowed_effects = input.effects_contracts;
    if (input.pending_restore && typeof input.pending_restore === 'object') request.restore_request = input.pending_restore;
    return request;
  }

  function buildPreflightMessages(input = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const request = buildPreflightRequest(input);
    return {
      request,
      messages: [
        { role: 'system', content: prompts.buildPreflightSystemPrompt({ modules: input.modules, hasPendingContext: Array.isArray(input.pending_context) && input.pending_context.length > 0 }) },
        { role: 'user', content: JSON.stringify(request) },
      ],
    };
  }

  function previewRequest(configInput, kind, input = {}, repair = {}) {
    const config = normalizeConfig(configInput);
    const normalizedKind = ['translator', 'preflight', 'repair'].includes(kind) ? kind : 'translator';
    const built = normalizedKind === 'preflight'
      ? buildPreflightMessages(input)
      : (normalizedKind === 'repair' ? buildRepairMessages(input, repair) : buildTranslatorMessages(input));
    const apiRequest = buildApiPayload(config, built.messages);
    return {
      kind: normalizedKind,
      phase: 'pseudo_request',
      endpoint: traceEndpoint(config.endpoint),
      model: config.model,
      timeout_ms: config.timeout_ms,
      messages: built.messages,
      api_format: apiRequest.kind,
      payload: apiRequest.payload,
      request: built.request,
    };
  }

  function emitTrace(options, event) {
    if (typeof options?.onTrace !== 'function') return;
    try { options.onTrace({ ...event, captured_at: new Date().toISOString() }); } catch (_) {   }
  }

  async function requestJson(configInput, messages, options = {}) {
    const config = normalizeConfig(configInput);
    assertConfig(config);
    const fetchImpl = options.fetchImpl || root.fetch;
    if (typeof fetchImpl !== 'function') throw Object.assign(new Error('当前宿主没有可用的 fetch'), { code: 'external_fetch_unavailable' });

    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    let rejectStopped;
    const stopped = new Promise((_, reject) => { rejectStopped = reject; });
    const cancel = () => {
      controller?.abort();
      rejectStopped(Object.assign(new Error('已停止外接请求'), { code: 'external_cancelled' }));
    };
    options.signal?.addEventListener('abort', cancel, { once: true });
    const timeoutId = root.setTimeout?.(() => {
      rejectStopped(Object.assign(new Error(`外接 API 等待超过 ${config.timeout_ms / 1000} 秒，可在 API 设置中延长等待时间`), { code: 'external_timeout' }));
      controller?.abort();
    }, config.timeout_ms);
    const headers = { 'Content-Type': 'application/json' };
    if (config.api_key) headers.Authorization = `Bearer ${config.api_key}`;
    const apiRequest = buildApiPayload(config, messages);
    const apiFormat = apiRequest.kind;
    const payload = apiRequest.payload;
    const traceKind = String(options.traceKind || 'external');
    const bridge = resolveTavernBridge(options);
    const key = transportKey(config), revision = transportState.revision;
    let transport = config.transport === TRANSPORTS.TAVERN
      || (config.transport === TRANSPORTS.AUTO && transportState.preferredKey === key) ? TRANSPORTS.TAVERN : TRANSPORTS.DIRECT;
    let receivedResponse = false;
    const markTransport = () => {
      if (revision === transportState.revision) Object.assign(transportState, { key, route: transport });
    };
    markTransport();
    emitTrace(options, {
      kind: traceKind,
      phase: 'request',
      endpoint: traceEndpoint(config.endpoint),
      model: config.model,
      timeout_ms: config.timeout_ms,
      api_format: apiFormat,
      transport,
      messages,
      payload,
    });

    let observedAttempt = null;
    try {
      const send = async (requestPayload) => {

        if (options.signal?.aborted) cancel();
        const request = async () => {
          if (transport === TRANSPORTS.TAVERN) {
            const relayBody = buildTavernRequest(config, requestPayload);
            if (!bridge) throw Object.assign(new Error('当前页面没有可用的酒馆代发接口，请在酒馆内使用或选择浏览器直连。'), { code: 'external_tavern_unavailable' });
            return bridge.fetch(new URL('/api/backends/chat-completions/generate', bridge.origin).href, {
              method: 'POST', headers: { ...bridge.getHeaders(), 'Content-Type': 'application/json' },
              body: JSON.stringify(relayBody), signal: controller?.signal, credentials: 'same-origin', redirect: 'error',
            });
          }
          return fetchImpl(config.endpoint, { method: 'POST', headers, body: JSON.stringify(requestPayload), signal: controller?.signal });
        };
        let response;
        try { response = await Promise.race([stopped, options.signal?.aborted ? stopped : request()]); }
        catch (error) {
          if (config.transport !== TRANSPORTS.AUTO || transport !== TRANSPORTS.DIRECT || receivedResponse
            || !(error instanceof TypeError) || controller?.signal.aborted || !bridge) throw error;

          tavernBaseUrl(config);
          transport = TRANSPORTS.TAVERN; markTransport();
          emitTrace(options, { kind: traceKind, phase: 'transport_fallback', transport, reason: '浏览器直连未取得响应，改由酒馆代发一次。' });
          response = await Promise.race([stopped, controller?.signal.aborted ? stopped : request()]);
        }
        receivedResponse = true;
        const responseText = await Promise.race([stopped, response.text()]);
        let body;
        try { body = JSON.parse(responseText); } catch (_) { body = null; }
        return { response, responseText, body };
      };
      let attempted = await send(payload);
      observedAttempt = attempted;
      const unsupportedResponseFormat = apiFormat !== 'completions' && structuredOutputUnsupported(attempted);
      if (unsupportedResponseFormat) {
        const fallbackPayload = removeStructuredOutputRequest(payload, apiFormat);
        emitTrace(options, {
          kind: traceKind,
          phase: 'request_fallback',
          endpoint: traceEndpoint(config.endpoint),
          model: config.model,
          api_format: apiFormat,
          messages,
          payload: fallbackPayload,
        });
        attempted = await send(fallbackPayload);
        observedAttempt = attempted;
      }
      const { response, responseText, body } = attempted;
      if (!response.ok) {
        const message = apiErrorMessage(body) || responseText || `HTTP ${response.status}`;
        throw Object.assign(new Error(`外接 API 请求失败：${message}`), { code: 'external_http_failed', status: response.status });
      }
      const successfulError = apiErrorMessage(body);
      if (successfulError) throw Object.assign(new Error(`外接 API 返回错误：${successfulError}`), { code: 'external_api_error' });
      const extracted = extractResponseText(body, responseText);
      const content = extracted.text;

      if (typeof options.onResponseText === 'function') options.onResponseText(content);
      const refusal = responseRefusalMessage(body) || responseRefusalMessage(body?.data);
      if (refusal) throw Object.assign(new Error(`外接模型没有提供状态结果：${refusal}`), { code: 'external_response_refused' });
      const stateError = responseStateError(body) || responseStateError(body?.data)
        || chatCompletionStateError(body) || chatCompletionStateError(body?.data);
      if (stateError) throw Object.assign(new Error(stateError), { code: 'external_response_incomplete' });
      if (!content.trim()) {
        throw Object.assign(new Error(`外接 API 响应中没有可用文本（${responseShapeSummary(body)}）`), {
          code: 'external_content_missing',
          response_shape: responseShapeSummary(body),
          finish_reason: responseFinishReason(body),
        });
      }
      const value = parseJsonResponse(content);
      if (transport === TRANSPORTS.TAVERN && config.transport === TRANSPORTS.AUTO && revision === transportState.revision) transportState.preferredKey = key;
      emitTrace(options, {
        kind: traceKind,
        phase: 'response',
        transport,
        status: response.status,
        api_format: extracted.format,
        model: String(extracted.root?.model || body?.model || config.model),
        response_text: content,
        parsed: value,
        raw_response: body,
        raw_response_text: body ? '' : responseText,
        finish_reason: responseFinishReason(extracted.root || body),
        usage: extracted.root?.usage || body?.usage || null,
      });
      return {
        transport,
        value,
        response_text: content,
        response_format: extracted.format,
        usage: extracted.root?.usage || body?.usage || null,
        model: String(extracted.root?.model || body?.model || config.model),
        raw: body,
      };
    } catch (error) {
      if (options.signal?.aborted || error?.code === 'external_cancelled') {
        throw Object.assign(new Error('已停止外接请求'), { code: 'external_cancelled' });
      }
      if (error?.name === 'AbortError') {
        const timeoutError = Object.assign(new Error('外接 API 请求已中断，未收到完整结果'), { code: 'external_timeout' });
        emitTrace(options, { kind: traceKind, phase: 'error', code: timeoutError.code, message: timeoutError.message });
        throw timeoutError;
      }
      if (error instanceof TypeError && !observedAttempt) error.message = transport === TRANSPORTS.TAVERN
        ? '酒馆代发连接中断，请检查酒馆服务和它到 API 的网络连接。' : networkFailureMessage();
      if (config.api_key && error?.message) error.message = error.message.split(config.api_key).join('[密钥已隐藏]');
      emitTrace(options, {
        kind: traceKind,
        phase: 'error',
        transport,
        code: error?.code || 'external_error',
        message: error?.message || String(error),
        status: observedAttempt?.response?.status,
        raw_response: observedAttempt?.body || null,
        raw_response_text: observedAttempt?.body ? '' : String(observedAttempt?.responseText || ''),
        response_shape: error?.response_shape || responseShapeSummary(observedAttempt?.body),
        finish_reason: error?.finish_reason || responseFinishReason(observedAttempt?.body),
      });
      throw error;
    } finally {
      options.signal?.removeEventListener('abort', cancel);
      if (timeoutId !== undefined) root.clearTimeout?.(timeoutId);
    }
  }

  async function translateTurn(config, input, options = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const built = buildTranslatorMessages(input);
    const request = built.request;
    try {
      const result = await requestJson(config, built.messages, { ...options, traceKind: options.traceKind || 'translator' });
      return { ...result, repaired: false, request };
    } catch (error) {
      if (error?.code !== 'external_json_invalid') throw error;
      return repairTurn(config, input, {
        original_request: request,
        candidate: error.response_text || '',
        validation_errors: [error.message || '外接返回无法解析为 JSON'],
      }, options);
    }
  }

  async function repairTurn(config, input, repair = {}, options = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const built = buildRepairMessages(input, repair);
    const result = await requestJson(config, built.messages, { ...options, traceKind: 'repair' });
    return { ...result, repaired: true, request: built.request };
  }

  async function preflightTurn(config, input, options = {}) {
    if (!prompts) throw new Error('外接提示词模块未加载');
    const built = buildPreflightMessages(input);
    const result = await requestJson(config, built.messages, { ...options, traceKind: options.traceKind || 'preflight' });
    const value = result.value;
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
