  function parseBodyModificationMaterials(section) {
    const materials = [];
    for (const paragraph of String(section?.intro || '').split(/\n\s*\n/)) {
      const match = paragraph.trim().match(/^([^:：\n]{1,12})[:：](.+)$/s);
