  function clampPressureEntryProfile(entry) {
    const metadata = entry?.metadata || {};
    const optionKey = ['档位', '夹法', '搭配', '松垂程度', '松紧程度', '吸力']
      .find((key) => metadata[key]) || '';
    const options = clampPressureChoiceValues(optionKey ? metadata[optionKey] : '');
    const locations = clampPressureChoiceValues(metadata.常见部位 || metadata.可接).map((choice) => choice.label);
    const weights = clampPressureChoiceValues(metadata.砝码档位);
    const pendant = ['坠子', '挂坠夹'].includes(entry?.label);
    return Object.freeze({
      role: entry?.scriptRole || '',
      locations: Object.freeze(locations),
      locationLabel: metadata.可接 ? '连接位置' : '使用部位',
      optionKey,
      options,
      defaultOption: options.find((choice) => choice.default)?.label || (options.length === 1 ? options[0].label : ''),
      fixedForce: metadata.力道 || '',
      defaultText: metadata.默认 || '',
      requiresClamp: ['拴链双夹', '挂坠夹'].includes(entry?.label),
      pendant,
      pendantVariants: pendant ? Object.freeze(['砝码坠', '铜铃坠', '铃串', '金属牌坠', '圆环坠', '链穗坠', '自定义']) : Object.freeze([]),
      weights,
      defaultWeight: weights.find((choice) => choice.default)?.label || '',
