      settingHint: metadata.本次设置 || '',
    });
  }

  function clampPressureSettingSummary(combination, entry) {
    const profile = clampPressureEntryProfile(entry);
    const clamp = CLAMP_PRESSURE_BASE_ENTRIES.find((candidate) => candidate.id === combination?.clamp_entry_id) || null;
    const detail = sanitizePlayDetail(combination?.detail, 500);
    const detailHasQuantity = /(?:左|右|单侧|双侧|数量|[0-9一二三四五六七八九十]+\s*(?:只|枚|个))/.test(detail);
    return [
      clamp ? `夹具：${clamp.label}` : '',
      combination?.location ? `${profile.locationLabel}：${combination.location}` : '',
      combination?.option ? `${profile.optionKey || '设置'}：${combination.option}` : '',
      profile.role === '基础夹具' && !detailHasQuantity ? '默认数量：成对部位两只，单点部位一只' : '',
      profile.defaultText ? `默认：${profile.defaultText}` : '',
      combination?.pendant_variant ? `坠子：${combination.pendant_variant}` : '',
      combination?.pendant_variant === '砝码坠' && combination?.weight ? `克重：${combination.weight}` : '',
      detail,
    ].filter(Boolean).join('；');
  }

  function bodyModificationOptionLabel(label) {
    return String(label || '').replace(/^穿孔/, '').replace(/^坠饰·/, '').trim();
  }

  function bodyModificationEntryCompatible(entry, baseEntry) {
    if (!entry || !baseEntry) return false;
    if (entry.label === '隐形保持器') return true;
    const option = bodyModificationOptionLabel(entry.label);
    if (baseEntry.availableOptions?.some((label) => bodyModificationOptionLabel(label) === option)) return true;
    if (!Array.isArray(entry.appliesTo) || entry.appliesTo.length === 0) return false;
    const baseLabel = baseEntry.label;
    return entry.appliesTo.some((target) => {
      if (target === '已有穿孔') return true;
      if (target === '乳环' || target === '双侧乳环' || target === '装有横杆的乳环') return baseLabel.includes('乳环');
      if (target === '耳部' || target === '耳垂') return baseLabel.includes('耳部');
      if (target === '阴蒂环') return baseLabel.includes('阴蒂环');
      if (target === '阴唇环') return baseLabel.includes('阴唇环');
      return baseLabel.includes(target) || target.includes(baseLabel.replace(/·.+$/, ''));
    });
  }

  function compatibleBodyModificationEntries(entries, baseEntry) {
    return Object.freeze((entries || []).filter((entry) => bodyModificationEntryCompatible(entry, baseEntry)
      && (!BODY_MODIFICATION_JEWELRY_ENTRIES.includes(entry) || bodyModificationSupportsJewelry(baseEntry, entry))));
  }

  function sanitizeBodyModificationDetails(raw, accessoryIds = [], extensionIds = []) {
    const input = isPlainObject(raw) ? raw : {};
    const accessories = {};
    const extensions = {};
    for (const id of accessoryIds) {
      const value = sanitizePlayDetail(input.accessories?.[id]);
      if (value) accessories[id] = value;
    }
    for (const id of extensionIds) {
      const value = sanitizePlayDetail(input.extensions?.[id]);
      if (value) extensions[id] = value;
    }
    return Object.freeze({
      base: sanitizePlayDetail(input.base || (typeof raw === 'string' ? raw : '')),
      jewelry: sanitizePlayDetail(input.jewelry),
      accessories: Object.freeze(accessories),
      extensions: Object.freeze(extensions),
    });
  }

  function bodyModificationInitialJewelry(entry) {
    return sanitizePlayDetail(entry?.initialJewelry, 80);
  }

  function bodyModificationJewelrySelection(combination, baseEntry) {
    const selected = BODY_MODIFICATION_JEWELRY_ENTRIES.find((entry) => (
      entry.id === combination?.jewelry_id
    ));
    if (selected) return selected;
    const label = bodyModificationSavedInitial(combination, baseEntry);
    return label ? Object.freeze({ id: '', label, body: '', summary: label, synthetic: true }) : null;
  }

  function bodyModificationEffectToken(entryId) {
    return playLibraryHash(String(entryId || ''));
  }

  function findPlayLibrarySection(sections, sectionId) {
    return sections.find((section) => section.id === sectionId) || null;
  }

  function findPlayLibraryEntry(sections, entryId) {
    for (const section of sections) {
      const entry = section.entries.find((candidate) => candidate.id === entryId);
      if (entry) return { section, entry };
    }
    return null;
  }

  function markingCarrierReference(carrier) {
    const commonEntries = MARKING_COMMON_SECTION?.entries || [];
    if (markingCarrierKind(carrier).includes('tattoo')) return commonEntries.find((entry) => entry.label.includes('工艺通则:纹身'))?.body || '';
    if (carrier === '烙印') return commonEntries.find((entry) => entry.label.includes('工艺通则:烙印'))?.body || '';
    const temporary = commonEntries.find((entry) => entry.label.includes('临时工艺一览'))?.body || '';
    if (!temporary) return '';
    const escaped = String(carrier || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = temporary.match(new RegExp(`${escaped}[:：]([\\s\\S]*?)(?=(?:记号笔|印章|贴花|彩绘|低温蜡)[:：]|$)`));
    return match ? `${carrier}：${match[1].trim()}` : '';
  }

  function markingCarrierKind(carrier) {
    const value = String(carrier || '').trim();
    if (value === '烙印') return 'permanent_brand';
    if (value === '纹身') return 'permanent_tattoo';
    if (/^纹身[（(]/.test(value)) return 'fading_tattoo';
    if (value === '佩件' || value === '首饰件') return 'wearable';
    return 'temporary';
  }

  function markingCarrierUsesTattooProcess(carrier) {
    return markingCarrierKind(carrier).includes('tattoo');
  }

  function markingCarrierIsPermanent(carrier) {
    return markingCarrierKind(carrier).startsWith('permanent_');
  }

  function markingProcess(entry, section, carrier) {
    if (markingCarrierUsesTattooProcess(carrier)) {
      const common = MARKING_COMMON_SECTION?.entries.find(candidate => candidate.label.includes('工艺通则:纹身'));
      return { label: '落墨·选开', body: entry.processInk || section.sharedProcessInk || common?.processInk || markingCarrierReference(carrier) };
    }
    if (carrier === '烙印') {
      const commonBrand = MARKING_COMMON_SECTION?.entries.find((candidate) => candidate.label.includes('工艺通则:烙印'));
      return { label: '落烙·选开', body: entry.processBrand || section.sharedProcessBrand || commonBrand?.processBrand || markingCarrierReference(carrier) };
    }
    if (markingCarrierKind(carrier) === 'wearable') return { label: '佩件', body: entry.body };
    return { label: '临时工艺·选开', body: markingCarrierReference(carrier) || entry.body };
  }

  function markingRecovery(entry, section, carrier) {
    if (markingCarrierUsesTattooProcess(carrier)) return entry.recovery || section.sharedRecovery
      || MARKING_COMMON_SECTION?.entries.find(candidate => candidate.label.includes('工艺通则:纹身'))?.recovery || '';
    if (carrier === '烙印') {
      const commonBrand = MARKING_COMMON_SECTION?.entries.find((candidate) => candidate.label.includes('工艺通则:烙印'));
      return commonBrand?.recovery || '';
    }
    return '';
  }

  function playCombinationId() {
    return playLibraryHash(`${Date.now()}|${Math.random()}|${runtime.playCombinations?.length || 0}`);
  }

  function sanitizePlayCombinations(input) {
    const result = [];
    const ids = new Set();
    for (const raw of Array.isArray(input) ? input : []) {
      if (!isPlainObject(raw)) continue;
      const id = /^[0-9a-f]{8}$/.test(String(raw.id || '')) ? String(raw.id) : '';
      const character = String(raw.character || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 120);
      const kind = ['marking', 'body_modification', 'clamp_pressure', ...NARRATIVE_LIBRARY_PLAY_KINDS].includes(raw.kind) ? raw.kind : '';
      if (!id || ids.has(id) || !character || !kind) continue;
      if (kind === 'marking') {
        const found = findPlayLibraryEntry(MARKING_SELECTABLE_SECTIONS, String(raw.entry_id || ''));
        const carrier = String(raw.carrier || '').replace('纹身(口内墨自褪,留色需重描)', '纹身(口内留色因位置而异)');
        if (!found || !found.entry.carriers.includes(carrier)) continue;
        result.push(Object.freeze({
          id,
          kind,
          character,
          active: raw.active !== false,
          layout_version: raw.layout_version === 2 ? 2 : 1,
          section_id: found.section.id,
          entry_id: found.entry.id,
          carrier,
          detail: raw.layout_version === 2 ? sanitizePlayDetail(raw.detail, 500) : '',
          process_pending: raw.layout_version === 2 && markingCarrierKind(carrier) !== 'wearable' && raw.completed !== true && raw.process_pending === true,
          recovery_enabled: raw.layout_version === 2 && markingCarrierKind(carrier) !== 'wearable' && raw.recovery_enabled === true,
          completed: raw.layout_version === 2 && markingCarrierKind(carrier) !== 'wearable' && raw.completed === true,
        }));
      } else if (kind === 'clamp_pressure') {
        const found = findPlayLibraryEntry(CLAMP_PRESSURE_SELECTABLE_SECTIONS, String(raw.entry_id || ''));
        if (!found) continue;
        const profile = clampPressureEntryProfile(found.entry);
        const location = profile.locations.includes(String(raw.location || '')) ? String(raw.location) : '';
        const option = profile.options.some((choice) => choice.label === raw.option)
          ? String(raw.option) : profile.defaultOption;
        const clamp = profile.requiresClamp
          ? CLAMP_PRESSURE_BASE_ENTRIES.find((entry) => entry.id === raw.clamp_entry_id) || null
          : null;
        const pendantVariant = profile.pendant && profile.pendantVariants.includes(String(raw.pendant_variant || ''))
          ? String(raw.pendant_variant) : (profile.pendant ? '砝码坠' : '');
        const weight = pendantVariant === '砝码坠' && profile.weights.some((choice) => choice.label === raw.weight)
          ? String(raw.weight) : (pendantVariant === '砝码坠' ? profile.defaultWeight : '');
        result.push(Object.freeze({
          id,
          kind,
          character,
          active: raw.active !== false,
          layout_version: 1,
          section_id: found.section.id,
          entry_id: found.entry.id,
          location,
          option,
          clamp_entry_id: clamp?.id || '',
          pendant_variant: pendantVariant,
          weight,
          detail: sanitizePlayDetail(raw.detail, 500),
        }));
      } else if (NARRATIVE_LIBRARY_PLAY_KINDS.includes(kind)) {
        if (kind === 'restraint') {
          const draft = normalizeRestraintDraft(raw);
          if (!draft) continue;
          result.push(Object.freeze({ id, ...draft, active: raw.active !== false }));
          ids.add(id);
          continue;
        }
        const library = narrativeOnlyPlayLibrary(kind);
        const entry = library.entries.find((candidate) => candidate.id === raw.entry_id) || null;
        if (!entry) continue;
        const variant = entry.variants.find((candidate) => candidate.id === raw.variant_id)
          || entry.variants[0]
          || null;
        result.push(Object.freeze({
          id,
          kind,
          character,
          active: raw.active !== false,
          layout_version: 1,
          entry_id: entry.id,
          variant_id: variant?.id || '',
          detail: sanitizePlayDetail(raw.detail, 500),
          ...(entry.connection ? { connection_detail: sanitizePlayDetail(raw.connection_detail, 500) } : {}),
        }));
      } else {
        const found = findPlayLibraryEntry(BODY_MODIFICATION_MAIN_SECTIONS, String(raw.entry_id || ''))
          || findPlayLibraryEntry(BODY_MODIFICATION_EXTENSION_SECTION ? [BODY_MODIFICATION_EXTENSION_SECTION] : [], String(raw.entry_id || ''));
        if (!found) continue;
        const isBase = BODY_MODIFICATION_MAIN_SECTIONS.some((section) => section.id === found.section.id);
        const jewelry = BODY_MODIFICATION_JEWELRY_ENTRIES.find((entry) => (
          entry.id === raw.jewelry_id
        )) || null;
        const material = BODY_MODIFICATION_MATERIALS.find((entry) => entry.id === raw.material_id) || null;
        const accessoryIds = [...new Set(Array.isArray(raw.accessory_ids) ? raw.accessory_ids : [])]
          .filter((idValue) => BODY_MODIFICATION_ACCESSORY_ENTRIES.some((entry) => (
            entry.id === idValue
          )));
        const extensionIds = [...new Set(Array.isArray(raw.extension_ids) ? raw.extension_ids : [])]
          .filter((idValue) => BODY_MODIFICATION_EXTENSION_ENTRIES.some((entry) => (
            entry.id === idValue
          )));
        result.push(Object.freeze({
          id,
          kind,
          character,
          active: raw.active !== false,
          layout_version: raw.layout_version === 2 && isBase ? 2 : 1,
          section_id: found.section.id,
          entry_id: found.entry.id,
          jewelry_id: jewelry?.id || '',
          narrative_revision: raw.narrative_revision === 4 ? 4 : 0,
          initial_jewelry: bodyModificationSavedInitial(raw, found.entry),
          material_id: material?.id || '',
          accessory_ids: Object.freeze(accessoryIds),
          extension_ids: Object.freeze(extensionIds),
          process_pending: raw.layout_version === 2 && raw.completed !== true && raw.process_pending === true,
          recovery_enabled: raw.layout_version === 2 && raw.recovery_enabled === true,
          completed: raw.layout_version === 2 && raw.completed === true,
          details: sanitizeBodyModificationDetails(raw.details, accessoryIds, extensionIds),
        }));
      }
      ids.add(id);
    }
    return Object.freeze(result);
  }

  function playCombinationSelection(combination) {
    if (!combination) return null;
    if (combination.kind === 'restraint') return restraintCombinationSelection(combination);
    if (combination.kind === 'marking') {
      const found = findPlayLibraryEntry(MARKING_SELECTABLE_SECTIONS, combination.entry_id);
      if (!found) return null;
      const process = markingProcess(found.entry, found.section, combination.carrier);
      const recovery = markingRecovery(found.entry, found.section, combination.carrier);
      const carrierKind = markingCarrierKind(combination.carrier);
      const resultPrompt = [
        `# ${found.entry.label}`,
        markingCombinationNote(combination.carrier),
        markingNarrativeForCarrier(found.section.intro, combination.carrier),
        markingNarrativeForCarrier(found.entry.body, combination.carrier),
        combination.layout_version === 2 && combination.detail ? `初始设置：${combination.detail}` : '',
      ].filter(Boolean).join('\n\n');
      return {
        section: found.section,
        entry: found.entry,
        process,
        recovery,
        resultPrompt,
        carrierKind,
        wearable: carrierKind === 'wearable',
        temporary: !markingCarrierIsPermanent(combination.carrier),
        legacy: combination.layout_version !== 2,
        detail: sanitizePlayDetail(combination.detail, 500),
        processPending: combination.layout_version === 2 && combination.process_pending === true,
        recoveryEnabled: combination.layout_version === 2 && combination.recovery_enabled === true,
        completed: combination.layout_version === 2 && combination.completed === true,
        label: `${found.entry.label}（${combination.carrier}）`,
      };
    }
    if (combination.kind === 'clamp_pressure') {
      const found = findPlayLibraryEntry(CLAMP_PRESSURE_SELECTABLE_SECTIONS, combination.entry_id);
      if (!found) return null;
      const profile = clampPressureEntryProfile(found.entry);
      const clamp = CLAMP_PRESSURE_BASE_ENTRIES.find((entry) => entry.id === combination.clamp_entry_id) || null;
      const settings = clampPressureSettingSummary(combination, found.entry);
      return {
        section: found.section,
        entry: found.entry,
        profile,
        clamp,
        settings,
        resultPrompt: [
          found.section.intro,
          found.entry.body,
          settings ? `初始设置：${settings}` : '',
        ].filter(Boolean).join('\n\n'),
        temporary: true,
        legacy: false,
        label: [found.entry.label, clamp?.label].filter(Boolean).join('｜'),
      };
    }
    if (NARRATIVE_LIBRARY_PLAY_KINDS.includes(combination.kind)) {
      const library = narrativeOnlyPlayLibrary(combination.kind);
      const entry = library.entries.find((candidate) => candidate.id === combination.entry_id) || null;
      if (!entry) return null;
      const variant = entry.variants.find((candidate) => candidate.id === combination.variant_id) || entry.variants[0] || null;
      const detail = sanitizePlayDetail(combination.detail, 500);
      const entryPrompt = [
        equipmentNarrativeBody(entry, combination.connection_detail),
        variant ? `### ${variant.label}\n\n${variant.body}` : '',
        detail ? `本次设置：${detail}` : '',
      ].filter(Boolean).join('\n\n');
      return {
        library,
        entry,
        variant,
        detail,
        entryPrompt,
        resultPrompt: [library.intro, entryPrompt].filter(Boolean).join('\n\n'),
        narrativeOnly: NARRATIVE_ONLY_PLAY_KINDS.includes(combination.kind),
        libraryBased: true,
        label: [entry.label, variant?.label].filter(Boolean).join('｜'),
      };
    }
    const found = findPlayLibraryEntry(BODY_MODIFICATION_MAIN_SECTIONS, combination.entry_id)
      || findPlayLibraryEntry(BODY_MODIFICATION_EXTENSION_SECTION ? [BODY_MODIFICATION_EXTENSION_SECTION] : [], combination.entry_id);
    if (!found) return null;
    const isBase = BODY_MODIFICATION_MAIN_SECTIONS.some((section) => section.id === found.section.id);
    const jewelry = isBase
      ? bodyModificationJewelrySelection(combination, found.entry)
      : BODY_MODIFICATION_JEWELRY_ENTRIES.find((entry) => entry.id === combination.jewelry_id) || null;
    const material = BODY_MODIFICATION_MATERIALS.find((entry) => entry.id === combination.material_id) || null;
    const accessories = BODY_MODIFICATION_ACCESSORY_ENTRIES.filter((entry) => (
      combination.accessory_ids?.includes(entry.id)
    ));
    const extensions = BODY_MODIFICATION_EXTENSION_ENTRIES.filter((entry) => (
      combination.extension_ids?.includes(entry.id)
    ));
    const details = sanitizeBodyModificationDetails(combination.details, accessories.map((entry) => entry.id), extensions.map((entry) => entry.id));
    const legacyLocation = combination.narrative_revision !== 4 && found.entry.id === 'bodymod_2aa1064d';
    const commonBody = legacyLocation ? '' : bodyModificationSelectedText(found.entry, null, [], 'common');
    const wearBody = legacyLocation ? '' : bodyModificationSelectedText(found.entry, jewelry, [], 'wear');
    const supportedJewelry = bodyModificationSupportsJewelry(found.entry, jewelry);
    const attachmentPrompt = entry => bodyModificationAccessoryIssue(found.entry, jewelry, entry) || legacyLocation || !supportedJewelry ? ''
      : [bodyModificationSelectedText(found.entry, jewelry, [entry], 'accessory'), entry.body].filter(Boolean).join('\n\n');
    const processBody = legacyLocation || !supportedJewelry ? '' : found.entry.processPiercing || found.section.sharedProcessPiercing || commonBody;
    if (combination.layout_version !== 2 || !isBase) {
      return {
        section: found.section,
        entry: found.entry,
        process: { label: '穿环·选开', body: processBody },
        recovery: found.entry.recovery || found.section.sharedRecovery || '',
        resultPrompt: [
          `# ${found.entry.label}`,
          found.section.intro,
          commonBody,
          wearBody,
          jewelry && supportedJewelry ? `## ${jewelry.label}\n\n${jewelry.body}` : '',
          material?.body || '',
          ...accessories.map(attachmentPrompt),
        ].filter(Boolean).join('\n\n'),
        temporary: false,
        legacy: true,
        jewelry, material, accessories, extensions, details,
        label: [found.entry.label, jewelry?.label, material?.label].filter(Boolean).join('｜'),
      };
    }
    return {
      section: found.section,
      entry: found.entry,
      process: { label: '穿环·选开', body: processBody },
      recovery: found.entry.recovery || found.section.sharedRecovery || '',
      basePrompt: commonBody,
      jewelryPrompt: supportedJewelry && !legacyLocation ? [wearBody, jewelry?.body || '', material?.body || ''].filter(Boolean).join('\n\n') : '',
      jewelryFormPrompt: supportedJewelry && !legacyLocation ? jewelry?.body || '' : '',
      accessoryPrompts: Object.freeze(Object.fromEntries(accessories.map((entry) => [entry.id, attachmentPrompt(entry)]))),
      extensionPrompts: Object.freeze(Object.fromEntries(extensions.map((entry) => [entry.id, attachmentPrompt(entry)]))),
      temporary: false,
      legacy: false,
      jewelry,
      material,
      accessories: Object.freeze(accessories),
      extensions: Object.freeze(extensions),
      details,
      processPending: combination.process_pending === true,
      recoveryEnabled: combination.recovery_enabled === true,
      completed: combination.completed === true,
      label: found.entry.label,
    };
  }

  const PLAY_EFFECT_KEY_RE = /^(marking|body_mod|clamp|insertion|mouth|restraint)_(process|recovery|result|visible|base|jewelry|accessory|extension|state)_([0-9a-f]{8})(?:_([0-9a-f]{8}))?$/;

  function playEffectParts(effectKey) {
    const match = String(effectKey || '').match(PLAY_EFFECT_KEY_RE);
    if (!match) return null;
    const parts = { prefix: match[1], phase: match[2], id: match[3], itemToken: match[4] || '' };
    if (parts.prefix === 'marking' && !['process', 'recovery', 'result', 'visible'].includes(parts.phase)) return null;
    if (parts.prefix === 'body_mod' && ['accessory', 'extension'].includes(parts.phase) !== Boolean(parts.itemToken)) return null;
    if (parts.prefix === 'clamp' && (parts.phase !== 'state' || parts.itemToken)) return null;
    if (['insertion', 'mouth'].includes(parts.prefix) && (parts.phase !== 'state' || parts.itemToken)) return null;
    if (parts.prefix === 'restraint' && parts.phase !== 'state') return null;
    return parts;
  }

  function playEffectKey(combination, phase, itemId = '') {
    if (combination?.kind === 'restraint') return `restraint_${phase}_${combination.id}${itemId ? `_${playLibraryHash(itemId)}` : ''}`;
    const prefix = combination?.kind === 'marking' ? 'marking'
      : (combination?.kind === 'clamp_pressure' ? 'clamp'
      : (combination?.kind === 'insertion_filling' ? 'insertion'
      : (combination?.kind === 'mouth_face' ? 'mouth' : 'body_mod')));
    const itemToken = prefix === 'body_mod' && ['accessory', 'extension'].includes(phase)
      ? `_${bodyModificationEffectToken(itemId)}` : '';
    return `${prefix}_${phase}_${combination.id}${itemToken}`;
  }

  function playCombinationForEffect(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    if (!parts) return null;
    return sanitizePlayCombinations(combinations).find((combination) => combination.id === parts.id) || null;
  }

  function combinationUsesPendingEffect(combination, selection = playCombinationSelection(combination)) {
    if (!combination || !selection) return false;
    if (combination.kind === 'restraint') return true;
    if (combination.kind === 'clamp_pressure') return true;
    if (combination.kind === 'mouth_face') return true;
    if (combination.kind === 'insertion_filling') return INSERTION_PENDING_EFFECT_LABELS.has(selection.entry.label);
    return combination.kind === 'marking' && selection.wearable === true;
  }

  function playCombinationIsCompleted(combination, snapshot = null) {
    if (combination?.completed === true) return true;
    if (!combination?.id || !isPlainObject(snapshot?.characters?.[combination.character]?.effects)) return false;
    return Object.keys(snapshot.characters[combination.character].effects).some((effectKey) => {
      const parts = playEffectParts(effectKey);
      return parts?.id === combination.id && parts.phase !== 'process';
    });
  }

  function markingEffectDescriptors(combination) {
    const selection = playCombinationSelection(combination);
    if (!selection || combination?.kind !== 'marking' || selection.legacy) return Object.freeze([]);
    if (!selection.wearable && !selection.completed) return Object.freeze([]);
    const suffix = selection.detail ? `；${selection.detail}` : '';
    const resultPhase = selection.temporary ? 'visible' : 'result';
    const resultLead = selection.wearable ? '当前佩戴' : (selection.temporary ? '当前可见' : '已完成');
    const descriptors = [Object.freeze({
      phase: resultPhase,
      key: playEffectKey(combination, resultPhase),
      label: `${resultLead}：${selection.label}`,
      note: `${resultLead}：${selection.label}${suffix}`,
      prompt: selection.resultPrompt,
    })];
    if (selection.recoveryEnabled && selection.recovery) {
      descriptors.push(Object.freeze({
        phase: 'recovery',
        key: playEffectKey(combination, 'recovery'),
        label: `恢复期：${selection.label}`,
        note: `恢复期：${selection.label}${suffix}`,
        prompt: selection.recovery,
      }));
    }
    return Object.freeze(descriptors);
  }

  function clampPressureEffectDescriptors(combination) {
    const selection = playCombinationSelection(combination);
    if (!selection || combination?.kind !== 'clamp_pressure') return Object.freeze([]);
    const note = selection.settings
      ? `当前${selection.entry.label}：${selection.settings}`
      : `当前${selection.entry.label}`;
    return Object.freeze([Object.freeze({
      phase: 'state',
      key: playEffectKey(combination, 'state'),
      label: `夹持与牵引：${selection.entry.label}`,
      note,
      prompt: selection.resultPrompt,
    })]);
  }

  function pendingStateEffectDescriptor(combination) {
    const selection = playCombinationSelection(combination);
    if (!combinationUsesPendingEffect(combination, selection)) return null;
    if (combination.kind === 'restraint') return restraintEffectDescriptors(combination)[0] || null;
    if (combination.kind === 'marking') return markingEffectDescriptors(combination)[0] || null;
    if (combination.kind === 'clamp_pressure') return clampPressureEffectDescriptors(combination)[0] || null;
    const prefix = combination.kind === 'insertion_filling' ? 'insertion' : 'mouth';
    const lead = combination.kind === 'insertion_filling' ? '留置状态' : '佩戴状态';
    const detail = selection.detail ? `：${selection.detail}` : '';
    return Object.freeze({
      phase: 'state',
      key: playEffectKey(combination, 'state'),
      label: `${lead}：${selection.entry.label}`,
      note: `${lead}：${selection.entry.label}${detail}`,
      prompt: selection.resultPrompt,
      prefix,
    });
  }

  function bodyModificationEffectDescriptors(combination) {
    const selection = playCombinationSelection(combination);
    if (!selection || combination?.kind !== 'body_modification' || selection.legacy) return Object.freeze([]);
    if (!selection.completed) return Object.freeze([]);
    const detailSuffix = (value) => value ? `；${value}` : '';
    const promptWithInitialSetting = (prompt, value) => [
      prompt,
      value ? `初始设置：${value}` : '',
    ].filter(Boolean).join('\n\n');
    const materialSuffix = selection.material ? `（${selection.material.label}）` : '';
    const jewelrySetting = [
      selection.material ? `材质颜色：${selection.material.label}` : '',
      selection.details.jewelry,
    ].filter(Boolean).join('；');
    const descriptors = [
      Object.freeze({
        phase: 'base',
        key: playEffectKey(combination, 'base'),
        label: `基础穿孔：${selection.entry.label}`,
        note: `基础穿孔：${selection.entry.label}${detailSuffix(selection.details.base)}`,
        referencePrompt: selection.basePrompt,
        prompt: promptWithInitialSetting(selection.basePrompt, selection.details.base),
      }),
    ];
    if (selection.jewelry) {
      descriptors.push(Object.freeze({
        phase: 'jewelry',
        key: playEffectKey(combination, 'jewelry'),
        label: `当前首饰：${selection.jewelry.label}`,
        note: `当前首饰：${selection.jewelry.label}${materialSuffix}${detailSuffix(selection.details.jewelry)}`,
        referencePrompt: selection.jewelryPrompt,
        genericReference: selection.jewelryFormPrompt,
        prompt: promptWithInitialSetting(selection.jewelryPrompt, jewelrySetting),
      }));
    }
    for (const entry of selection.accessories) {
      descriptors.push(Object.freeze({
        phase: 'accessory',
        itemId: entry.id,
        key: playEffectKey(combination, 'accessory', entry.id),
        label: `可摘配饰：${entry.label}`,
        note: `可摘配饰：${entry.label}${detailSuffix(selection.details.accessories[entry.id])}`,
        referencePrompt: selection.accessoryPrompts[entry.id],
        genericReference: selection.accessoryPrompts[entry.id] ? entry.body : '',
        prompt: promptWithInitialSetting(selection.accessoryPrompts[entry.id], selection.details.accessories[entry.id]),
      }));
    }
    for (const entry of selection.extensions) {
      descriptors.push(Object.freeze({
        phase: 'extension',
        itemId: entry.id,
        key: playEffectKey(combination, 'extension', entry.id),
        label: `后续扩展：${entry.label}`,
        note: `后续扩展：${entry.label}${detailSuffix(selection.details.extensions[entry.id])}`,
        referencePrompt: selection.extensionPrompts[entry.id],
        genericReference: selection.extensionPrompts[entry.id] ? entry.body : '',
        prompt: promptWithInitialSetting(selection.extensionPrompts[entry.id], selection.details.extensions[entry.id]),
      }));
    }
    if (selection.recoveryEnabled && selection.recovery) {
      descriptors.push(Object.freeze({
        phase: 'recovery',
        key: playEffectKey(combination, 'recovery'),
        label: `愈合期：${selection.entry.label}`,
        note: `愈合期：${selection.entry.label}${detailSuffix(selection.details.base)}`,
        prompt: selection.recovery,
      }));
    }
    return Object.freeze(descriptors);
  }

  function playCombinationEffectDescriptors(combination) {
    const selection = playCombinationSelection(combination);
    if (!selection) return Object.freeze([]);
    if (combination.kind === 'restraint') return restraintEffectDescriptors(combination);
    if (combination.kind === 'marking') return markingEffectDescriptors(combination);
    if (combination.kind === 'body_modification') return bodyModificationEffectDescriptors(combination);
    const pending = pendingStateEffectDescriptor(combination);
    return Object.freeze(pending ? [pending] : []);
  }



  function playCombinationDescriptorForEffect(combination, effectKey) {
    const parts = playEffectParts(effectKey);
    if (!parts || parts.id !== combination?.id) return null;
    const effective = ['marking', 'body_modification'].includes(combination.kind)
      ? { ...combination, completed: true } : combination;
    const selected = playCombinationEffectDescriptors(effective).find(item => item.key === effectKey);
    if (selected) return selected;
    if (effective.layout_version !== 2 || !['marking', 'body_modification'].includes(effective.kind)) return null;
    let retained;
    if (parts.phase === 'recovery') retained = { ...effective, recovery_enabled: true };
    else if (effective.kind === 'body_modification' && ['accessory', 'extension'].includes(parts.phase)) {
      const entries = parts.phase === 'accessory' ? BODY_MODIFICATION_ACCESSORY_ENTRIES : BODY_MODIFICATION_EXTENSION_ENTRIES;
      const entry = entries.find(item => bodyModificationEffectToken(item.id) === parts.itemToken);
      if (!entry) return null;
      const field = parts.phase === 'accessory' ? 'accessory_ids' : 'extension_ids';
      retained = { ...effective, [field]: [...new Set([...(effective[field] || []), entry.id])] };
    } else return null;
    const descriptor = playCombinationEffectDescriptors(retained).find(item => item.key === effectKey);
    if (!descriptor) return null;
    return Object.freeze({ ...descriptor, retainedOnly: true,
      recordingRule: playCombinationEffectRecordingRule(retained.kind, descriptor.phase, playCombinationSelection(retained), descriptor.itemId),
    });
  }

  function reconcileBodyModificationEffects(candidate, previousSnapshot, combinations = runtime.playCombinations, consumeProcess = true) {
    const sanitized = sanitizePlayCombinations(combinations);
    const managedCombinations = new Map(sanitized
      .filter((item) => ['body_modification', 'marking'].includes(item.kind) && item.layout_version === 2)
      .map((item) => [item.id, item]));
    let value = cloneJson(candidate);
    let changed = false;
    if (consumeProcess) {
      for (const [name, character] of Object.entries(value?.characters || {})) {
        for (const effectKey of Object.keys(character?.effects || {})) {
          const parts = playEffectParts(effectKey);
          if (!parts || parts.phase !== 'process' || !managedCombinations.has(parts.id)) continue;
          delete value.characters[name].effects[effectKey];
          changed = true;
        }
      }
    }
    return Object.freeze({ snapshot: value, combinations: sanitized, changed });
  }

  function playEffectLabel(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    const combination = playCombinationForEffect(effectKey, combinations);
    const selection = playCombinationSelection(combination);
    if (!parts || !selection) return '';
    if (parts.prefix === 'restraint') return restraintEffectDescriptors(combination).find(item => item.key === effectKey)?.label || '';
    if (parts.prefix === 'marking' && !selection.legacy) {
      return playCombinationDescriptorForEffect(combination, effectKey)?.label || '';
    }
    if (parts.prefix === 'clamp') {
      return clampPressureEffectDescriptors(combination).find((descriptor) => descriptor.key === effectKey)?.label || '';
    }
    if (parts.prefix === 'body_mod' && !selection.legacy) {
      return playCombinationDescriptorForEffect(combination, effectKey)?.label || '';
    }
    if (['insertion', 'mouth'].includes(parts.prefix)) {
      return pendingStateEffectDescriptor(combination)?.label || '';
    }
    const phaseLabels = { process: selection.process.label, recovery: '恢复期', result: '完成结果', visible: selection.wearable ? '当前佩戴' : '当前仍可见' };
    return `${phaseLabels[parts.phase] || parts.phase}：${selection.label}`;
  }

  function activePlayCombinationEffects(snapshot, combinations = runtime.playCombinations) {
    const result = [];
    const sanitized = sanitizePlayCombinations(combinations);
    for (const [character, state] of Object.entries(snapshot?.characters || {})) {
      for (const [effectKey, effect] of Object.entries(state?.effects || {})) {
        const parts = playEffectParts(effectKey);
        const combination = parts ? sanitized.find((candidate) => candidate.id === parts.id) : null;
        if (!parts || !combination || !effectIsPersisting(effect)) continue;
        result.push(Object.freeze({ character, effectKey, effect, parts, combination }));
      }
    }
    return Object.freeze(result);
  }

  function markingNarrativeReference(selection, descriptor) {
    if (!descriptor?.prompt) return '';
    if (descriptor.phase === 'process') {
      const temporary = selection?.carrierKind === 'temporary';
      const title = temporary ? `临时工艺｜${selection?.label || descriptor.label}` : descriptor.label;
      const role = temporary
        ? '以下内容用于描写进行这次临时标记时的操作、触感与刚完成时的表现。'
        : '以下内容用于描写这次标记实施时的操作、即时身体反应与疼痛过程。';
      return `### ${title}\n\n${role}\n\n${descriptor.prompt}`;
    }
    if (descriptor.phase === 'recovery') {
      return `### ${descriptor.label}\n\n以下内容用于描写标记完成后仍在持续的疼痛、敏感与恢复表现。\n\n${descriptor.prompt}`;
    }
    return `### ${descriptor.label}\n\n${descriptor.prompt}`;
  }

  function bodyModificationNarrativeReference(descriptor) {
    if (!descriptor?.prompt) return '';
    if (descriptor.phase === 'process') {
      return `### 穿环过程\n\n以下内容用于描写穿刺时的操作、即时身体反应与疼痛过程。\n\n${descriptor.prompt}`;
    }
    if (descriptor.phase === 'recovery') {
      return `### 愈合期\n\n以下内容用于描写穿刺完成后仍在持续的疼痛、敏感与恢复表现。\n\n${descriptor.prompt}`;
    }
    return `### ${descriptor.label}\n\n${descriptor.prompt}`;
  }

  function buildPlayCombinationNarratives(snapshot, combinations = runtime.playCombinations, external = false) {
    const title = (combination, label) => external ? externalCombinationLabel(combination) : `${combination.character}｜${label}`;
    const prompts = [];
    const sanitized = sanitizePlayCombinations(combinations);
    const active = sanitized.filter((combination) => combination.active !== false);
    const activeEffects = activePlayCombinationEffects(snapshot, sanitized);
    const preparedBridge = '以下是本次已经准备的器具与设置，是否使用以实际剧情为准；使用时贴近正文自然叙事。';
    const bodyGroups = new Map();
    const markingGroups = new Map();
    const clampGroups = new Map();
    for (const kind of NARRATIVE_LIBRARY_PLAY_KINDS) {
      const selected = active
        .filter((combination) => combination.kind === kind)
        .map((combination) => ({ combination, selection: playCombinationSelection(combination) }))
        .filter((item) => item.selection);
      if (selected.length === 0) continue;
      const library = selected[0].selection.library;
      prompts.push(`# ${library.title}${library.intro ? `\n\n${library.intro}` : ''}`);
      for (const { combination, selection } of selected) {
        if (combination.kind === 'restraint') {
          prompts.push(`## ${title(combination, selection.label)}\n\n### 本次对象与当前记录\n\n${restraintCurrentState(combination, snapshot, external)}\n\n${selection.entryPrompt}`);
          continue;
        }
        const descriptor = pendingStateEffectDescriptor(combination);
        const effect = descriptor ? snapshot?.characters?.[combination.character]?.effects?.[descriptor.key] : null;
        const state = effectIsPersisting(effect)
          ? `### 当前状态\n\n- ${effect.notes || descriptor.note}`
          : `### 本次准备\n\n${preparedBridge}`;
        prompts.push(`## ${title(combination, selection.label)}\n\n${state}\n\n${selection.entryPrompt}`);
      }
    }

    for (const combination of active) {
      const selection = playCombinationSelection(combination);
      if (!selection) continue;
      if (combination.kind === 'clamp_pressure') {
        const descriptor = clampPressureEffectDescriptors(combination)[0];
        clampGroups.set(`${combination.character}:${combination.id}`, {
          combination, selection, descriptor,
          effect: descriptor ? snapshot?.characters?.[combination.character]?.effects?.[descriptor.key] : null,
        });
        continue;
      }
      if (combination.kind === 'marking' && !selection.legacy) {
        const completed = playCombinationIsCompleted(combination, snapshot);
        const effectiveCombination = completed ? { ...combination, completed: true } : combination;
        const descriptors = markingEffectDescriptors(effectiveCombination);
        const effects = descriptors.map((descriptor) => ({
          descriptor,
          effect: snapshot?.characters?.[combination.character]?.effects?.[descriptor.key],
        })).filter((item) => effectIsPersisting(item.effect));
        if (selection.wearable || !completed || effects.length > 0) {
          markingGroups.set(`${combination.character}:${combination.id}`, {
            combination: effectiveCombination, selection: playCombinationSelection(effectiveCombination), effects,
          });
        }
        continue;
      }
      if (combination.kind === 'body_modification' && !selection.legacy) {
        const completed = playCombinationIsCompleted(combination, snapshot);
        const effectiveCombination = completed ? { ...combination, completed: true } : combination;
        const descriptors = bodyModificationEffectDescriptors(effectiveCombination);
        const effects = descriptors.map((descriptor) => ({
          descriptor,
          effect: snapshot?.characters?.[combination.character]?.effects?.[descriptor.key],
        })).filter((item) => effectIsPersisting(item.effect));
        if (!completed || effects.length > 0) {
          bodyGroups.set(`${combination.character}:${combination.id}`, {
            combination: effectiveCombination, selection: playCombinationSelection(effectiveCombination), effects,
          });
        }
      }
    }

    for (const route of activeEffects) {
      const selection = playCombinationSelection(route.combination);
      if (!selection) continue;
      if (NARRATIVE_LIBRARY_PLAY_KINDS.includes(route.combination.kind)) {
        if (route.combination.active === false) {
          const owner = route.combination.kind === 'restraint' ? route.character : undefined;
          const label = playEffectLabel(route.effectKey, sanitized) || selection.label;
          prompts.push(`# ${external ? externalCombinationLabel(route.combination, undefined, owner) : (route.combination.kind === 'restraint' ? `${route.character}｜${label}` : label)}\n\n### 当前状态\n\n- ${route.effect?.notes || selection.label}`);
        }
        continue;
      }
      if (route.combination.kind === 'clamp_pressure') {
        const descriptor = clampPressureEffectDescriptors(route.combination).find((item) => item.key === route.effectKey);
        if (descriptor) clampGroups.set(`${route.character}:${route.combination.id}`, {
          combination: route.combination, selection, descriptor, effect: route.effect,
        });
        continue;
      }
      if (route.combination.kind === 'marking' && !selection.legacy) {
        const groupKey = `${route.character}:${route.combination.id}`;
        const effectiveCombination = { ...route.combination, completed: true };
        const effectiveSelection = playCombinationSelection(effectiveCombination);
        if (!markingGroups.has(groupKey)) markingGroups.set(groupKey, { combination: effectiveCombination, selection: effectiveSelection, effects: [] });
        const descriptor = playCombinationDescriptorForEffect(effectiveCombination, route.effectKey);
        if (descriptor && !markingGroups.get(groupKey).effects.some((item) => item.descriptor.key === descriptor.key)) {
          markingGroups.get(groupKey).effects.push({ descriptor, effect: route.effect });
        }
        continue;
      }
      if (route.combination.kind === 'body_modification' && !selection.legacy) {
        const groupKey = `${route.character}:${route.combination.id}`;
        const effectiveCombination = { ...route.combination, completed: true };
        const effectiveSelection = playCombinationSelection(effectiveCombination);
        if (!bodyGroups.has(groupKey)) bodyGroups.set(groupKey, { combination: effectiveCombination, selection: effectiveSelection, effects: [] });
        const descriptor = playCombinationDescriptorForEffect(effectiveCombination, route.effectKey);
        if (descriptor && !bodyGroups.get(groupKey).effects.some((item) => item.descriptor.key === descriptor.key)) {
          bodyGroups.get(groupKey).effects.push({ descriptor, effect: route.effect });
        }
        continue;
      }
    }

    for (const { combination, selection, effects } of markingGroups.values()) {
      const completed = playCombinationIsCompleted(combination, snapshot);
      if (!completed && !selection.wearable) {
        const process = selection.processPending && selection.process?.body
          ? markingNarrativeReference(selection, { phase: 'process', label: selection.process.label, prompt: selection.process.body }) : '';
        const result = `### 完成后的设计\n\n${selection.resultPrompt}`;
        const recovery = selection.recoveryEnabled && selection.recovery
          ? `### 完成后的恢复\n\n${selection.recovery}` : '';
        prompts.push(`## ${title(combination, selection.label)}\n\n### 进行中\n\n本次设计已经确定，完成前按当前剧情继续。${process ? `\n\n${process}` : ''}\n\n${result}${recovery ? `\n\n${recovery}` : ''}`);
        continue;
      }
      if (selection.wearable && effects.length === 0) {
        prompts.push(`## ${title(combination, selection.label)}\n\n### 本次准备\n\n${preparedBridge}\n\n${selection.resultPrompt}`);
        continue;
      }
      if (effects.length === 0) continue;
      const ordered = [...effects].sort((left, right) => (
        ['result', 'visible', 'recovery'].indexOf(left.descriptor.phase)
        - ['result', 'visible', 'recovery'].indexOf(right.descriptor.phase)
      ));
      const current = ordered.map(({ descriptor, effect }) => `- ${effect?.notes || descriptor.note}`).join('\n');
      const references = combination.active === false ? [] : ordered
        .map(({ descriptor }) => ({ phase: descriptor.phase, text: markingNarrativeReference(selection, descriptor) }))
        .filter((item) => item.text);
      const middle = references.filter((item) => item.phase !== 'recovery').map((item) => item.text).join('\n\n');
      const recovery = references.filter((item) => item.phase === 'recovery').map((item) => item.text).join('\n\n');
      prompts.push(`## ${title(combination, selection.label)}\n\n### 当前状态\n\n${current}${middle ? `\n\n${middle}` : ''}${recovery ? `\n\n${recovery}` : ''}`);
    }
    if (clampGroups.size > 0) {
      prompts.push('# 夹持、压力与牵引');
      for (const { combination, selection, descriptor, effect } of clampGroups.values()) {
        const current = effectIsPersisting(effect)
          ? `### 当前状态\n\n- ${effect.notes || descriptor.note}`
          : `### 本次准备\n\n${preparedBridge}`;
        const reference = combination.active === false ? '' : descriptor.prompt;
        prompts.push(`## ${title(combination, selection.entry.label)}\n\n${current}${reference ? `\n\n${reference}` : ''}`);
      }
    }
    if (bodyGroups.size > 0) {
      prompts.push('# 身体改造组合');
      for (const { combination, selection, effects } of bodyGroups.values()) {
        const completed = playCombinationIsCompleted(combination, snapshot);
        if (!completed) {
          const process = selection.processPending && selection.process?.body
            ? bodyModificationNarrativeReference({ phase: 'process', prompt: selection.process.body }) : '';
          const plannedDescriptors = bodyModificationEffectDescriptors({ ...combination, completed: true });
          const middle = plannedDescriptors.filter((descriptor) => descriptor.phase !== 'recovery')
            .map((descriptor) => bodyModificationNarrativeReference(descriptor)).filter(Boolean).join('\n\n');
          const recovery = selection.recoveryEnabled && selection.recovery
            ? bodyModificationNarrativeReference({ phase: 'recovery', prompt: selection.recovery }) : '';
          prompts.push(`## ${title(combination, selection.entry.label)}\n\n### 进行中\n\n本次设计已经确定，完成前按当前剧情继续。${process ? `\n\n${process}` : ''}${middle ? `\n\n### 完成后的设计\n\n${middle}` : ''}${recovery ? `\n\n${recovery}` : ''}`);
          continue;
        }
        if (effects.length === 0) continue;
        const ordered = [...effects].sort((left, right) => (
          ['base', 'jewelry', 'accessory', 'extension', 'recovery'].indexOf(left.descriptor.phase)
          - ['base', 'jewelry', 'accessory', 'extension', 'recovery'].indexOf(right.descriptor.phase)
        ));
        const current = ordered.map(({ descriptor, effect }) => `- ${effect?.notes || descriptor.note}`).join('\n');
        const references = combination.active === false ? [] : ordered
          .map(({ descriptor, effect }) => ({ phase: descriptor.phase, text: bodyModificationNarrativeReference({ ...descriptor, prompt: bodyModificationCurrentReference(selection, descriptor, effect, ordered) }) }))
          .filter((item) => item.text);
        const middle = references.filter((item) => item.phase !== 'recovery').map((item) => item.text).join('\n\n');
        const recovery = references.filter((item) => item.phase === 'recovery').map((item) => item.text).join('\n\n');
        prompts.push(`## ${title(combination, selection.entry.label)}\n\n### 当前状态\n\n${current}${middle ? `\n\n${middle}` : ''}${recovery ? `\n\n${recovery}` : ''}`);
      }
    }
    return prompts;
  }

  function buildPlayCombinationJudgmentPrompt(snapshot, combinations = runtime.playCombinations) {
    const contracts = buildPlayCombinationEffectContracts(snapshot, combinations);
    if (contracts.length === 0) return '';
    return `# 玩法效果\n\n${contracts.map((contract) => `- ${contract.group || contract.label}：使用 effects.${contract.id}。${contract.recording_rule}`).join('\n')}`;
  }

  function buildExternalPlayCombinationJudgmentPrompt(snapshot, combinations = runtime.playCombinations) {
    const contracts = buildPlayCombinationEffectContracts(snapshot, combinations);
    if (contracts.length === 0) return '';
    const groups = new Map();
    for (const contract of contracts) {
      const group = contract.group || contract.label;
      if (!group) continue;
      const combination = playCombinationForEffect(contract.id, combinations);
      if (!groups.has(group)) groups.set(group, { combination, contracts: [] });
      groups.get(group).contracts.push(contract);
    }
    const lines = [];
    for (const [group, entry] of groups) {
      const combination = entry.combination;
      const selection = playCombinationSelection(combination);
      const phases = new Set(entry.contracts.map((contract) => playEffectParts(contract.id)?.phase).filter(Boolean));
      let rule = '交接正文结束时仍在的实际设置和直接影响；对应状态结束时交接为结束。';
      if (combination?.kind === 'marking') {
        if (selection?.wearable) {
          rule = '实际佩戴后才交接当前佩件、位置和直接影响；取下且影响消退后交接为结束。';
        } else if (selection?.temporary) {
          rule = '完成后交接仍可见的具体形态、位置和数量；褪去或清除后交接为结束。';
        } else {
          rule = '完成后的标记属于长期身体记录；恢复结束只结束恢复状态，不删除已经完成的标记。';
        }
        if (phases.has('recovery')) rule += ' 恢复中的疼痛、敏感和恢复表现单独交接。';
      } else if (combination?.kind === 'body_modification') {
        rule = '基础穿孔属于长期身体记录；首饰、配饰、后续扩展和愈合分别交接，取下或结束其中一项时不删除基础穿孔。只取下一部分或解开一端时，写清剩余数量和连接；打开不等于整件取下。';
      } else if (['clamp_pressure', 'insertion_filling', 'mouth_face'].includes(combination?.kind)) {
        rule = '器具实际戴上、夹上或留置后才交接；写清当前器具、设置和直接影响。取下后仍有直接余感时继续交接，全部消退后交接为结束。';
      } else if (combination?.kind === 'restraint') {
        rule = '实际使用后才交接，写清各自当前固定关系、活动限制和直接影响；调整后更新，解除后只保留仍在的余感，全部结束时交接为结束。';
      }
      const owner = entry.contracts[0]?.character;
      lines.push(`- ${combination ? externalCombinationLabel(combination, undefined, owner) : group}：${rule}`);
    }
    return lines.length > 0 ? `# 玩法状态\n\n${lines.join('\n')}` : '';
  }

