      const descriptor = pendingStateEffectDescriptor(combination);
      if (!descriptor) continue;
      const activeEffect = snapshot?.characters?.[combination.character]?.effects?.[descriptor.key];
      addContract(combination, descriptor, effectIsPersisting(activeEffect), true);
