  function stripHistoricalLifeState(text, keepStateHandoff = false) {
    const pattern = keepStateHandoff
      ? /<life_state\b[^>]*>[\s\S]*?<\/life_state>/gi
      : /<(life_state|state_handoff)\b[^>]*>[\s\S]*?<\/\1>/gi;
    return String(text ?? '')
      .replace(pattern, '')
      .replace(/<story_time\b[^>]*>[\s\S]*?<\/story_time>/gi, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
