      && ['regenerate', 'swipe'].includes(plan?.generationType)
      && handoffIndexes.at(-1) === sourceChat.length - 1) handoffIndexes.pop();
    const keptHandoffIndexes = new Set(plan?.workflowMode === WORKFLOW_MODES.EXTERNAL && plan?.analysisMode !== 'independent'
      ? handoffIndexes.slice(-Math.max(1, Math.min(3, runtime.externalPendingQueue.length))) : []);
