    const beforeMode = placeNarrativeAtAnchor(messages, anchors.worldInfoBefore, content, 'after', 'world_info_before_end');
    if (beforeMode) return beforeMode;

    const characterAnchor = lastCharacterAnchor(messages, [anchors.description, anchors.personality, anchors.scenario]);
