    replaceString: '',
    trimStrings: Object.freeze([]),
    placement: Object.freeze([2]),
    disabled: false,
    markdownOnly: true,
    promptOnly: false,
    runOnEdit: true,
    substituteRegex: 0,
    minDepth: null,
    maxDepth: null,
  });


  const DISPLAY_REGEX_REFRESH = Object.freeze({ source: 'life-state-regex' });

  async function syncDisplayRegexList(context, document = runtime.hostDocument) {
    if (context?.extensionSettings?.disabledExtensions?.includes('regex')) return true;
    const list = document?.getElementById?.('saved_regex_scripts');
    if (!list) return false;
    const matches = () => [...list.children].some(row => row.id === DISPLAY_STATE_REGEX.id
      && row.querySelector('.regex_script_name')?.textContent === DISPLAY_STATE_REGEX.scriptName
      && row.querySelector('.disable_regex')?.checked === false);
    if (matches()) return true;
    const event = context?.eventTypes?.CHAT_CHANGED;
    if (!event || typeof context.eventSource?.emit !== 'function') return false;
    await context.eventSource.emit(event, context.chatId, DISPLAY_REGEX_REFRESH);
    return matches();
  }

  async function ensureDisplayStateRegex(context, refreshMessage, document = runtime.hostDocument) {
    const settings = context?.extensionSettings;
    if (!isPlainObject(settings) || typeof context.saveSettingsDebounced !== 'function') {
      throw new Error('无法安装正文隐藏规则，酒馆设置接口尚不可用');
    }
    const rule = DISPLAY_STATE_REGEX;
    const existing = settings.regex ?? [];
    if (!Array.isArray(existing)) throw new Error('读取酒馆正则失败，未修改原有规则');
    const own = existing.filter((item) => item.id === rule.id);
    if (own.length === 1 && Object.entries(rule).every(([key, value]) => (
      JSON.stringify(own[0][key]) === JSON.stringify(value)
    ))) return { changed: false };

    let replaced = false;
    const next = [];
    for (const item of existing) {
      if (item.id !== rule.id) next.push(item);
      else if (!replaced) { next.push(cloneJson(rule)); replaced = true; }
    }
    if (!replaced) next.push(cloneJson(rule));
    settings.regex = next;
    context.saveSettingsDebounced();

    if (refreshMessage && document?.querySelectorAll) {
      for (const element of document.querySelectorAll('#chat .mes[mesid]')) {
        const id = Number(element.getAttribute('mesid'));
        const message = context.chat?.[id];
        if (!message || message.is_user || message.is_system || element.querySelector('.edit_textarea')) continue;
        if (/<(?:life_state|state_handoff|story_time)\b/i.test(String(message.mes || ''))) await refreshMessage(id);
      }
    }
    return { changed: true };
  }

  function getDirectApis() {


    return {
      getVariables: typeof getVariables === 'function' ? getVariables : undefined,
      replaceVariables: typeof replaceVariables === 'function' ? replaceVariables : undefined,
      updateVariablesWith: typeof updateVariablesWith === 'function' ? updateVariablesWith : undefined,
      getChatMessages: typeof getChatMessages === 'function' ? getChatMessages : undefined,
      injectPrompts: typeof injectPrompts === 'function' ? injectPrompts : undefined,
      uninjectPrompts: typeof uninjectPrompts === 'function' ? uninjectPrompts : undefined,
      eventOn: typeof eventOn === 'function' ? eventOn : undefined,
      tavernEvents: typeof tavern_events !== 'undefined' ? tavern_events : undefined,
      refreshOneMessage: typeof refreshOneMessage === 'function' ? refreshOneMessage : undefined,
    };
  }

  function getHelperScopes() {
    const scopes = [];
    const candidates = [root, root.TavernHelper];
    try { candidates.push(root.parent, root.parent?.TavernHelper); } catch (_) {   }
    try { candidates.push(root.top, root.top?.TavernHelper); } catch (_) {   }
    for (const candidate of candidates) {
      if (candidate && !scopes.includes(candidate)) scopes.push(candidate);
    }
    return scopes;
  }

  function findBoundFunction(scopes, name, direct) {
    if (typeof direct === 'function') return direct;
    for (const scope of scopes) {
      if (typeof scope?.[name] === 'function') return scope[name].bind(scope);
    }
    return undefined;
  }

  function findEventMap(scopes, direct) {
    if (direct) return direct;
    for (const scope of scopes) {
      if (scope?.tavern_events) return scope.tavern_events;
    }
    return {};
  }

  function resolveSillyTavernContext(scopes = getHelperScopes()) {
    for (const scope of scopes) {
      try {
        if (typeof scope?.SillyTavern?.getContext === 'function') return scope.SillyTavern.getContext();
        if (typeof scope?.getContext === 'function') {
          const context = scope.getContext();
          if (context?.generate || context?.stopGeneration) return context;
        }
      } catch (_) {   }
    }
    return null;
  }

  function tavernChatIdentity(context) {
    if (!context) return '';
    const chatId = String(context.chatId ?? '').trim();
    const groupId = String(context.groupId ?? '').trim();
    const characterId = String(context.characterId ?? '').trim();
    if (!chatId && !groupId && !characterId) return '';
    return JSON.stringify([chatId, groupId, characterId]);
  }

  function characterProfileSourceEntries(book) {
    const source = book?.entries;
    if (Array.isArray(source)) return source;
    if (isPlainObject(source)) return Object.values(source);
    return [];
  }

  function characterProfileEntryText(entry) {
    if (!isPlainObject(entry) || entry.enabled === false || entry.disable === true) return '';
    const title = String(entry.comment || entry.name || '').trim();
    const keys = [entry.keys, entry.key, entry.keysecondary, entry.secondary_keys]
      .flatMap((value) => Array.isArray(value) ? value : (typeof value === 'string' ? [value] : []))
      .map((value) => String(value).trim()).filter(Boolean);
    const content = String(entry.content || '').trim();
    if (!title && keys.length === 0 && !content) return '';
    return [title ? `条目：${title}` : '', keys.length > 0 ? `关键词：${keys.join('、')}` : '', content]
      .filter(Boolean).join('\n');
  }

  async function readCharacterProfileSourceFromContext(context) {
    const characterId = context?.characterId;
    const card = context?.characters?.[characterId];
    if (!card) throw new Error('当前没有可扫描的角色卡');
    const fields = typeof context.getCharacterCardFields === 'function'
      ? context.getCharacterCardFields({ chid: characterId })
      : {};
    const sections = [];
    const append = (label, value, limit = 24000) => {
      const text = Array.isArray(value) ? value.filter(Boolean).join('\n\n') : String(value || '').trim();
      if (text) sections.push(`## ${label}\n${text.slice(0, limit)}`);
    };
    append('角色卡名称', card.name || context.name2, 500);
    append('角色描述', fields.description);
    append('性格', fields.personality);
    append('情景', fields.scenario);
    append('开场白', fields.firstMessage);
    append('对话示例', fields.mesExamples);
    append('备选开场白', fields.alternateGreetings);
    append('作者备注', fields.creatorNotes, 12000);

    const embeddedEntries = characterProfileSourceEntries(card.data?.character_book)
      .map(characterProfileEntryText).filter(Boolean);
    append('角色世界书', embeddedEntries, 72000);

    const linkedName = String(card.data?.extensions?.world || '').trim();
    if (linkedName && typeof context.loadWorldInfo === 'function') {
      const linkedBook = await Promise.resolve(context.loadWorldInfo(linkedName));
      const linkedEntries = characterProfileSourceEntries(linkedBook).map(characterProfileEntryText).filter(Boolean);
      append(`关联世界书：${linkedName}`, linkedEntries, 72000);
    }
    const output = sections.join('\n\n').slice(0, 160000);
    if (!output) throw new Error('角色卡中没有可供扫描的资料');
    return output;
  }


  function createTavernHelperAdapter(overrides = {}) {
    if (Object.keys(overrides).length > 0) return overrides;

    const direct = getDirectApis();
    const scopes = getHelperScopes();
    const getVars = findBoundFunction(scopes, 'getVariables', direct.getVariables);
    const replaceVars = findBoundFunction(scopes, 'replaceVariables', direct.replaceVariables);
    const updateVars = findBoundFunction(scopes, 'updateVariablesWith', direct.updateVariablesWith);
    const getMessages = findBoundFunction(scopes, 'getChatMessages', direct.getChatMessages);
    const inject = findBoundFunction(scopes, 'injectPrompts', direct.injectPrompts);
    const uninject = findBoundFunction(scopes, 'uninjectPrompts', direct.uninjectPrompts);
    const onEvent = findBoundFunction(scopes, 'eventOn', direct.eventOn);
    const eventMap = findEventMap(scopes, direct.tavernEvents);
    const refreshMessage = findBoundFunction(scopes, 'refreshOneMessage', direct.refreshOneMessage);
    let promptModulePromise;
    const getPromptManager = async () => {
      if (!promptModulePromise) {
        promptModulePromise = (async () => {

          const host = getHostDocument()?.defaultView;
          if (!host?.SillyTavern || typeof host.Function !== 'function') return null;
          return host.Function('url', 'return import(url)')(new URL('/scripts/openai.js', host.location.href).href);
        })().catch(error => { logStateError('prompt_layout_api_unavailable', error); return null; });
      }
      return (await promptModulePromise)?.promptManager || null;
    };
    let lastStoreSource = 'none';
    const currentChatIdentity = () => tavernChatIdentity(resolveSillyTavernContext(scopes));
    const assertExpectedChat = (expected) => {
      if (!expected || currentChatIdentity() === expected) return;
      const error = new Error('聊天已经切换，本次操作未保存');
      error.code = 'chat_identity_changed';
      throw error;
    };

    return {
      capabilities: {
        variables: Boolean(getVars && (updateVars || replaceVars)),
        messages: Boolean(getMessages),
        injection: Boolean(inject),
        events: Boolean(onEvent && eventMap),
        promptDryRun: Boolean(resolveSillyTavernContext(scopes)?.generate),
      },

      getUserName() {
        return normalizeTrackedUserName(resolveSillyTavernContext(scopes)?.name1);
      },

      async preparePromptLayout(plan, isCurrent) {
        const manager = await getPromptManager();
        if (!isCurrent() || !manager) return () => {};
        return observeHostPromptLayout(manager, plan, isCurrent);
      },

      async hasNativeMain() {
        const manager = await getPromptManager();
        const order = manager?.getPromptOrderForCharacter?.(manager.activeCharacter);

        return Array.isArray(order) && order.some(entry => entry.identifier === 'main')
          && Boolean(manager.getPromptById?.('main'));
      },

      async ensureDisplayStateRegex(isActive = () => true) {
        const available = getHelperScopes();
        const context = resolveSillyTavernContext(available);
        const refresh = findBoundFunction(available, 'refreshOneMessage', refreshMessage);
        const result = await ensureDisplayStateRegex(context, refresh);
        if (!isActive()) return result;
        const listReady = await syncDisplayRegexList(context);
        return { ...result, listReady };
      },

      getChatIdentity() {
        return currentChatIdentity();
      },

      async readCharacterProfileSource() {
        const context = resolveSillyTavernContext(scopes);
        return readCharacterProfileSourceFromContext(context);
      },

      async generateCharacterProfileScan(source, options = {}) {
        const context = resolveSillyTavernContext(scopes);
        if (typeof context?.generateRaw !== 'function') throw new Error('当前酒馆版本不提供默认模型调用接口');
        return Promise.resolve(context.generateRaw({
          systemPrompt: CHARACTER_PROFILE_SCAN_SYSTEM_PROMPT,
          prompt: String(source || ''),
          trimNames: false,
          ...(options.compatibility === true ? {} : { responseLength: 60000, jsonSchema: CHARACTER_PROFILE_SCAN_SCHEMA }),
        }));
      },

      async generateFormatRepair(systemPrompt, payload) {
        const context = resolveSillyTavernContext(scopes);
        if (typeof context?.generateRaw !== 'function') throw new Error('当前酒馆版本不提供默认模型调用接口');
        return context.generateRaw({ systemPrompt, prompt: JSON.stringify(payload), trimNames: false });
      },

      async getStore() {
        if (!getVars) throw new Error('找不到 getVariables');
        const variables = await Promise.resolve(getVars({ type: 'chat' }));
        if (!isPlainObject(variables)) {
          lastStoreSource = 'none';
          return undefined;
        }
        if (Object.prototype.hasOwnProperty.call(variables, CONFIG.variableKey)) {
          lastStoreSource = 'ver500';
          return variables[CONFIG.variableKey];
        }
        if (Object.prototype.hasOwnProperty.call(variables, CONFIG.legacyVariableKeyV456)) {
          lastStoreSource = 'legacy_v456';
          return variables[CONFIG.legacyVariableKeyV456];
        }
        if (Object.prototype.hasOwnProperty.call(variables, CONFIG.legacyVariableKeyVNext)) {
          lastStoreSource = 'legacy_vnext';
          return variables[CONFIG.legacyVariableKeyVNext];
        }
        if (Object.prototype.hasOwnProperty.call(variables, CONFIG.legacyVariableKey)) {
          lastStoreSource = 'legacy_ver4';
          return variables[CONFIG.legacyVariableKey];
        }
        if (Object.prototype.hasOwnProperty.call(variables, CONFIG.legacyVariableKeyV3)) {
          lastStoreSource = 'legacy_v3';
          return variables[CONFIG.legacyVariableKeyV3];
        }
        lastStoreSource = 'none';
        return undefined;
      },

      async setStore(payload, expectedChatIdentity = '') {
        assertExpectedChat(expectedChatIdentity);
        if (updateVars) {
          await Promise.resolve(updateVars((variables) => {
            assertExpectedChat(expectedChatIdentity);
            const next = isPlainObject(variables) ? variables : {};
            next[CONFIG.variableKey] = payload;
            return next;
          }, { type: 'chat' }));
          lastStoreSource = 'ver500';
          return;
        }
        if (getVars && replaceVars) {
          const variables = await Promise.resolve(getVars({ type: 'chat' }));
          assertExpectedChat(expectedChatIdentity);
          const next = isPlainObject(variables) ? variables : {};
          next[CONFIG.variableKey] = payload;
          await Promise.resolve(replaceVars(next, { type: 'chat' }));
          lastStoreSource = 'ver500';
          return;
        }
        throw new Error('找不到聊天变量写入接口');
      },

      getStoreSource() {
        return lastStoreSource;
      },

      async readMessage(messageId) {
        if (!getMessages) throw new Error('找不到 getChatMessages');
        const messages = await Promise.resolve(getMessages(Number(messageId)));
        return Array.isArray(messages) ? messages[0] : undefined;
      },

      async listMessages() {
        if (!getMessages) throw new Error('找不到 getChatMessages');
        const messages = await Promise.resolve(getMessages('0-{{lastMessageId}}', { hide_state: 'all' }));
        return Array.isArray(messages) ? messages : [];
      },

      async injectOnce(content) {
        if (!inject) throw new Error('找不到 injectPrompts');
        if (uninject) await Promise.resolve(uninject([CONFIG.promptId]));
        await Promise.resolve(inject([{
          id: CONFIG.promptId,
          position: 'in_chat',
          depth: 0,
          role: 'system',
          content,
          should_scan: false,
        }], { once: true }));
      },

      clearPromptEnvelope() {
        if (uninject) return Promise.resolve(uninject([CONFIG.promptId]));
        return Promise.resolve();
      },

      async injectDynamicScan(content) {
        if (!inject) throw new Error('找不到 injectPrompts');
        if (uninject) await Promise.resolve(uninject([CONFIG.dynamicScanPromptId]));
        if (!content) return;
        await Promise.resolve(inject([{
          id: CONFIG.dynamicScanPromptId,
          position: 'none',
          depth: 0,
          role: 'system',
          content,
          should_scan: true,
        }], { once: true }));
      },

      clearDynamicScan() {
        if (uninject) return Promise.resolve(uninject([CONFIG.dynamicScanPromptId]));
        return Promise.resolve();
      },



      getNativePromptApi() {
        const context = resolveSillyTavernContext(scopes);
        const setExtensionPrompt = context?.setExtensionPrompt;
        const extensionPrompts = context?.extensionPrompts;
        return (typeof setExtensionPrompt === 'function' && isPlainObject(extensionPrompts))
          ? { setExtensionPrompt, extensionPrompts }
          : null;
      },

      async setNativePrompt(id, content, position = NATIVE_PROMPT_POSITION.IN_PROMPT, role = NATIVE_PROMPT_ROLE.SYSTEM) {
        const api = this.getNativePromptApi();
        if (!api) return false;
        api.setExtensionPrompt(id, String(content || ''), position, 0, false, role);
        return true;
      },


      async injectNativeMiddleAfterMain(content) {
        if (!inject) return false;
        if (uninject) await Promise.resolve(uninject([CONFIG.nativeMiddlePromptId]));
        await Promise.resolve(inject([{
          id: CONFIG.nativeMiddlePromptId,
          position: 'after_main',
          depth: 0,
          role: 'system',
          content: String(content || ''),
          should_scan: false,
        }], { once: true }));
        return true;
      },

      async clearNativePrompt(id) {
        const api = this.getNativePromptApi();
        if (api) {
          try { api.setExtensionPrompt(id, '', NATIVE_PROMPT_POSITION.IN_PROMPT, 0, false, NATIVE_PROMPT_ROLE.SYSTEM); } catch (_) {   }
        }
        if (uninject) {
          try { await Promise.resolve(uninject([id])); } catch (_) {   }
        }
        return true;
      },

      clearInjection() {
        if (uninject) {
          return Promise.resolve(uninject([
            CONFIG.promptId,
            CONFIG.dynamicScanPromptId,
            CONFIG.nativeMiddlePromptId,
            ...CONFIG.legacyPromptIds,
          ]));
        }
        return Promise.resolve();
      },

      generateDryRun() {
        const context = resolveSillyTavernContext(scopes);
        if (typeof context?.generate !== 'function') throw new Error('找不到 SillyTavern context.generate');
        return Promise.resolve(context.generate('normal', { automatic_trigger: true }, true));
      },

      stopGeneration() {
        const context = resolveSillyTavernContext(scopes);
        if (typeof context?.stopGeneration === 'function') context.stopGeneration();
      },

      on(eventName, listener) {
        if (!onEvent) throw new Error('找不到 eventOn');
        const actualEvent = eventMap?.[eventName];
        if (!actualEvent) throw new Error(`当前 tavern_events 不提供 ${eventName}`);
        const result = onEvent(actualEvent, listener);
        return typeof result?.stop === 'function' ? () => result.stop() : () => {};
      },
    };
  }

  const MANUAL_PROFILE_FIELDS = ['active', 'sex', 'initial_stages', 'initial_offsets', 'initial_cycle_day', 'observation_paused'];
  const MANUAL_CALC_FIELDS = ['snapshot', 'archives', 'daily_anchor_archives', 'conception_event_ledger', 'conception_decision_ledger', 'active_conception_decisions', 'sexual_desire_profiles', 'stamina_profiles'];

  function manualBranchIndex(messages) {
    const index = new Map();
    let prefix = sha256Hex('manual-state-history-v1');
    for (const message of [...(messages || [])].filter(item => Number.isInteger(item?.message_id)).sort((a,b) => a.message_id - b.message_id)) {
      const identity = { ...externalMessageIdentity(message), role: String(message.role || '') };
      prefix = sha256Hex(`${prefix}|${JSON.stringify(identity)}`);
      index.set(message.message_id, { ...identity, prefix_sha256: prefix });
    }
    return index;
  }

  function manualPatchAllowed(path) {
    if (!Array.isArray(path) || !path.every(key => typeof key === 'string' && key.length && key.length <= 250)
      || path.some(key => ['__proto__','prototype','constructor'].includes(key))) return false;
    if (path[0] === 'character_profiles') return path.length === 3 && MANUAL_PROFILE_FIELDS.includes(path[2]);
    if (path[0] === 'effect_dismissals') return path.length === 2;
    if (path[0] === 'stamina_profiles') return path.length === 2;
    if (path[0] === 'archives') return path.length === 2;
    if (['conception_decision_ledger','active_conception_decisions'].includes(path[0])) return path.length === 2;
    if (path[0] !== 'snapshot' || path[1] !== 'characters' || path.length < 3) return false;
    if (path.length === 3) return true;
    if (path[3] === 'mode') return path.length === 4;
    if (path[3] === 'needs') return path.length === 5 && NEED_KEYS.includes(path[4]);
    if (path[3] === 'effects') return path.length === 5 && EFFECT_ID_RE.test(path[4]) && path[4] !== CYCLE_PRESENCE_KEY;
    if (path[3] === 'reproductive') return path.length === 4 || (path.length === 5 && REPRODUCTIVE_FIELDS.includes(path[4]))
      || (path.length === 6 && ['pregnancy','conception'].includes(path[4]) && ['user_awareness','character_awareness'].includes(path[5]));
    return false;
  }

  function manualHistory(store) {
    return (Array.isArray(store?.manual_state_edits) ? store.manual_state_edits : []).filter(row =>
      Number.isSafeInteger(row?.seq) && row.seq > 0 && Array.isArray(row.patches)
      && (row.anchor === null || (Number.isInteger(row.anchor?.message_id) && typeof row.anchor.content_sha256 === 'string' && typeof row.anchor.prefix_sha256 === 'string')))
      .map(row => ({ ...row, patches: row.patches.filter(p => manualPatchAllowed(p?.path) && typeof p.before_exists === 'boolean' && typeof p.after_exists === 'boolean'
        && (!p.before_exists || Object.prototype.hasOwnProperty.call(p,'before')) && (!p.after_exists || Object.prototype.hasOwnProperty.call(p,'after'))) }))
      .filter(row => row.patches.length).sort((a,b) => a.seq - b.seq);
  }

  function manualRowActive(row, index, limit = Infinity) {
    if (row.anchor === null) return true;
    if (row.anchor.message_id > limit) return false;
    const message = index.get(row.anchor.message_id);
    return message && message.swipe_id === row.anchor.swipe_id && message.role === row.anchor.role
      && message.content_sha256 === row.anchor.content_sha256 && message.prefix_sha256 === row.anchor.prefix_sha256;
  }

  function manualProjectionKey(store, messages, limit = Infinity) {
    const rows = manualHistory(store);
    if (!rows.length) return '';
    const index = manualBranchIndex(messages);
    const active = rows.filter(row => manualRowActive(row, index, limit));
    const end = Math.max(-1, Math.min(limit, store?.source_message_id ?? -1), ...active.map(row => row.anchor?.message_id ?? -1));
    return sha256Hex(JSON.stringify([index.get(end)?.prefix_sha256 || '', active.map(row => [row.seq,row.patches])]));
  }

  function manualValue(object, path) {
    let parent = object;
    for (const key of path) {
      if (!isPlainObject(parent) || !Object.prototype.hasOwnProperty.call(parent, key)) return { exists:false };
      parent = parent[key];
    }
    return { exists:true, value:cloneJson(parent) };
  }

  function writeManualValue(object, path, exists, value) {
    let parent = object;
    for (const key of path.slice(0,-1)) {
      if (!isPlainObject(parent[key])) {
        if (!exists) return;
        parent[key] = {};
      }
      parent = parent[key];
    }
    if (exists) parent[path.at(-1)] = cloneJson(value);
    else delete parent[path.at(-1)];
  }

  function manualStatePatches(before, after) {
    const patches = [];
    const push = path => {
      if (!manualPatchAllowed(path)) return;
      const a=manualValue(before,path), b=manualValue(after,path);
      if (a.exists===b.exists && JSON.stringify(a.value)===JSON.stringify(b.value)) return;
      const patch={path,before_exists:a.exists,after_exists:b.exists,...(a.exists?{before:a.value}:{}),...(b.exists?{after:b.value}:{})};
      if (path[0]==='snapshot' && path[3]==='needs' && b.exists) {
        for (const field of ['elapsed','awake_for']) { delete patch.after?.[field]; delete patch.before?.[field]; }
        const field=path[4]==='sleep'?'wake_at':'last_at';
        const now=timelineToHours(after.snapshot?.timeline), anchor=storyAnchorToHours(b.value?.[field]);
        if (now!==null && anchor!==null) patch.anchor_offset={field,hours:now-anchor};
      }
      if (path[0]==='snapshot' && path[4]==='conception' && path.length===6) {
        const window=before.snapshot?.characters?.[path[2]]?.reproductive?.conception;
        patch.window={id:window?.window_id,start:window?.window_started_at};
      }
      patches.push(patch);
    };
    const names=new Set([...Object.keys(before.snapshot?.characters||{}),...Object.keys(after.snapshot?.characters||{})]);
    for (const name of names) {
      const a=before.snapshot?.characters?.[name], b=after.snapshot?.characters?.[name], root=['snapshot','characters',name];
      if (!a||!b) { push(root); continue; }
      push([...root,'mode']);
      for(const key of NEED_KEYS) push([...root,'needs',key]);
      for(const key of new Set([...Object.keys(a.effects||{}),...Object.keys(b.effects||{})])) push([...root,'effects',key]);
      if(!isPlainObject(a.reproductive)||!isPlainObject(b.reproductive)) push([...root,'reproductive']);
      else {
        push([...root,'reproductive','menstrual_cycle']);
        for(const kind of ['pregnancy','conception']) {
          if(!a.reproductive[kind]||!b.reproductive[kind]) push([...root,'reproductive',kind]);
          else for(const field of ['character_awareness','user_awareness']) push([...root,'reproductive',kind,field]);
        }
      }
    }
    for(const name of new Set([...Object.keys(before.character_profiles||{}),...Object.keys(after.character_profiles||{})])) {
      for(const field of MANUAL_PROFILE_FIELDS) push(['character_profiles',name,field]);
    }
    for(const key of new Set([...Object.keys(before.effect_dismissals||{}),...Object.keys(after.effect_dismissals||{})])) push(['effect_dismissals',key]);
    for(const name of new Set([...Object.keys(before.stamina_profiles||{}),...Object.keys(after.stamina_profiles||{})])) push(['stamina_profiles',name]);
    for(const key of new Set([...Object.keys(before.conception_decision_ledger||{}),...Object.keys(after.conception_decision_ledger||{})])) {
      if ((before.conception_decision_ledger?.[key]?.manual || after.conception_decision_ledger?.[key]?.manual)
        && JSON.stringify(before.conception_decision_ledger?.[key])!==JSON.stringify(after.conception_decision_ledger?.[key])) {
        push(['conception_decision_ledger',key]);
        const name=after.conception_decision_ledger?.[key]?.character || before.conception_decision_ledger?.[key]?.character;
        if(name && !patches.some(p=>p.path[0]==='archives'&&p.path[1]===name))push(['archives',name]);
      }
    }
    for(const id of new Set([...Object.keys(before.active_conception_decisions||{}),...Object.keys(after.active_conception_decisions||{})])) {
      if (before.conception_decision_ledger?.[before.active_conception_decisions?.[id]]?.manual || after.conception_decision_ledger?.[after.active_conception_decisions?.[id]]?.manual) push(['active_conception_decisions',id]);
    }
    return patches;
  }

  function applyManualRow(store, row, direction = 'after', contextOnly = false) {
    const patches=direction==='before'?[...row.patches].reverse():row.patches;
    for(const patch of patches) {
      if(contextOnly && ['snapshot','archives','conception_decision_ledger','active_conception_decisions'].includes(patch.path[0])) continue;
      const exists=patch[`${direction}_exists`]; let value=cloneJson(patch[direction]);
      if(direction==='after' && patch.path[0]==='snapshot') {
        if(!store.snapshot && exists) store.snapshot={version:5,timeline:cloneJson(row.timeline)||null,scene:null,characters:{}};

        if(patch.path.length>3 && !store.snapshot?.characters?.[patch.path[2]]) continue;
        if(patch.window) {
          const current=store.snapshot?.characters?.[patch.path[2]]?.reproductive?.conception;
          if(!current || current.window_id!==patch.window.id || current.window_started_at!==patch.window.start) continue;
        }
        if(patch.anchor_offset && isPlainObject(value)) {
          const now=timelineToHours(store.snapshot?.timeline);
          if(now!==null) {
            const anchor=hoursToStoryAnchor(now-patch.anchor_offset.hours);
            if(anchor) value[patch.anchor_offset.field]=anchor;
            else delete value[patch.anchor_offset.field];
          }
        }
      }
      if(direction==='after' && patch.path[0]==='effect_dismissals' && isPlainObject(value)) value.dismissed_at=timelineToStoryAnchor(store.snapshot?.timeline)||value.dismissed_at||null;
      writeManualValue(store,patch.path,exists,value);
      if(direction==='after' && patch.path[0]==='snapshot' && patch.path[4]==='conception' && patch.path.length===6 && exists) {
        const current=store.snapshot?.characters?.[patch.path[2]]?.reproductive?.conception;
        if(current && isPlainObject(store.conception_event_ledger)) setConceptionLedgerAwareness(store.conception_event_ledger,patch.path[2],current,patch.path[5],value);
      }
    }
    if(store.snapshot?.characters && !Object.keys(store.snapshot.characters).length && store.snapshot.scene===null) store.snapshot=null;
    return store;
  }

  function manualReplayContext(store) {
    const context={snapshot:null,character_profiles:cloneJson(store?.character_profiles||{}),effect_dismissals:cloneJson(store?.effect_dismissals||{})};
    for(const row of manualHistory(store).reverse()) applyManualRow(context,row,'before',true);

    for(const profile of Object.values(context.character_profiles)) if(profile.active===undefined) profile.active=false;
    return context;
  }

  function manualRowsAt(store, messages, first=-1, last=Infinity, branchIndex=null) {
    const rows=manualHistory(store);
    if(!rows.length) return [];
    const index=branchIndex||manualBranchIndex(messages);
    return rows.filter(row=>manualRowActive(row,index,last) && (row.anchor?.message_id??-1)>first)
      .sort((a,b)=>(a.anchor?.message_id??-1)-(b.anchor?.message_id??-1)||a.seq-b.seq);
  }

  function normalizeManualProjection(store, previous = store.snapshot) {
    const modules=modulesWithPlayRequirements(modulesFromStore(store,'vnext'),playNarrativeRouteIds(store.active_play_routes||[],store.snapshot));
    let snapshot=ensureActiveCharacterProfiles(store.snapshot,store.character_profiles,modules,previous);
    const prepared=prepareLifeState(snapshot,modules,store.character_profiles,previous);
    if(!prepared.valid) throw new Error(`手动修改后的状态无法恢复：${prepared.errors.join('；')}`);
    snapshot=applyEffectDismissals(prepared.snapshot,store.effect_dismissals).snapshot;
    store.snapshot=reconcileCyclePresence(snapshot,previous,store.cycle_presence_enabled===true,modules);
    store.has_valid_snapshot=store.snapshot!==null;
    store.daily_anchor_archives=updateDailyAnchorArchives(store.daily_anchor_archives,store.snapshot,modules,{}, {pruneMissing:modules.daily_needs.length>0});
    if(modules.reproductive) store.archives=applyArchiveOperations(store.archives,store.archive_tombstones,store.snapshot,[],{source_message_id:store.source_message_id,source_swipe_id:store.source_swipe_id}).archives;
    const manualNotices=Object.values(sanitizeConceptionDecisionLedger(store.conception_decision_ledger)).filter(entry=>entry.manual);
    store.conception_event_ledger=reconcileConceptionAwarenessLedger(store.conception_event_ledger||{},store.snapshot,manualNotices);
    return store;
  }

  function manualCanonicalStore(store) {
    const clean={...cloneJson(store)};
    const pending=store?.manual_pending_base;
    if(pending && pending.source_message_id===(store.source_message_id??null)) {
      for(const field of MANUAL_CALC_FIELDS) if(Object.prototype.hasOwnProperty.call(pending,field)) clean[field]=cloneJson(pending[field]);
      const future=manualHistory(store).filter(row=>(row.anchor?.message_id??-1)>(store.source_message_id??-1));
      for(const row of future.reverse()) applyManualRow(clean,row,'before',true);
    }
    delete clean.manual_pending_base;
    clean.has_valid_snapshot=clean.snapshot!==null && clean.snapshot!==undefined;
    return clean;
  }

  function projectPendingManualEdits(store, messages) {
    if(!manualHistory(store).length) return store;
    const next=cloneJson(store); delete next.manual_pending_base;
    const source=store.source_message_id??-1;
    const rows=manualRowsAt(store,messages,source);
    if(rows.length) {
      if(sanitizeExternalPendingQueue(store.external_pending_queue).length) next.manual_pending_base={source_message_id:store.source_message_id??null,...Object.fromEntries(MANUAL_CALC_FIELDS.map(key=>[key,cloneJson(store[key]??null)]))};
      for(const row of rows) applyManualRow(next,row);
      normalizeManualProjection(next,store.snapshot);
    }
    next.manual_projection_key=manualProjectionKey(next,messages);
    return next;
  }

  async function commitManualStateStore(adapter, base, next, kind='state', expectedIdentity='') {
    const identity=expectedIdentity||operationChatIdentity(adapter);
    try {
    if(!adapter?.getStore || !adapter?.setStore) throw new Error('缺少可靠的状态读取或保存接口，修改尚未保存。');
    const patches=manualStatePatches(base,next);
    if(patches.length && runtime.generationActive) throw new Error('保存时正文仍在生成，修改尚未保存；本轮结束后可重试，填写内容已保留。');
    const messages=adapter.listMessages?await adapter.listMessages():[];
    if(!Array.isArray(messages)) throw new Error('无法读取当前聊天分支，修改尚未保存，请刷新后重试。');
    const index=manualBranchIndex(messages), anchor=[...index.values()].at(-1)||null;
    if(!anchor && Number.isInteger(base.source_message_id) && !adapter.listMessages) throw new Error('无法定位当前楼层，请刷新后再修改。');
    assertOperationChatUnchanged(adapter,identity);
    if(adapter.getStore && JSON.stringify(await adapter.getStore()||{})!==JSON.stringify(base)) throw new Error('状态刚刚发生变化，修改尚未保存，请刷新后重试。');
    const commit={...next};
    if(patches.length) {
      const rows=manualHistory(base),seq=Math.max(0,...rows.map(row=>row.seq))+1;
      commit.manual_state_edits=[...rows,{seq,kind,anchor,timeline:cloneJson(next.snapshot?.timeline)||null,patches}];

      commit.external_manual_effect_edits=base.external_manual_effect_edits||[];
      if((sanitizeExternalPendingQueue(base.external_pending_queue).length || normalizeWorkflowMode(base.state_workflow_mode)===WORKFLOW_MODES.EXTERNAL)
        && (anchor?.message_id??-1)>(base.source_message_id??-1)) {
        commit.manual_pending_base=base.manual_pending_base||{source_message_id:base.source_message_id??null,...Object.fromEntries(MANUAL_CALC_FIELDS.map(key=>[key,cloneJson(base[key]??null)]))};
      }
      commit.manual_projection_key=manualProjectionKey(commit,messages);
    }
    if(adapter.listMessages && JSON.stringify([...manualBranchIndex(await adapter.listMessages()).values()])!==JSON.stringify([...index.values()])) throw new Error('聊天分支已变化，修改尚未保存，请重试。');
    assertOperationChatUnchanged(adapter,identity);
    await adapter.setStore(commit,identity);
    assertOperationChatUnchanged(adapter,identity);
    setManualSaveNotice('',adapter,identity);
    return commit;
    } catch(error) {
      const message=String(error?.message||'');
      setManualSaveNotice(/尚未保存|正文正在生成|分支已变化/.test(message)?message:'本次修改未保存，填写内容已保留，请稍后重试。',adapter,identity);
      throw error;
    }
  }

  function setManualSaveNotice(message,adapter=runtime.adapter,identity='') {
    if(identity && operationChatIdentity(adapter)!==identity) return;
    runtime.manualSaveError=message;
    const notice=(runtime.hostDocument||getHostDocument())?.getElementById(CONFIG.panelId)?.querySelector('.ls-manual-save-notice');
    if(notice) { notice.textContent=message; notice.hidden=!message; }
  }

  async function writeStateStore(adapter, base, next, options={}) {
    if(options.manualEdit) return commitManualStateStore(adapter,options.manualBase||base,next,options.manualEdit,options.expectedChatIdentity);
    if(options.clearManualPending) next.manual_pending_base=null;
    if(options.projectManualPending && adapter.listMessages) next=projectPendingManualEdits(next,await adapter.listMessages());
    if(manualHistory(next).length && adapter.listMessages) next.manual_projection_key=manualProjectionKey(next,await adapter.listMessages(),options.manualProjectionLimit??Infinity);
    await adapter.setStore(next,options.expectedChatIdentity||'');
    return next;
  }

  function manualTurnPatches(store,messages,start,end,branchIndex=null) {
    return manualRowsAt(store,messages,start,end,branchIndex).flatMap(row=>row.patches.filter(p=>['snapshot','stamina_profiles'].includes(p.path[0])).map(p=>({path:p.path,exists:p.after_exists,
      ...(p.after_exists?{value:p.path[0]==='stamina_profiles'?{score:p.after.score,notes:p.after.notes}:p.after}:{}),...(p.anchor_offset?{anchor_offset:p.anchor_offset}:{}),...(p.window?{window:p.window}:{})})));
  }

  function syncManualProjectionRuntime(store) {
    runtime.characterProfiles=sanitizeCharacterProfiles(store.character_profiles);
    runtime.effectDismissals=sanitizeEffectDismissals(store.effect_dismissals);
    runtime.archives=sanitizeArchiveMap(store.archives);
    runtime.dailyAnchorArchives=sanitizeDailyAnchorArchives(store.daily_anchor_archives);
    runtime.conceptionEventLedger=sanitizeConceptionEventLedger(store.conception_event_ledger);
    runtime.conceptionDecisionLedger=sanitizeConceptionDecisionLedger(store.conception_decision_ledger);
    runtime.activeConceptionDecisions=sanitizeActiveConceptionDecisions(store.active_conception_decisions,runtime.conceptionDecisionLedger);
    runtime.staminaProfiles=sanitizeStaminaProfiles(store.stamina_profiles);
  }
  function logStateError(code, error, level = 'warn') {
    const message = error instanceof Error ? error.message : String(error);
    const entry = {
      time: new Date().toLocaleTimeString(),
      code,
      message,
    };
    runtime.logs.push(entry);
    if (runtime.logs.length > CONFIG.maxDebugEntries) runtime.logs.shift();
    const logger = level === 'error' ? console.error : level === 'info' ? console.info : console.warn;
    logger(`[LifeState:${code}] ${message}`);
    refreshDebugPanel();
  }

  function logCleanupWarnings(warnings, context = 'snapshot') {
    for (const warning of warnings || []) {
      logStateError('snapshot_cleaned', `${context}：${warning}`);
    }
  }

  function sanitizeArchiveMap(input) {
    const source = isPlainObject(input) ? input : {};
    const next = {};
    for (const [name, entry] of Object.entries(source)) {
      if (name.trim() === '' || !isPlainObject(entry?.reproductive)) continue;
      const prepared = prepareLifeState({
        version: 5,
        timeline: null,
        scene: null,
        characters: {
          [name]: {
            mode: 'detailed',
            effects: {},
            reproductive: entry.reproductive,
          },
        },
      }, { daily_needs: [], reproductive: true });
      if (!prepared.valid || !isPlainObject(prepared.snapshot?.characters?.[name]?.reproductive)) continue;
      next[name] = {
        reproductive: cloneJson(prepared.snapshot.characters[name].reproductive),
        timeline: sanitizeArchiveTimeline(entry.timeline),
        source_message_id: Number.isInteger(entry.source_message_id) ? entry.source_message_id : null,
        source_swipe_id: Number.isInteger(entry.source_swipe_id) ? entry.source_swipe_id : null,
        saved_at: typeof entry.saved_at === 'string' ? entry.saved_at : null,
      };
    }
    return next;
  }

  function sanitizeArchiveTimeline(timeline) {
    if (!isPlainObject(timeline) || !Number.isInteger(timeline.day) || timeline.day < 1) return null;
    if (typeof timeline.time !== 'string' || !/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(timeline.time)) return null;
    return { day: timeline.day, time: timeline.time };
  }

  function buildDormantReproductiveHint(archives, snapshot = null, cycleEnabled = true, excludedName = '') {
    if (!cycleEnabled) return '';
    const source = sanitizeArchiveMap(archives);
    const activeNames = new Set(isPlainObject(snapshot?.characters) ? Object.keys(snapshot.characters) : []);
    if (excludedName) activeNames.add(excludedName);
    const lines = [];
    for (const [rawName, entry] of Object.entries(source)) {
      if (activeNames.has(rawName)) continue;
      const name = String(rawName).replace(/\s+/g, ' ').trim();
      const reproductive = entry.reproductive;
      const anchor = entry.timeline ? `D${entry.timeline.day} ${entry.timeline.time}` : '记录时点未定';
      const cycle = reproductive?.menstrual_cycle;
      if (isPlainObject(cycle)) {
        const day = Number.isInteger(cycle.cycle_day) ? `第${cycle.cycle_day}日` : '周期日待校准';
        const awareness = cycle.user_awareness === '已知' ? 'User已知' : 'User未知';
        lines.push(`${name}：周期在 ${anchor} 记录为${day}，${awareness}。`);
      }
      const pregnancy = reproductive?.pregnancy;
      if (isPlainObject(pregnancy)) {
        const day = Number.isInteger(pregnancy.gestation_days) ? `妊娠第${pregnancy.gestation_days}日` : '孕期天数待校准';
        const confirmation = pregnancy.confirmation === '已确认' ? '已确认' : '待确认';
        const awareness = pregnancy.user_awareness === '已知' ? 'User已知' : 'User未知';
        lines.push(`${name}：孕期在 ${anchor} 记录为${day}，${confirmation}，${awareness}。`);
      }
    }
    if (lines.length === 0) return '';
    return `\n\n离场生殖时标：以下仅为角色离场时的生殖日期锚点，不是当前状态。角色未重新进入可观察范围时不得写回活动 characters，也不得据此描写当前身体。角色重新进入时，先用当前可靠 timeline 与记录时点计算完整经过天数，再更新 cycle_day 或 gestation_days；存在明确来潮、检查或其他权威事实时优先服从该事实。\n${lines.join('\n')}`;
  }

  function sanitizeArchiveTombstones(input) {
    const source = isPlainObject(input) ? input : {};
    const next = {};
    for (const [name, entry] of Object.entries(source)) {
      if (name.trim() === '' || !isPlainObject(entry)) continue;
      next[name] = {
        source_message_id: Number.isInteger(entry.source_message_id) ? entry.source_message_id : null,
        source_swipe_id: Number.isInteger(entry.source_swipe_id) ? entry.source_swipe_id : null,
        deleted_at: typeof entry.deleted_at === 'string' ? entry.deleted_at : null,
        manual: entry.manual === true,
      };
    }
    return next;
  }

  function applyArchiveOperations(archives, tombstones, snapshot, archiveDeletions = [], provenance = {}, reproductiveModuleDeletions = []) {
    const nextArchives = sanitizeArchiveMap(archives);
    const nextTombstones = sanitizeArchiveTombstones(tombstones);
    const sourceMessageId = Number.isInteger(provenance.source_message_id) ? provenance.source_message_id : null;
    const sourceSwipeId = Number.isInteger(provenance.source_swipe_id) ? provenance.source_swipe_id : null;

    for (const name of archiveDeletions || []) {
      delete nextArchives[name];
      const existing = nextTombstones[name];
      const mayReplace = !existing
        || existing.source_message_id === null
        || (sourceMessageId !== null && sourceMessageId > existing.source_message_id)
        || (sourceMessageId === existing.source_message_id && provenance.manual === true);
      if (mayReplace) {
        nextTombstones[name] = {
          source_message_id: sourceMessageId,
          source_swipe_id: sourceSwipeId,
          deleted_at: new Date().toISOString(),
          manual: provenance.manual === true,
        };
      }
      logStateError('archive_deleted', `已明确删除角色“${name}”的生殖档案`, 'info');
    }

    for (const deletion of reproductiveModuleDeletions || []) {
      const name = deletion?.name;
      const moduleName = deletion?.moduleName;
      if (!name || !REPRODUCTIVE_FIELDS.includes(moduleName) || !isPlainObject(nextArchives[name]?.reproductive)) continue;
      if (!Object.prototype.hasOwnProperty.call(nextArchives[name].reproductive, moduleName)) continue;
      delete nextArchives[name].reproductive[moduleName];
      if (Object.keys(nextArchives[name].reproductive).length === 0) delete nextArchives[name];
      logStateError('reproductive_module_cleared', `已终止角色“${name}”的 ${moduleName} 状态`, 'info');
    }

    if (isPlainObject(snapshot?.characters)) {
      for (const [name, character] of Object.entries(snapshot.characters)) {
        if (!isPlainObject(character?.reproductive) || Object.keys(character.reproductive).length === 0) continue;
        const tombstone = nextTombstones[name];
        const newerThanDeletion = !tombstone
          || (sourceMessageId !== null && tombstone.source_message_id !== null && sourceMessageId > tombstone.source_message_id);
        if (!newerThanDeletion) continue;
        delete nextTombstones[name];
        nextArchives[name] = {
          reproductive: cloneJson(character.reproductive),
          timeline: sanitizeArchiveTimeline(snapshot.timeline),
          source_message_id: sourceMessageId,
          source_swipe_id: sourceSwipeId,
          saved_at: new Date().toISOString(),
        };
      }
    }
    return { archives: nextArchives, tombstones: nextTombstones };
  }

  function updateArchivesFromSnapshot(archives, snapshot, provenance = {}) {
    return applyArchiveOperations(archives, {}, snapshot, [], provenance).archives;
  }

  function restoreRequestFromStore(stored, archives) {
    const name = typeof stored?.pending_restore?.name === 'string' ? stored.pending_restore.name : '';
    if (!name || !isPlainObject(archives[name]?.reproductive)) return null;
    return { name };
  }

  function contentSettingsFromStore(stored, source = 'none') {
    return {
      modules: normalizeModules(modulesFromStore(stored, source)),
      user_tracking_enabled: stored?.user_tracking_enabled === true,
      nsfw_enhancement_enabled: stored?.nsfw_enhancement_enabled !== false,
      body_expression_enabled: stored?.body_expression_enabled === true,
      cycle_presence_enabled: stored?.cycle_presence_enabled === true,
      effect_mode: normalizeEffectMode(stored?.effect_mode),
    };
  }

  function loadContentDefaults(storage) {
    try {
      storage ??= root.localStorage;
      const value = JSON.parse(storage?.getItem(CONFIG.contentDefaultsKey) || 'null');
      const settings = value?.settings;
      if (value?.version !== 1 || !isPlainObject(settings) || !isPlainObject(settings.modules)
        || !Array.isArray(settings.modules.daily_needs) || settings.modules.daily_needs.some(key => !NEED_KEYS.includes(key))
        || ['reproductive', 'sexual_desire'].some(key => typeof settings.modules[key] !== 'boolean')
        || ['user_tracking_enabled', 'nsfw_enhancement_enabled', 'body_expression_enabled', 'cycle_presence_enabled'].some(key => typeof settings[key] !== 'boolean')
        || !['strict', 'open'].includes(settings.effect_mode)) return null;
      return contentSettingsFromStore(settings);
    } catch (_) { return null; }
  }

  async function saveContentDefaults(adapter = runtime.adapter, storage) {
    if (!adapter?.getStore) throw new Error('无法读取当前聊天设置，默认设置未保存。');
    const identity = operationChatIdentity(adapter);
    if (typeof adapter.getChatIdentity === 'function' && !identity) throw new Error('请先打开一个聊天，再保存它的内容设置。');
    const stored = await adapter.getStore();
    assertOperationChatUnchanged(adapter, identity);
    if (stored != null && !isPlainObject(stored)) throw new Error('当前聊天设置不可读取，默认设置未保存。');
    const settings = contentSettingsFromStore(stored, adapter.getStoreSource?.());
    storage ??= root.localStorage;
    if (!storage?.setItem || !storage?.getItem) throw new Error('浏览器无法保存默认设置，请检查本地存储权限。');
    const text = JSON.stringify({ version: 1, settings });
    storage.setItem(CONFIG.contentDefaultsKey, text);
    if (storage.getItem(CONFIG.contentDefaultsKey) !== text) throw new Error('默认设置未保存成功，请检查浏览器存储权限。');
    return settings;
  }

  function clearContentDefaults(storage) {
    storage ??= root.localStorage;
    if (!storage?.removeItem || !storage?.getItem) throw new Error('浏览器无法清除默认设置，请检查本地存储权限。');
    storage.removeItem(CONFIG.contentDefaultsKey);
    if (storage.getItem(CONFIG.contentDefaultsKey) != null) throw new Error('默认设置尚未清除，请重试。');
  }

  const contentDefaultsInitializations = new WeakMap();
  async function readStoreWithContentDefaults(adapter, storage) {
    if (!adapter?.getStore) return undefined;
    const identity = operationChatIdentity(adapter);
    const owner = adapter[STATE_OPERATION_SOURCE] || adapter;
    const pending = contentDefaultsInitializations.get(owner);
    if (pending?.identity === identity && pending.epoch === runtime.stateOperationEpoch) return pending.promise;
    const task = { identity, epoch: runtime.stateOperationEpoch };
    task.promise = (async () => {
      const stored = await adapter.getStore();
      assertOperationChatUnchanged(adapter, identity);
      const empty = value => value == null || (isPlainObject(value) && Object.keys(value).length === 0);
      if (!empty(stored) || (typeof adapter.getChatIdentity === 'function' && !identity)
        || String(adapter.getStoreSource?.() || '').startsWith('legacy')) return stored;
      const settings = loadContentDefaults(storage);
      if (!settings || !adapter.setStore) return stored;
      const trackedName = settings.user_tracking_enabled ? await resolveCurrentUserName(adapter) : '';
      assertOperationChatUnchanged(adapter, identity);

      const latest = await adapter.getStore();
      assertOperationChatUnchanged(adapter, identity);
      if (!empty(latest) || String(adapter.getStoreSource?.() || '').startsWith('legacy')) return latest;
      const next = { store_version: 5, ...settings, content_defaults_applied: true,
        tracked_user_name: normalizeTrackedUserName(trackedName), saved_at: new Date().toISOString() };
      await adapter.setStore(next, identity);
      assertOperationChatUnchanged(adapter, identity);
