  async function setWorkflowMode(mode, adapter = runtime.adapter, options = {}) {
    if (runtime.externalBackgroundJob && !options.discardExternalPending) throw new Error('后台分析正在进行；可稍后切换，或选择“停止外接并切回内置”。');
    cancelInlineFormatRepair();
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const next = normalizeWorkflowMode(mode);
    const discardPending = options.discardExternalPending === true && next === WORKFLOW_MODES.INLINE;
    if (runtime.externalControl.stopping && !discardPending) return runtime.workflowMode;
    if (runtime.generationActive) {
      runtime.requestedWorkflowMode = next;
      runtime.externalError = '本轮完成后切换。';
      refreshStatePanel();
      return runtime.workflowMode;
    }
    const expectedChatIdentity = operationChatIdentity(adapter);
    let current = adapter?.getStore ? await Promise.resolve(adapter.getStore()) : undefined;
    const previousMode = normalizeWorkflowMode(current?.state_workflow_mode);
    if (next === WORKFLOW_MODES.EXTERNAL && normalizeExternalAnalysisMode(current?.external_analysis_mode) === 'independent'
      && !independentCleaningReady(current)) {
      await beginIndependentSetup(adapter);
      return runtime.workflowMode;
    }
    if (previousMode === WORKFLOW_MODES.EXTERNAL && next !== previousMode && !discardPending) {
      const settled = await flushExternalPending(adapter);
      if (!settled.ok) throw new Error('待更新正文还未结算成功，已保留外接模式；可重试，或选择“停止外接并切回内置”。');
      current = await adapter.getStore();
    }
    assertOperationChatUnchanged(adapter, expectedChatIdentity);
    const base = isPlainObject(current) ? current : {};
    const storeSource = adapter?.getStoreSource?.() || 'none';
    const modules = isPlainObject(base.modules) || String(storeSource).startsWith('legacy')
      ? modulesFromStore(base, storeSource)
      : { ...MODULE_DEFAULTS };
    const activePlayIds = normalizeActivePlayIds(base.active_play_routes);
    const effectiveModules = modulesWithPlayRequirements(modules, activePlayIds);
    const externalPendingQueue = discardPending ? [] : sanitizeExternalPendingQueue(base.external_pending_queue);
    const messages = adapter.listMessages ? await adapter.listMessages() : [];
    const skipped = discardPending ? messages.filter(item => item.role === 'assistant'
      && (Number(item.message_id) > Number(base.source_message_id ?? -1)
        || sanitizeExternalPendingQueue(base.external_pending_queue).some(entry => externalMessageMatches(item, entry)))) : [];
    assertOperationChatUnchanged(adapter, expectedChatIdentity);
    await adapter.setStore({
      ...base,
      store_version: 5,
      state_workflow_mode: next,
      external_independent_ranges: updateIndependentRanges(base, messages.filter(item => item.role === 'assistant').at(-1)?.message_id ?? -1,
        next === WORKFLOW_MODES.EXTERNAL && normalizeExternalAnalysisMode(base.external_analysis_mode) === 'independent'),
      modules,
      cycle_enabled: effectiveModules.reproductive,
      external_pending_queue: externalPendingQueue,
      ...(discardPending ? {
        manual_pending_base: null,
        external_start_after: messages.filter(item => item.role === 'assistant').at(-1)?.message_id ?? -1,
        external_skipped_turns: [...sanitizeExternalPendingQueue(base.external_skipped_turns).map(externalMessageIdentity), ...skipped.map(externalMessageIdentity)].slice(-EXTERNAL_LEDGER_LIMIT),
      } : {}),
      ...(next === WORKFLOW_MODES.EXTERNAL && previousMode !== next
        ? { external_start_after: messages.filter(item => item.role === 'assistant').at(-1)?.message_id ?? -1 } : {}),
      saved_at: new Date().toISOString(),
    }, expectedChatIdentity);
    runtime.workflowMode = next;
    runtime.independentSetup = false;
    await refreshStoryClockContext(adapter, messages);
    runtime.generationMode = null;
    runtime.externalStateLedger = sanitizeExternalStateLedger(base.external_state_ledger);
    runtime.externalUpdateEvery = normalizeExternalUpdateEvery(base.external_update_every);
    runtime.externalBackgroundEnabled = base.external_background_enabled === true;
    runtime.modules = modules;
    runtime.cycleEnabled = effectiveModules.reproductive;
    runtime.externalStatus = 'idle';
    runtime.externalError = '';
    runtime.externalContentFilterNotice = '';
    if (next !== WORKFLOW_MODES.EXTERNAL) runtime.externalResponseOpen = false;
    runtime.externalPreflightResult = null;
    runtime.externalPendingQueue = externalPendingQueue;
    runtime.externalPendingMessageId = externalPendingQueue[0]?.message_id ?? null;
    if (next === WORKFLOW_MODES.EXTERNAL) await ensureExternalPlayLabels(adapter);
    await releasePromptRequest(adapter);
    logStateError('workflow_mode_changed', next === WORKFLOW_MODES.EXTERNAL ? '本聊天已切换为外接工作流。' : '本聊天已切换为内置工作流。', 'info');
    refreshStatePanel();
    return next;
  }

  async function setExternalPreflightEnabled(enabled, adapter = runtime.adapter) {
