  function shouldRetryCharacterProfileScan(error) {
    const message = [typeof error === 'string' ? error : error?.message, error?.status, error?.code, error?.error?.message].filter(Boolean).join(' ');
    if (/401|403|429|quota|rate.limit|unauthori|forbidden|api.?key|credit|balance|cancel|abort|network|timeout/i.test(message)) return false;
    return /\b400\b|INVALID_ARGUMENT|json.?schema|response.?schema|response.?format|structured.?output/i.test(message);
  }

  function resetCharacterProfileScan() {
    runtime.independentProfileController?.abort();
    runtime.independentProfileController = null;
    if (runtime.scanReturnView) closeExternalResponse(runtime.hostDocument);
    runtime.characterProfileScanReport = null;
    runtime.characterProfileScanStatus = 'idle';
    runtime.characterProfileScanError = '';
    runtime.characterProfileScanRetrying = false;
    runtime.characterProfileScanActive = false;
  }

  function beginCharacterProfileScan(source) {
    if (runtime.generationActive || runtime.characterProfileScanActive) throw new Error('请等当前任务结束后再扫描。');
    if (runtime.scanReturnView) closeExternalResponse(runtime.hostDocument);
    const report = { source, raw: '', error: '', redacted: false, serialized: false };
    runtime.characterProfileScanReport = report;
    runtime.characterProfileScanStatus = 'scanning';
    runtime.characterProfileScanError = '';
    runtime.characterProfileScanRetrying = false;
    runtime.characterProfileScanActive = true;
    refreshStatePanel();
    return report;
  }

  function scanReportText(value, report) {
    let text = typeof value === 'string' ? value : value == null ? '' : JSON.stringify(value, null, 2);
    const key = String(runtime.externalApiConfig?.api_key || '');
    if (key && text.includes(key)) { text = text.split(key).join('[密钥已隐藏]'); report.redacted = true; }
    return text;
  }

  function recordCharacterProfileScan(report, value) {
    if (runtime.characterProfileScanReport !== report) return;
    report.serialized = typeof value !== 'string' && value != null;
    report.raw = scanReportText(value, report);
  }

  function failCharacterProfileScan(report, error) {
    if (runtime.characterProfileScanReport !== report) return;
    report.error = scanReportText(error?.message || String(error), report);
    runtime.characterProfileScanStatus = 'error';
    runtime.characterProfileScanError = report.error;
  }

  async function resolveCharacterProfileScan(input, { report, repair, assertCurrent, controller, timeoutMs, candidate = input }) {
    let failure;
    try { return validateCharacterScanValue(input); } catch (error) { failure = error; }
    if (typeof repair !== 'function') throw failure;
    let facts;
    try { facts = characterScanRepairFacts(candidate); } catch (_) { throw failure; }
    assertCurrent();
    report.repair_status = 'repairing';
    report.validation_error = scanReportText(failure.message, report);
    runtime.characterProfileScanRetrying = false;
    runtime.independentProfileController = controller;
    refreshStatePanel();
    try {
      const payload = { candidate, validation_error: failure.message, schema: CHARACTER_PROFILE_SCAN_SCHEMA.value };
      const returned = await awaitFormatRepair(repair(payload, text => {
        if (runtime.characterProfileScanReport === report && !controller.signal.aborted) report.repair_raw = scanReportText(text, report);
      }), controller.signal, timeoutMs);
      assertCurrent();
      if (!report.repair_raw) report.repair_raw = scanReportText(returned, report);
      const value = typeof returned === 'string' ? EXTERNAL_WORKFLOW.parseJsonResponse(returned) : returned;
      if (value?.repaired !== true) throw new Error('格式修复未完成：' + String(value?.reason || '模型未返回修复结果'));
      const checked = verifyCharacterScanRepair(facts, value.result);
      report.repair_status = 'repaired';
      return checked;
    } catch (error) {
      controller.abort();
      if (runtime.characterProfileScanReport === report) report.repair_status = 'failed';
      throw error;
    }
  }

  async function scanCharacterProfiles(adapter = runtime.adapter, options = {}) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    if (typeof adapter.readCharacterProfileSource !== 'function' || typeof adapter.generateCharacterProfileScan !== 'function') {
      throw new Error('当前酒馆版本不支持人物扫描');
    }
    const expectedChatIdentity = operationChatIdentity(adapter);
    const compatibility = options.compatibility === true;
    const report = beginCharacterProfileScan(compatibility ? '酒馆兼容扫描' : '酒馆扫描');
    const controller = new AbortController();
    const timeoutMs = EXTERNAL_WORKFLOW.normalizeConfig(runtime.externalApiConfig || loadExternalApiConfig()).timeout_ms;
    const assertCurrent = () => {
      assertOperationChatUnchanged(adapter, expectedChatIdentity);
      if (runtime.characterProfileScanReport !== report || controller.signal.aborted) throw new Error('本次人物扫描已停止或失效，请重新扫描。');
    };
    try {
      const source = await Promise.resolve(adapter.readCharacterProfileSource());
      assertCurrent();
      let response;
      try {
        response = await Promise.resolve(adapter.generateCharacterProfileScan(source, compatibility ? { compatibility: true } : undefined));
      } catch (error) {
        assertCurrent();
        if (compatibility || !shouldRetryCharacterProfileScan(error)) throw error;
        runtime.characterProfileScanRetrying = true;
        refreshStatePanel();
        response = await Promise.resolve(adapter.generateCharacterProfileScan(source, { compatibility: true }));
      }
      assertCurrent();
      recordCharacterProfileScan(report, response);
      let current = adapter?.getStore ? await Promise.resolve(adapter.getStore()) : undefined;
      assertCurrent();
      response = await resolveCharacterProfileScan(response, { report, assertCurrent, controller, timeoutMs,
        repair: typeof adapter.generateFormatRepair === 'function' ? payload => adapter.generateFormatRepair(CHARACTER_PROFILE_SCAN_REPAIR_PROMPT, payload) : null });
      assertCurrent();
      if (report.repair_status === 'repaired' && adapter.getStore) { current = await adapter.getStore(); assertCurrent(); }
      const base = isPlainObject(current) ? current : {};
      const profiles = parseCharacterProfileScanResponse(response, base.character_profiles || runtime.characterProfiles);
      await adapter.setStore({
        ...base,
        store_version: 5,
        character_profiles: profiles,
        saved_at: new Date().toISOString(),
      }, expectedChatIdentity);
      assertCurrent();
      runtime.characterProfiles = profiles;
      runtime.characterProfileScanStatus = 'ready';
      logStateError('character_profiles_scanned', `人物扫描完成，共找到 ${Object.keys(profiles).length} 人。`, 'info');
      return profiles;
    } catch (error) {
      if (runtime.characterProfileScanReport === report) {
        if (operationChatIdentity(adapter) !== expectedChatIdentity) resetCharacterProfileScan();
        else failCharacterProfileScan(report, error);
      }
      throw error;
    } finally {
      if (runtime.characterProfileScanReport === report) {
        if (runtime.independentProfileController === controller) runtime.independentProfileController = null;
        runtime.characterProfileScanActive = false;
        runtime.characterProfileScanRetrying = false;
        refreshStatePanel();
      }
    }
  }

  async function setCharacterProfileActive(characterName, active, adapter = runtime.adapter, options = {}) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const expectedChatIdentity = operationChatIdentity(adapter);
    const current = adapter?.getStore ? await Promise.resolve(adapter.getStore()) : undefined;
    assertOperationChatUnchanged(adapter, expectedChatIdentity);
    const base = isPlainObject(current) ? current : {};
    const profiles = sanitizeCharacterProfiles(base.character_profiles || runtime.characterProfiles);
    const name = normalizeCharacterProfileName(characterName);
    if (!profiles[name]) throw new Error('找不到这个扫描人物');
    const manualModules = modulesFromStore(base, adapter?.getStoreSource?.() || 'ver500');
    const activePlayIds = normalizeActivePlayIds(base.active_play_routes || runtime.activePlayIds);
    const effectiveModules = modulesWithPlayRequirements(manualModules, playNarrativeRouteIds(activePlayIds, base.snapshot));
    let snapshot = base.has_valid_snapshot === true ? cloneJson(base.snapshot) : cloneJson(runtime.snapshot);
    const alreadyInSnapshot = isPlainObject(snapshot?.characters?.[name]);
    if (active && !alreadyInSnapshot) {
      profiles[name].sex = normalizeCharacterProfileSex(options.sex ?? profiles[name].sex);
      const selectedStages = sanitizeProfileInitialStages(options.initialStages);
      profiles[name].initial_stages = Object.fromEntries(effectiveModules.daily_needs.map((needKey) => [
        needKey,
        selectedStages[needKey] || '平稳期',
      ]));
      profiles[name].initial_offsets = Object.fromEntries(effectiveModules.daily_needs.map((needKey) => {
        const stage = profiles[name].initial_stages[needKey];
        return [needKey, randomInitialOffset(needKey, stage)];
      }));
      if (profiles[name].sex === 'female') profiles[name].initial_cycle_day = 1 + Math.floor(randomUnit() * 28);
      else delete profiles[name].initial_cycle_day;
    }
    profiles[name].active = Boolean(active);
    delete profiles[name].observation_paused;
    const dailyAnchorArchives = sanitizeDailyAnchorArchives(base.daily_anchor_archives || runtime.dailyAnchorArchives);
    const sexualDesireProfiles = sanitizeSexualDesireProfiles(base.sexual_desire_profiles || runtime.sexualDesireProfiles, base.sexual_desire_baselines || runtime.sexualDesireBaselines);
    if (active) {
      snapshot = ensureActiveCharacterProfiles(snapshot, profiles, effectiveModules, snapshot);
    } else if (isPlainObject(snapshot?.characters)) {
      delete snapshot.characters[name];
      delete dailyAnchorArchives[name];
      delete sexualDesireProfiles[name];
      if (Object.keys(snapshot.characters).length === 0 && snapshot.scene === null) snapshot = null;
    }
    const provenance = {
      source_message_id: Number.isInteger(base.source_message_id) ? base.source_message_id : null,
      source_swipe_id: Number.isInteger(base.source_swipe_id) ? base.source_swipe_id : null,
    };
    if (snapshot === null) {
      await saveNoValidSnapshot(adapter, {
        manualEdit: 'profile-active', manualBase: base,
        characterProfiles: profiles,
        dailyAnchorArchives,
        sexualDesireProfiles,
        modules: manualModules,
        activePlayIds,
        strictStoreRead: true,
        expectedChatIdentity,
      });
    } else {
      snapshot = await saveLastValidSnapshot(snapshot, adapter, provenance, {
        manualEdit: 'profile-active', manualBase: base,
        characterProfiles: profiles,
        dailyAnchorArchives,
        sexualDesireProfiles,
        modules: manualModules,
        activePlayIds,
        strictStoreRead: true,
        expectedChatIdentity,
      });
    }
    runtime.characterProfiles = profiles;
    runtime.snapshot = snapshot;
    runtime.hasSnapshot = snapshot !== null;
    runtime.activeCharacter = active ? name : runtime.activeCharacter === name ? null : runtime.activeCharacter;
    logStateError('character_profile_toggled', `${name}${active ? '已手动建档' : '已手动删档'}。`, 'info');
    refreshStatePanel();
    return snapshot;
  }

  async function saveCharacterProfileSettings(characterName, adapter = runtime.adapter, options = {}) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const expectedChatIdentity = operationChatIdentity(adapter);
    const current = adapter?.getStore ? await Promise.resolve(adapter.getStore()) : undefined;
    assertOperationChatUnchanged(adapter, expectedChatIdentity);
    const base = isPlainObject(current) ? current : {};
    const name = normalizeCharacterProfileName(characterName);
    const foldedName = name.toLocaleLowerCase();
    if (!name || ['user', '{{user}}', '用户'].includes(foldedName)) throw new Error('请输入有效的人物姓名');

    let profiles = sanitizeCharacterProfiles(base.character_profiles || runtime.characterProfiles);
    const existingName = Object.keys(profiles).find((item) => item.toLocaleLowerCase() === foldedName) || '';
    let snapshot = base.has_valid_snapshot === true ? cloneJson(base.snapshot) : cloneJson(runtime.snapshot);
    const alreadyInSnapshot = isPlainObject(snapshot?.characters?.[name]);
    if (options.create === true && (existingName || alreadyInSnapshot)) throw new Error('这个人物已经存在，可以直接编辑现有档案');

    const profileName = existingName || name;
    const previousProfile = profiles[profileName] || {
      name: profileName,
      sex: 'unknown',
      summary: alreadyInSnapshot ? '当前档案' : '自定义人物',
      wake_start: '07:00',
      wake_end: '09:00',
      active: false,
    };
    const manualModules = modulesFromStore(base, adapter?.getStoreSource?.() || 'ver500');
    const activePlayIds = normalizeActivePlayIds(base.active_play_routes || runtime.activePlayIds);
    const effectiveModules = modulesWithPlayRequirements(manualModules, playNarrativeRouteIds(activePlayIds, snapshot));
    const sex = normalizeCharacterProfileSex(options.sex ?? previousProfile.sex);
    const selectedStages = sanitizeProfileInitialStages(options.initialStages);
    const previousStages = sanitizeProfileInitialStages(previousProfile.initial_stages);
    const previousOffsets = sanitizeProfileInitialOffsets(previousProfile.initial_offsets);
    const currentCharacter = snapshot?.characters?.[profileName];
    const initialStages = { ...previousStages };
    const initialOffsets = { ...previousOffsets };
    const changedNeeds = [];

    for (const needKey of effectiveModules.daily_needs) {
      const currentStage = NEED_STAGES.has(currentCharacter?.needs?.[needKey]?.stage)
        ? currentCharacter.needs[needKey].stage
        : (previousStages[needKey] || '平稳期');
      const stage = selectedStages[needKey] || currentStage;
      initialStages[needKey] = stage;
      if (!isPlainObject(currentCharacter?.needs?.[needKey]) || currentStage !== stage) {
        initialOffsets[needKey] = randomInitialOffset(needKey, stage);
        changedNeeds.push(needKey);
      }
    }

    profiles[profileName] = {
      ...previousProfile,
      name: profileName,
      sex,
      active: true,
      initial_stages: initialStages,
      initial_offsets: initialOffsets,
    };

    const requestedCycle = options.cycleDay ?? 'keep';
    if(requestedCycle!=='keep' && requestedCycle!=='random' && !(Number.isInteger(Number(requestedCycle)) && Number(requestedCycle)>=1 && Number(requestedCycle)<=28)) throw new Error('周期日应为1至28之间的整数，或选择保持当前／随机。');
    const reproductiveLocked=isPlainObject(currentCharacter?.reproductive?.pregnancy)||isPlainObject(currentCharacter?.reproductive?.conception);
    if((isPlainObject(currentCharacter?.reproductive?.pregnancy) && requestedCycle!=='keep') || (reproductiveLocked && options.sex!==undefined && sex!=='female')) throw new Error('该人物已有孕期或受孕记录，请刷新编辑页；当前生殖记录不能由周期或性别编辑覆盖。');
    if (sex === 'female' && effectiveModules.reproductive) {
      const currentCycleDay = currentCharacter?.reproductive?.menstrual_cycle?.cycle_day;
      const cycleDay = requestedCycle === 'keep' && Number.isInteger(currentCycleDay)
        ? currentCycleDay
        : (Number.isInteger(Number(requestedCycle)) && Number(requestedCycle) >= 1 && Number(requestedCycle) <= 28
          ? Number(requestedCycle)
          : 1 + Math.floor(randomUnit() * 28));
      profiles[profileName].initial_cycle_day = cycleDay;
    } else {
      delete profiles[profileName].initial_cycle_day;
    }

    profiles = sanitizeCharacterProfiles(profiles);
    if (!profiles[profileName]) throw new Error(`人物档案数量不能超过 ${CHARACTER_PROFILE_LIMIT} 个`);
    if (!currentCharacter) delete profiles[profileName].observation_paused;
    snapshot = ensureActiveCharacterProfiles(snapshot, profiles, effectiveModules, snapshot);
    const character = snapshot?.characters?.[profileName];
    if (!isPlainObject(character)) throw new Error('人物档案建立失败');

    const timelineHours = timelineToHours(snapshot.timeline);
    if (effectiveModules.daily_needs.length > 0) {
      character.mode = 'detailed';
      if (typeof character.observed_for !== 'number') character.observed_for = 0;
      if (!isPlainObject(character.needs)) character.needs = {};
      for (const needKey of changedNeeds) {
        const need = needSkeleton(needKey, false);
        need.stage = initialStages[needKey];
        const anchor = timelineHours === null ? null : hoursToStoryAnchor(timelineHours - initialOffsets[needKey]);
        if (anchor) {
          if (needKey === 'sleep') need.wake_at = anchor;
          else need.last_at = anchor;
        }
        character.needs[needKey] = need;
      }
    }

    if (sex !== 'female') {
      if(options.sex!==undefined) delete character.reproductive;
    } else if (effectiveModules.reproductive && requestedCycle !== 'keep') {
      const cycleDay = profiles[profileName].initial_cycle_day;
      const currentAwareness = currentCharacter?.reproductive?.menstrual_cycle?.user_awareness;
      character.reproductive = {
        menstrual_cycle: {
          cycle_day: cycleDay,
          phase: deriveFixedCyclePhase(cycleDay),
          user_awareness: USER_AWARENESS_VALUES.has(currentAwareness) ? currentAwareness : '未知',
        },
        ...(isPlainObject(currentCharacter?.reproductive?.conception)
          ? { conception: cloneJson(currentCharacter.reproductive.conception) }
          : {}),
      };
    }

    const provenance = {
      source_message_id: Number.isInteger(base.source_message_id) ? base.source_message_id : null,
      source_swipe_id: Number.isInteger(base.source_swipe_id) ? base.source_swipe_id : null,
    };
    snapshot = await saveLastValidSnapshot(snapshot, adapter, provenance, {
      manualEdit: 'profile-settings', manualBase: base,
      staminaProfiles: staminaManualProfiles(base, snapshot, profileName, options.stamina, effectiveModules),
      characterProfiles: profiles,
      modules: manualModules,
      activePlayIds,
      strictStoreRead: true,
      expectedChatIdentity,
    });
    runtime.characterProfiles = profiles;
    runtime.snapshot = snapshot;
    runtime.hasSnapshot = true;
    runtime.activeCharacter = profileName;
    logStateError('character_profile_saved', `${profileName}的档案已保存。`, 'info');
    refreshStatePanel();
    return snapshot;
  }

