  async function testExternalConnection(config = runtime.externalApiConfig) {
    if (!EXTERNAL_WORKFLOW) throw new Error('外接工作流模块未加载');
    if (runtime.externalConnectionTestPromise) return runtime.externalConnectionTestPromise;
    const savedConfig = runtime.externalApiConfig;
    runtime.externalConfigStatus = 'testing';
    runtime.externalConfigError = '';
    runtime.externalConnectionTestPromise = EXTERNAL_WORKFLOW.testConnection(config || loadExternalApiConfig(), { onTrace: recordExternalTrace });
    refreshStatePanel();
    try {
      const result = await runtime.externalConnectionTestPromise;
      if (runtime.externalApiConfig === savedConfig) runtime.externalConfigStatus = 'passed';
      return result;
    } catch (error) {
      if (runtime.externalApiConfig === savedConfig) {
        runtime.externalConfigStatus = 'failed';
        runtime.externalConfigError = error.message || String(error);
      }
      throw error;
    } finally {
      runtime.externalConnectionTestPromise = null;
      refreshStatePanel();
    }
  }

