  function normalizePlayCombinationDraft(raw) {
    if (!isPlainObject(raw)) return null;
    const kind = ['marking', 'body_modification', 'clamp_pressure', ...NARRATIVE_LIBRARY_PLAY_KINDS].includes(raw.kind) ? raw.kind : '';
    const character = String(raw.character || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 120);
    if (!kind || !character) return null;
    if (kind === 'restraint') return normalizeRestraintDraft(raw);
    if (kind === 'marking') {
      const found = findPlayLibraryEntry(MARKING_SELECTABLE_SECTIONS, String(raw.entry_id || ''));
      const carrier = String(raw.carrier || '').replace('纹身(口内墨自褪,留色需重描)', '纹身(口内留色因位置而异)');
      if (!found || !found.entry.carriers.includes(carrier)) return null;
      return {
        kind,
        character,
        layout_version: 2,
        section_id: found.section.id,
        entry_id: found.entry.id,
        carrier,
        detail: sanitizePlayDetail(raw.detail, 500),
        process_pending: markingCarrierKind(carrier) !== 'wearable' && raw.completed !== true && raw.process_pending !== false,
        recovery_enabled: markingCarrierKind(carrier) !== 'wearable' && raw.recovery_enabled === true,
        completed: markingCarrierKind(carrier) !== 'wearable' && raw.completed === true,
      };
    }
    if (kind === 'clamp_pressure') {
      const found = findPlayLibraryEntry(CLAMP_PRESSURE_SELECTABLE_SECTIONS, String(raw.entry_id || ''));
      if (!found) return null;
      const profile = clampPressureEntryProfile(found.entry);
      const location = String(raw.location || '');
      if (profile.locations.length > 0 && !profile.locations.includes(location)) return null;
      const option = profile.options.some((choice) => choice.label === raw.option)
        ? String(raw.option) : profile.defaultOption;
      if (profile.options.length > 0 && !option) return null;
      const clamp = profile.requiresClamp
        ? CLAMP_PRESSURE_BASE_ENTRIES.find((entry) => entry.id === raw.clamp_entry_id) || null
        : null;
      if (profile.requiresClamp && !clamp) return null;
      const pendantVariant = profile.pendantVariants.includes(String(raw.pendant_variant || ''))
        ? String(raw.pendant_variant) : (profile.pendant ? '砝码坠' : '');
      const weight = pendantVariant === '砝码坠' && profile.weights.some((choice) => choice.label === raw.weight)
        ? String(raw.weight) : (pendantVariant === '砝码坠' ? profile.defaultWeight : '');
      const detail = sanitizePlayDetail(raw.detail, 500);
      if (profile.requiresEndpoints && !detail) return null;
      if (found.entry.label === '拴链双夹' && location.includes('另一夹点') && !detail) return null;
      return {
        kind,
        character,
        layout_version: 1,
        section_id: found.section.id,
        entry_id: found.entry.id,
        location,
        option,
        clamp_entry_id: clamp?.id || '',
        pendant_variant: pendantVariant,
        weight,
        detail,
      };
    }
    if (NARRATIVE_LIBRARY_PLAY_KINDS.includes(kind)) {
      const library = narrativeOnlyPlayLibrary(kind);
      const entry = library.entries.find((candidate) => candidate.id === raw.entry_id) || null;
      if (!entry) return null;
      const variant = entry.variants.find((candidate) => candidate.id === raw.variant_id)
        || entry.variants[0]
        || null;
      return {
        kind,
        character,
        layout_version: 1,
        entry_id: entry.id,
        variant_id: variant?.id || '',
        ...(entry.connection ? { connection_detail: sanitizePlayDetail(raw.connection_detail, 500) } : {}),
        detail: sanitizePlayDetail(raw.detail, 500),
      };
    }
    const found = findPlayLibraryEntry(BODY_MODIFICATION_MAIN_SECTIONS, String(raw.entry_id || ''));
    if (!found) return null;
    const jewelry = BODY_MODIFICATION_JEWELRY_ENTRIES.find((entry) => (
      entry.id === raw.jewelry_id
    )) || null;
    const material = BODY_MODIFICATION_MATERIALS.find((entry) => entry.id === raw.material_id) || null;
    const accessoryIds = [...new Set(Array.isArray(raw.accessory_ids) ? raw.accessory_ids : [])]
      .filter((idValue) => BODY_MODIFICATION_ACCESSORY_ENTRIES.some((entry) => (
        entry.id === idValue
      )));
    const extensionIds = [...new Set(Array.isArray(raw.extension_ids) ? raw.extension_ids : [])]
      .filter((idValue) => BODY_MODIFICATION_EXTENSION_ENTRIES.some((entry) => (
        entry.id === idValue
      )));
    return {
      kind,
      character,
      layout_version: 2,
      section_id: found.section.id,
      entry_id: found.entry.id,
      jewelry_id: jewelry?.id || '',
      narrative_revision: raw.narrative_revision === 0 ? 0 : 4,
      initial_jewelry: bodyModificationSavedInitial({ ...raw, narrative_revision: raw.narrative_revision === 0 ? 0 : 4 }, found.entry),
      material_id: material?.id || '',
      accessory_ids: accessoryIds,
      extension_ids: extensionIds,
      process_pending: raw.completed !== true && raw.process_pending !== false,
      recovery_enabled: raw.recovery_enabled === true,
      completed: raw.completed === true,
      details: sanitizeBodyModificationDetails(raw.details, accessoryIds, extensionIds),
    };
  }

  async function applyPlayCombination(raw, adapter = runtime.adapter, editingId = '') {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const applicationIdentity = operationChatIdentity(adapter);
    const draft = normalizePlayCombinationDraft(raw);
    if (!draft) throw new Error('请完整选择应用角色和玩法搭配');
    const current = adapter?.getStore ? await adapter.getStore() : undefined;
    const base = isPlainObject(current) ? current : {};
    assertOperationChatUnchanged(adapter, applicationIdentity);
    const snapshot = cloneJson(base.has_valid_snapshot === true ? base.snapshot : runtime.snapshot);
    if (!isPlainObject(snapshot?.characters?.[draft.character]) || snapshot.characters[draft.character].mode !== 'detailed') {
      throw new Error('应用角色需要处于当前情景并已建立详细记录');
    }
    const combinations = sanitizePlayCombinations(base.play_combinations || runtime.playCombinations).map((item) => ({ ...item }));
    const existingIndex = editingId ? combinations.findIndex((item) => item.id === editingId && item.active !== false) : -1;
    const id = existingIndex >= 0 ? combinations[existingIndex].id : playCombinationId();
    const nextCombination = { id, ...draft, active: true };
    const previousCombination = existingIndex >= 0 ? combinations[existingIndex] : null;
    if (draft.kind === 'body_modification') {
      const beforeIssues = previousCombination ? bodyModificationSelectionIssues(previousCombination) : [];
      const newIssues = bodyModificationSelectionIssues(nextCombination).filter(issue => !beforeIssues.includes(issue));
      if (newIssues.length) throw new Error(newIssues.join('\n'));
    }
    const previousHasEffects = previousCombination && Object.values(snapshot.characters).some(person => Object.keys(person.effects || {})
      .some((effectKey) => playEffectParts(effectKey)?.id === previousCombination.id));
    if (previousHasEffects && (previousCombination.character !== nextCombination.character
      || previousCombination.kind !== nextCombination.kind
      || previousCombination.entry_id !== nextCombination.entry_id
      || (nextCombination.kind === 'restraint' && previousCombination.partner_character !== nextCombination.partner_character))) {
      throw new Error('已经建立状态的搭配不能更换角色或条目；请另建一套');
    }
    if (existingIndex >= 0) combinations[existingIndex] = nextCombination;
    else combinations.push(nextCombination);

    const selection = playCombinationSelection(nextCombination);
    if (!selection) throw new Error('玩法搭配已经失效，请重新选择');
    const dismissals = sanitizeEffectDismissals(base.effect_dismissals || runtime.effectDismissals);
    const character = snapshot.characters[nextCombination.character];
    if (!selection.narrativeOnly && !isPlainObject(character.effects)) character.effects = {};
    for (const descriptor of playCombinationEffectDescriptors(nextCombination)) {
      delete dismissals[effectDismissalId(descriptor.character || nextCombination.character, descriptor.key)];
    }

    const sanitized = sanitizePlayCombinations(combinations);
    assertOperationChatUnchanged(adapter, applicationIdentity);
    await commitManualPlayChange(adapter, base, {
      play_library_enabled: true,
      has_valid_snapshot: true,
      snapshot,
      play_combinations: sanitized,
      effect_dismissals: dismissals,
      format_boost_pending: true,
    }, () => {
      runtime.playDraft = null;
      runtime.playEditingId = '';
      runtime.playFeedback = `已加入${nextCombination.character}的本次准备：${selection?.label || '玩法搭配'}`;
      if (['restraint', 'marking', 'body_modification'].includes(nextCombination.kind) && operationChatIdentity(adapter) === applicationIdentity) {
        const inserted = appendPlayInputDraft(nextCombination, runtime.hostDocument, adapter, false, previousCombination);
        runtime.playFeedback += inserted === 'inserted' ? '。草稿已填入输入框，尚未发送。'
          : (inserted === 'unavailable' ? '。暂未找到聊天输入框，可稍后点击“填入草稿”。' : '。保留输入框已有草稿。');
      }
      logStateError('play_combination_applied', runtime.playFeedback, 'info');
    });
    return cloneJson(nextCombination);
  }

  async function completePlayCombination(id, adapter = runtime.adapter) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const current = adapter?.getStore ? await adapter.getStore() : undefined;
    const base = isPlainObject(current) ? current : {};
    const snapshot = cloneJson(base.has_valid_snapshot === true ? base.snapshot : runtime.snapshot);
    const combinations = sanitizePlayCombinations(base.play_combinations || runtime.playCombinations).map((item) => ({ ...item }));
    const index = combinations.findIndex((item) => item.id === id && item.active !== false);
    if (index < 0) throw new Error('这套进行中的玩法已经不存在');
    const currentCombination = combinations[index];
    const selection = playCombinationSelection(currentCombination);
    const canComplete = currentCombination.layout_version === 2
      && ((currentCombination.kind === 'marking' && !selection?.wearable) || currentCombination.kind === 'body_modification');
    if (!canComplete) throw new Error('这套玩法不需要手动建立完成状态');
    if (!isPlainObject(snapshot?.characters?.[currentCombination.character])) throw new Error('应用角色当前没有可用档案');
    const completed = { ...currentCombination, completed: true, process_pending: false };
    combinations[index] = completed;
    const descriptors = playCombinationEffectDescriptors(completed);
    if (descriptors.length === 0) throw new Error('当前设置没有可建立的完成状态');
    const character = snapshot.characters[completed.character];
    if (!isPlainObject(character.effects)) character.effects = {};
    const dismissals = sanitizeEffectDismissals(base.effect_dismissals || runtime.effectDismissals);
    for (const descriptor of descriptors) {
      character.effects[descriptor.key] = { notes: descriptor.note };
      delete dismissals[effectDismissalId(completed.character, descriptor.key)];
    }
    const sanitized = sanitizePlayCombinations(combinations);
    await commitManualPlayChange(adapter, base, {
      play_library_enabled: true,
      has_valid_snapshot: true,
      snapshot,
      play_combinations: sanitized,
      effect_dismissals: dismissals,
      format_boost_pending: true,
    }, () => {
      runtime.playFeedback = `已完成并建立${completed.character}的状态：${selection.label}`;
      logStateError('play_combination_completed', runtime.playFeedback, 'info');
    });
    return cloneJson(completed);
  }

