  async function clearPlayInjection(adapter = runtime.adapter) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const current = adapter?.getStore ? await adapter.getStore() : undefined;
    const base = isPlainObject(current) ? current : {};
    const manualModules = normalizeModules(base.modules || runtime.modules);
    const previousPlayIds = normalizeActivePlayIds(base.active_play_routes || runtime.activePlayIds);
    const previousEffective = modulesWithPlayRequirements(manualModules, playNarrativeRouteIds(previousPlayIds, base.snapshot));
    const effectiveModules = modulesWithPlayRequirements(manualModules, []);
    const dailyAnchorArchives = updateDailyAnchorArchives(
      base.daily_anchor_archives,
      base.snapshot,
      previousEffective,
      { source_message_id: base.source_message_id, source_swipe_id: base.source_swipe_id },
    );
    let snapshot = cloneJson(base.has_valid_snapshot === true ? base.snapshot : runtime.snapshot);
    if (isPlainObject(snapshot?.characters)) {
      for (const character of Object.values(snapshot.characters)) {
        for (const effectKey of Object.keys(character?.effects || {})) {
          if (playEffectParts(effectKey)?.phase === 'process') delete character.effects[effectKey];
        }
      }
    }
    if (base.has_valid_snapshot === true && snapshot) snapshot = snapshotForModules(snapshot, effectiveModules);
    const combinations = sanitizePlayCombinations(base.play_combinations || runtime.playCombinations)
      .map((item) => ({ ...item, active: false, process_pending: false }));
    const sanitized = sanitizePlayCombinations(combinations);
    await adapter.setStore({
      ...base,
      store_version: 5,
      active_play_routes: [],
      play_library_enabled: false,
      play_combinations: sanitized,
      has_valid_snapshot: snapshot !== null,
      snapshot,
      daily_anchor_archives: dailyAnchorArchives,
      cycle_enabled: effectiveModules.reproductive,
      format_boost_pending: true,
      saved_at: new Date().toISOString(),
    });
    if (typeof adapter.clearDynamicScan === 'function') {
      await Promise.resolve(adapter.clearDynamicScan()).catch((error) => logStateError('play_scan_clear_failed', error));
    }
    runtime.activePlayIds = [];
    runtime.playLibraryEnabled = false;
    runtime.playCombinations = sanitized;
    runtime.snapshot = snapshot;
    runtime.hasSnapshot = snapshot !== null;
    runtime.dailyAnchorArchives = dailyAnchorArchives;
    runtime.cycleEnabled = effectiveModules.reproductive;
    runtime.formatBoostPending = true;
    runtime.playDraft = null;
    runtime.playEditingId = '';
    runtime.playOptionInfoKey = '';
    runtime.playFeedback = '已清空玩法注入；已建立的持续影响保持不变。';
    logStateError('play_injection_cleared', runtime.playFeedback, 'info');
    refreshStatePanel();
    return { activePlayIds: [], playLibraryEnabled: false, playCombinations: sanitized, snapshot: cloneJson(snapshot) };
  }

  async function setEffectMode(mode, adapter = runtime.adapter) {
    if (!adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const current = adapter?.getStore ? await adapter.getStore() : undefined;
    const base = isPlainObject(current) ? current : {};
    const effectMode = normalizeEffectMode(mode);
    const warnings = [];
    const snapshot = base.has_valid_snapshot === true
      ? applyEffectMode(base.snapshot, effectMode, warnings)
      : base.snapshot;
    logCleanupWarnings(warnings, '持续影响模式切换');
    await commitManualPlayChange(adapter, base, {
      effect_mode: effectMode,
      has_valid_snapshot: snapshot !== null && base.has_valid_snapshot === true,
      snapshot,
      format_boost_pending: true,
    }, () => {
      logStateError('effect_mode_changed', `持续影响已切换为${effectMode === 'open' ? '宽松' : '严格'}。`, 'info');
    });
    return effectMode;
  }

  function isEditableBodyModificationEffect(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    if (parts?.prefix !== 'body_mod' || parts.phase === 'process') return false;
    const combination = playCombinationForEffect(effectKey, combinations);
    const selection = playCombinationSelection(combination);
    return combination?.layout_version === 2 && selection && !selection.legacy;
  }

  function isEditableMarkingEffect(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    if (parts?.prefix !== 'marking' || parts.phase === 'process') return false;
    const combination = playCombinationForEffect(effectKey, combinations);
    const selection = playCombinationSelection(combination);
    return combination?.layout_version === 2 && selection && !selection.legacy;
  }

  function isEditableClampPressureEffect(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    if (parts?.prefix !== 'clamp' || parts.phase !== 'state') return false;
    const combination = playCombinationForEffect(effectKey, combinations);
    return combination?.kind === 'clamp_pressure' && Boolean(playCombinationSelection(combination));
  }

  function isEditablePendingToolEffect(effectKey, combinations = runtime.playCombinations) {
    const parts = playEffectParts(effectKey);
    if (!['insertion', 'mouth', 'restraint'].includes(parts?.prefix) || parts.phase !== 'state') return false;
    const combination = playCombinationForEffect(effectKey, combinations);
    return combinationUsesPendingEffect(combination);
  }

  function isEditablePlayEffect(effectKey, combinations = runtime.playCombinations) {
    if (effectKey === CYCLE_PRESENCE_KEY) return false;
    return (EFFECT_ID_RE.test(effectKey) && !isPresetEffectKey(effectKey))
      || effectKey === 'striking_aftereffects'
      || isEditableBodyModificationEffect(effectKey, combinations)
      || isEditableMarkingEffect(effectKey, combinations)
      || isEditableClampPressureEffect(effectKey, combinations)
      || isEditablePendingToolEffect(effectKey, combinations);
  }

  function sanitizePregnancyAwarenessEdits(input) {

    const edits = {};
    for (const entry of Object.values(isPlainObject(input) ? input : {})) {
      if (!isPlainObject(entry) || typeof entry.character !== 'string' || !entry.character.trim()) continue;
      if (!['character_awareness', 'user_awareness'].includes(entry.field) || !USER_AWARENESS_VALUES.has(entry.value)) continue;
      if (!Number.isInteger(entry.source_message_id) || entry.source_message_id < 0) continue;
      if (typeof entry.content_sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(entry.content_sha256)) continue;
      const kind = entry.kind || 'pregnancy';
      if (!['conception', 'pregnancy'].includes(kind)) continue;
      if (kind === 'conception' && (!Number.isInteger(entry.window_id) || entry.window_id < 1
        || typeof entry.window_started_at !== 'string' || !STORY_ANCHOR_RE.test(entry.window_started_at))) continue;
      const record = {
        character: entry.character, kind, field: entry.field, value: entry.value,
        ...(kind === 'conception' ? { window_id: entry.window_id, window_started_at: entry.window_started_at } : {}),
        source_message_id: entry.source_message_id,
        source_swipe_id: Number.isInteger(entry.source_swipe_id) ? entry.source_swipe_id : null,
        content_sha256: entry.content_sha256,
      };
      edits[JSON.stringify([record.character, kind, record.field, record.source_message_id, record.source_swipe_id])] = record;
    }
    return edits;
  }

  function setConceptionLedgerAwareness(ledger, name, conception, field, value) {
    for (const entry of Object.values(ledger)) {
      if (entry.character !== name || entry.window_id !== conception.window_id
        || entry.window_started_at !== conception.window_started_at || entry.closed || entry.actual_outcome) continue;
      if (entry[field] !== value && field === 'character_awareness') entry.notice_pending = value === '已知';
      entry[field] = value;
    }
  }

  function applyPregnancyAwarenessEdits(snapshot, editsInput, message, conceptionLedger = null) {
    const value = cloneJson(snapshot);
    if (!message) return value;
    const hash = sha256Hex(message.message || '');
    const swipe = Number.isInteger(message.swipe_id) ? message.swipe_id : null;
    for (const edit of Object.values(sanitizePregnancyAwarenessEdits(editsInput))) {
      if (edit.source_message_id !== Number(message.message_id) || edit.source_swipe_id !== swipe || edit.content_sha256 !== hash) continue;
      const state = value?.characters?.[edit.character]?.reproductive?.[edit.kind];
      if (!isPlainObject(state)) continue;
      if (edit.kind === 'conception' && (state.outcome !== '待判定'
        || state.window_id !== edit.window_id || state.window_started_at !== edit.window_started_at)) continue;
      state[edit.field] = edit.value;
      if (edit.kind === 'conception' && conceptionLedger) {
        setConceptionLedgerAwareness(conceptionLedger, edit.character, state, edit.field, edit.value);
      }
    }
    return value;
  }

  async function setPregnancyAwareness(characterName, field, value, adapter = runtime.adapter) {
    return setReproductiveAwareness(characterName, 'pregnancy', field, value, adapter);
  }

  async function setConceptionAwareness(characterName, field, value, adapter = runtime.adapter, expectedWindow = null) {
    return setReproductiveAwareness(characterName, 'conception', field, value, adapter, expectedWindow);
  }

  async function setReproductiveAwareness(characterName, kind, field, value, adapter = runtime.adapter, expectedWindow = null) {
    if (runtime.externalStatus === 'translating') throw new Error('外接正在更新状态，请完成后再修改');
    const name = String(characterName || '').trim();
    if (!name || !['conception', 'pregnancy'].includes(kind)
      || !['character_awareness', 'user_awareness'].includes(field) || !USER_AWARENESS_VALUES.has(value)) {
      throw new Error('请选择角色本人或User角色的已知／未知状态');
    }
    if (!adapter?.getStore || !adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const expectedChatIdentity = operationChatIdentity(adapter);
    const base = await adapter.getStore();
    const snapshot = cloneJson(base?.has_valid_snapshot === true ? base.snapshot : null);
    const state = snapshot?.characters?.[name]?.reproductive?.[kind];
    if (!isPlainObject(state) || (kind === 'conception' && state.outcome !== '待判定')) {
      throw new Error(kind === 'conception' ? '该角色当前没有待判定的受孕风险' : '该角色当前没有孕期档案');
    }
    if (kind === 'conception' && expectedWindow && (state.window_id !== expectedWindow.window_id
      || state.window_started_at !== expectedWindow.window_started_at)) throw new Error('受孕判定已变化，请刷新后再修改');
    const edits = sanitizePregnancyAwarenessEdits(base.pregnancy_awareness_edits);
    const sourceId = base.source_message_id;
    if (Number.isInteger(sourceId) && adapter.readMessage) {
      const message = await adapter.readMessage(sourceId);
      const swipe = Number.isInteger(message?.swipe_id) ? message.swipe_id : null;
      if (!message || swipe !== (Number.isInteger(base.source_swipe_id) ? base.source_swipe_id : null)) {
        throw new Error('当前楼层已变化，请刷新状态后再修改');
      }
    }
    state[field] = value;
    const conceptionLedger = sanitizeConceptionEventLedger(base.conception_event_ledger);
    if (kind === 'conception') setConceptionLedgerAwareness(conceptionLedger, name, state, field, value);
    assertOperationChatUnchanged(adapter, expectedChatIdentity);
    const saved = await saveLastValidSnapshot(snapshot, adapter, {
      source_message_id: Number.isInteger(sourceId) ? sourceId : null,
      source_swipe_id: Number.isInteger(base.source_swipe_id) ? base.source_swipe_id : null,
    }, { pregnancyAwarenessEdits: edits, conceptionEventLedger: conceptionLedger, strictStoreRead: true, expectedChatIdentity, manualEdit: 'awareness', manualBase: base });
    runtime.snapshot = saved;
    runtime.hasSnapshot = true;
    logStateError(`${kind}_awareness_updated`, `已更新“${name}”的${field === 'character_awareness' ? '角色本人' : 'User角色'}知情状态。`, 'info');
    refreshStatePanel();
    return cloneJson(saved.characters[name].reproductive[kind]);
  }

  async function setConceptionResult(characterName, outcome, adapter = runtime.adapter, expectedWindow = null) {
    if (runtime.generationActive || runtime.externalFlushPromise || runtime.externalStatus === 'translating') throw new Error('请等本轮状态处理结束后再指定结果');
    const name = String(characterName || '').trim();
    if (!name || !['已受孕','未受孕'].includes(outcome)) throw new Error('请选择本次窗口的受孕结果');
    if (!adapter?.getStore || !adapter?.setStore) throw new Error('没有可用的聊天状态保存接口');
    const identity = operationChatIdentity(adapter), base = await adapter.getStore();
    const snapshot = cloneJson(base?.has_valid_snapshot ? base.snapshot : null);
    if (Number.isInteger(base?.source_message_id) && adapter.readMessage) {
      const message = await adapter.readMessage(base.source_message_id);
      if (!message || (message.swipe_id ?? null) !== (base.source_swipe_id ?? null)) throw new Error('当前楼层已变化，请刷新后再指定结果');
      assertOperationChatUnchanged(adapter,identity);
    }
    const conception = snapshot?.characters?.[name]?.reproductive?.conception;
    if (!conception || conception.outcome !== '待判定' || !Number.isInteger(conception.window_id) || !conception.window_started_at) throw new Error('当前没有可指定结果的待判定窗口');
    if (expectedWindow && (conception.window_id !== expectedWindow.window_id || conception.window_started_at !== expectedWindow.window_started_at)) throw new Error('受孕窗口已变化，请刷新后再操作');
    const windowIdentity = conceptionWindowIdentity(name, conception);
    const decisions = sanitizeConceptionDecisionLedger(base.conception_decision_ledger);
    const active = sanitizeActiveConceptionDecisions(base.active_conception_decisions, decisions);
    if (decisions[active[windowIdentity]]) throw new Error('本次窗口已有结果，请刷新状态');
    const key = `manual:${windowIdentity}:${conception.window_started_at}`;
    decisions[key] = { character: name, identity: windowIdentity, outcome, manual: true,
      window_id: conception.window_id, window_started_at: conception.window_started_at, last_risk_at: conception.last_risk_at,
      probability_percent: conception.combined_risk_percent ?? conception.event_risk_percent, probability: null, roll: null,
      source_message_id: base.source_message_id ?? null, source_swipe_id: base.source_swipe_id ?? null, decided_at: new Date().toISOString() };
    active[windowIdentity] = key;
    const only = { ...snapshot, characters: { [name]: snapshot.characters[name] } };
    const seeded = reconcileConceptionEventLedger(only, base.conception_event_ledger || {});
    const decided = applyConceptionDice(only, decisions, active, {}, () => { throw new Error('手动结果不应触发随机判定'); });
    snapshot.characters[name] = decided.snapshot.characters[name];
    const events = reconcileConceptionAwarenessLedger(seeded.ledger, snapshot, decided.notices);
    const archiveState = applyArchiveOperations(base.archives,base.archive_tombstones,snapshot,[],{source_message_id:base.source_message_id,source_swipe_id:base.source_swipe_id},outcome==='未受孕'?[{name,moduleName:'conception',reason:'negative'}]:[]);
    const saved = await saveLastValidSnapshot(snapshot, adapter, { source_message_id: base.source_message_id, source_swipe_id: base.source_swipe_id }, {
      conceptionDecisionLedger: decided.ledger, activeConceptionDecisions: decided.active, conceptionEventLedger: events,
      archives: archiveState.archives, archiveTombstones: archiveState.tombstones,
      strictStoreRead: true, expectedChatIdentity: identity, manualEdit: 'conception-result', manualBase: base,
    });
    runtime.snapshot = saved; runtime.hasSnapshot = saved !== null;
    logStateError('conception_result_manual', `已将“${name}”本次窗口指定为${outcome}；不会自动改变双方知情。`, 'info');
    refreshStatePanel();
    return cloneJson(saved?.characters?.[name]?.reproductive || null);
  }

  async function updatePlayEffectManually(characterName, effectKey, notesInput, adapter = runtime.adapter) {
    const name = String(characterName || '').trim();
    const key = String(effectKey || '').trim();
    const notes = String((isPlainObject(notesInput) ? notesInput.notes : notesInput) || '').replace(/\s+/g, ' ').trim().slice(0, 500);
    if (!name || !EFFECT_ID_RE.test(key)) throw new Error('缺少可编辑的持续影响');
    if (!notes) throw new Error('当前记录不能为空；不再需要时请使用“移除记录”');
    if (!adapter?.getStore || !adapter?.setStore) throw new Error('没有可用的聊天变量持久化接口');
    const identity=operationChatIdentity(adapter);
    const current = await adapter.getStore();
    assertOperationChatUnchanged(adapter,identity);
    const base = isPlainObject(current) ? current : {};
    const playCombinations = sanitizePlayCombinations(base.play_combinations || runtime.playCombinations);
    if (!isEditablePlayEffect(key, playCombinations)) throw new Error('该持续影响不支持手动编辑');
    const snapshot = cloneJson(base.has_valid_snapshot === true ? base.snapshot : runtime.snapshot);
    const effect = snapshot?.characters?.[name]?.effects?.[key];
