  async function analyzeExternalRange(start, end, adapter = runtime.adapter) {
    if (String(start).trim() === '' || String(end).trim() === '' || !Number.isInteger(Number(start)) || !Number.isInteger(Number(end))
      || Number(start) < 0 || Number(end) < Number(start)) throw new Error('请填写有效的起止楼号，结束楼不能早于起始楼。');
    if (runtime.externalFlushPromise) throw new Error('已有分析正在进行，请等当前任务完成后再选择区间。');
    adapter = guardStateAdapter(adapter);
    const from = Number(start), cutoff = Number(end);
    let task;
    await queueLocalStateTask(async () => {
      if (runtime.externalFlushPromise) throw new Error('已有分析正在进行，请等当前任务完成后再选择区间。');
      const store = await adapter.getStore() || {};
      if (normalizeWorkflowMode(store.state_workflow_mode) !== WORKFLOW_MODES.EXTERNAL) throw new Error('请先切换到外接模式。');
      const messages = completedExternalBranch(await adapter.listMessages());
      if (!messages.some(message => message.role === 'assistant' && message.message_id >= from && message.message_id <= cutoff)) throw new Error('该区间没有已完成的模型回复。');
      const pending = await syncExternalPendingFromBranch(adapter, messages);
      if (pending.some(row => row.message_id < from)) throw new Error(`请从最早待更新的第 ${pending[0].message_id} 楼开始，不能跳过前面的状态。`);
      if (messages.some(message => message.role === 'assistant' && message.message_id >= from && message.message_id <= cutoff
        && message.message_id > (store.source_message_id ?? -1) && !pending.some(row => externalMessageMatches(message, row)))) {
        throw new Error('区间包含未纳入当前外接流程或已主动跳过的楼层，本次不覆盖历史记录。');
      }
      runtime.externalRange = { start: String(from), end: String(cutoff), message: '正在补算所选区间…', error: '' };
      const completedEnd = messages.filter(message => message.role === 'assistant').at(-1)?.message_id ?? -1;

      task = flushExternalPending(adapter, { background: true, cutoff: Math.min(cutoff, completedEnd), rangeStart: from });
    });
    const result = await task;
    assertStateOperation(adapter);
    runtime.externalRange.message = result.ok ? `所选区间已完成，本次更新 ${result.processed || 0} 轮。` : '';
    runtime.externalRange.error = result.ok ? '' : (result.error || '更新已停止，已完成的进度保留。');
    refreshStatePanel(); return result;
  }

