      const character = value?.characters?.[edit.character];
      if (!character) continue;
      if (!isPlainObject(character.effects)) character.effects = {};
      if (edit[direction] === null) delete character.effects[edit.effect];
      else if (isPlainObject(edit[direction])) character.effects[edit.effect] = cloneJson(edit[direction]);
