  async function beginIndependentSetup(adapter = runtime.adapter) {
    if (runtime.generationActive || runtime.externalCleaningUI.busy) throw new Error('请等本轮任务结束后再检查。');
    const identity = operationChatIdentity(adapter), ui = runtime.externalCleaningUI;
    const base = await adapter.getStore() || {};
    const messages = await adapter.listMessages();
    assertOperationChatUnchanged(adapter, identity);
    if (ui !== runtime.externalCleaningUI) return;
    runtime.independentSetup = true;
    ui.open = true; ui.error = ''; ui.message = '先扫描或预览，再确认内容并启用。';
    const cleaning = normalizeExternalCleaning(base.external_content_cleaning);
    const hasBody = messages.some(item => item.role === 'assistant' && item.message?.trim());
    if (hasBody && cleaning.rules && !ui.candidate) await editExternalCleaning(adapter);
    if (!hasBody) ui.message = '先生成一段正文，再回来检查。原模式继续可用。';
    refreshStatePanel();
  }

  async function previewIndependentPlainText(adapter = runtime.adapter) {
    const ui = runtime.externalCleaningUI, identity = operationChatIdentity(adapter);
    if (ui.busy || ui.saving || runtime.generationActive) return;
    const samples = selectExternalCleaningSamples(await adapter.listMessages());
    assertOperationChatUnchanged(adapter, identity);
    if (ui !== runtime.externalCleaningUI) return;
    ui.candidate = emptyExternalCleaningRules(); ui.disabled = [];
    ui.samples = previewExternalCleaning(samples, ui.candidate);
    ui.open = true; ui.error = ''; ui.message = '以下内容不做额外标签清理，请查看后确认。';
    const latest = samples.filter(item => item.role === 'assistant').at(-1);
    ui.openSamples = latest ? [`assistant:${latest.message_id}`] : [];
    refreshStatePanel();
  }

  function independentRanges(store) {
    return (Array.isArray(store?.external_independent_ranges) ? store.external_independent_ranges : [])
      .filter(item => Number.isInteger(item?.start_after) && (item.end_at === null || Number.isInteger(item.end_at)))
      .map(item => ({ start_after: item.start_after, end_at: item.end_at }));
  }
  function isIndependentTurn(store, message) {
    return independentRanges(store).some(range => Number(message?.message_id) > range.start_after
      && (range.end_at === null || Number(message.message_id) <= range.end_at));
  }
  function updateIndependentRanges(store, lastId, active) {
    const ranges = independentRanges(store).filter(item => item.end_at === null || item.start_after < lastId)
      .map(item => ({ start_after: Math.min(item.start_after, lastId), end_at: item.end_at === null ? null : Math.min(item.end_at, lastId) }));
    const open = ranges.findLast(item => item.end_at === null);
    if (open && !active) open.end_at = lastId;
    if (!open && active) ranges.push({ start_after: lastId, end_at: null });
    return ranges;
  }

  async function syncIndependentRanges(adapter, messages) {
    const identity = operationChatIdentity(adapter), base = await adapter.getStore() || {};
    const active = normalizeWorkflowMode(base.state_workflow_mode) === WORKFLOW_MODES.EXTERNAL && base.external_analysis_mode === 'independent';
    const lastId = messages.filter(item => item.role === 'assistant').at(-1)?.message_id ?? -1;
    const ranges = updateIndependentRanges(base, lastId, active);
    const startAfter = active ? Math.min(Number(base.external_start_after ?? lastId), lastId) : base.external_start_after;
    assertOperationChatUnchanged(adapter, identity);
    if (JSON.stringify(ranges) !== JSON.stringify(independentRanges(base)) || startAfter !== base.external_start_after) {
      await adapter.setStore({ ...base, external_independent_ranges: ranges, external_start_after: startAfter }, identity);
    }
  }

  async function setExternalAnalysisMode(mode, adapter = runtime.adapter, options = {}) {
    if (runtime.externalBackgroundJob) throw new Error('请等当前后台分析完成后再切换分析方式。');
    if (runtime.generationActive || runtime.externalControl.stopping) throw new Error('请等本轮结束后切换分析方式。');
    const next = normalizeExternalAnalysisMode(mode), identity = operationChatIdentity(adapter);
    let base = await adapter.getStore() || {};
    if (next === 'independent' && (!independentCleaningReady(base) || options.review === true)) {
      await beginIndependentSetup(adapter); return false;
    }
    if (sanitizeExternalPendingQueue(base.external_pending_queue).length) {
      const result = await flushExternalPending(adapter);
      if (!result.ok) throw new Error('待更新内容尚未结算，请重试，或先停止外接并切回内置。');
      base = await adapter.getStore() || {};
    }
    const messages = await adapter.listMessages();
    assertOperationChatUnchanged(adapter, identity);
    const lastId = messages.filter(item => item.role === 'assistant').at(-1)?.message_id ?? -1;
    const wasExternal = normalizeWorkflowMode(base.state_workflow_mode) === WORKFLOW_MODES.EXTERNAL;
    await adapter.setStore({ ...base, external_analysis_mode: next, state_workflow_mode: WORKFLOW_MODES.EXTERNAL,
      external_independent_ranges: updateIndependentRanges(base, lastId, next === 'independent'),
      ...(!wasExternal ? { external_start_after: lastId } : {}) }, identity);
    assertOperationChatUnchanged(adapter, identity);
    runtime.workflowMode = WORKFLOW_MODES.EXTERNAL; runtime.externalAnalysisMode = next;
    runtime.independentSetup = false; runtime.externalPreflightResult = null;
    await releasePromptRequest(adapter);
    await loadAndRefresh(adapter);
    return true;
  }

  function parseStoryTime(text) {
    const blocks = [...String(text || '').matchAll(/<story_time\b[^>]*>([\s\S]*?)<\/story_time>/gi)];
    if (blocks.length !== 1) return null;
    const match = /^D([1-9]\d{0,6})\s+([01]\d|2[0-3]):([0-5]\d)$/.exec(blocks[0][1].trim());
    return match ? { day: Number(match[1]), time: `${match[2]}:${match[3]}` } : null;
  }
  function storyTimeMinutes(time) {
    return time && Number.isInteger(time.day) && time.day > 0 && /^([01]\d|2[0-3]):[0-5]\d$/.test(time.time)
      ? time.day * 1440 + Number(time.time.slice(0, 2)) * 60 + Number(time.time.slice(3)) : null;
  }
  function parseHandoffStoryTime(text) {
    const blocks = [...String(text || '').matchAll(/<state_handoff\b[^>]*>([\s\S]*?)<\/state_handoff>/gi)];
    if (blocks.length !== 1) return null;
    const lines = blocks[0][1].split(/\r?\n/).filter(line => /^\s*(?:[-*]\s+)?(?:\*\*)?结束时间(?:\*\*)?\s*[:：]/.test(line));
    if (lines.length !== 1) return null;
    const times = [...lines[0].matchAll(/(?:\bD([1-9]\d{0,6})\b|第\s*([1-9]\d{0,6})\s*天)\s*[,，·]?\s*([01]?\d|2[0-3])[:：]([0-5]\d)(?!\d)/gi)];
    if (times.length !== 1) return null;
    return { day: Number(times[0][1] || times[0][2]), time: `${times[0][3].padStart(2, '0')}:${times[0][4]}` };
  }

  function lastKnownStoryClock(store, messages) {
    if (store?.has_valid_snapshot !== true || store.snapshot !== null || !Number.isInteger(store.source_message_id)) return null;
    const skipped = sanitizeExternalPendingQueue(store.external_skipped_turns);
    const branch = messages.filter(item => item.role === 'assistant' && item.message_id <= store.source_message_id).sort((a,b) => b.message_id - a.message_id);
    for (const message of branch) {
      if (skipped.some(item => externalMessageMatches(message, item))) continue;
      const key = externalLedgerKey(Number(message.message_id), message.swipe_id);
      const record = store.external_state_ledger?.[key];
      const entry = record ? externalLedgerEntryForMessage(message, { [key]: record }, messages) : null;
      const text = entry?.raw_state_block || inlineStateText(message, store, messages);
      const block = extractLifeState(text);
      if (!block || (!entry && block.inner.trim() === 'null')) continue;
      const result = processLifeStateTextFlexible(text, modulesFromStore(store, 'vnext'));
      if (!result.ok) continue;
      const time = result.snapshot?.timeline;
      const timeline = storyTimeMinutes(time) !== null ? time : entry && result.snapshot === null
        ? (isIndependentTurn(store, message) ? parseStoryTime(message.message) : parseHandoffStoryTime(message.message)) : null;
      if (storyTimeMinutes(timeline) !== null) return { timeline: cloneJson(timeline), sourceMessageId: message.message_id,
        source: time ? 'history_state' : 'history_body', carried: true, notice: '当前没有跟踪状态，沿用最近记录的剧情时间；后续推进以正文为准。' };
    }
    return null;
  }


  function resolveStoryClock(store, messages) {
    const saved = store?.has_valid_snapshot === true ? store.snapshot?.timeline : null;
    const settled = storyTimeMinutes(saved) !== null ? cloneJson(saved) : null;
    const previous = settled ? null : lastKnownStoryClock(store, messages);
    let timeline = settled || previous?.timeline || null;
    let sourceMessageId = store?.source_message_id ?? null, notice = '', pending = false;
    let source = settled ? 'snapshot' : previous?.source || null, carried = Boolean(previous);
    if (previous) { sourceMessageId = previous.sourceMessageId; notice = previous.notice; }
    if (normalizeWorkflowMode(store?.state_workflow_mode) !== WORKFLOW_MODES.EXTERNAL) return { timeline, sourceMessageId, settled, notice, pending, source, carried };
    const queue = sanitizeExternalPendingQueue(store?.external_pending_queue);
    const skipped = sanitizeExternalPendingQueue(store?.external_skipped_turns);
    for (const message of [...messages].filter(item => item.role === 'assistant').sort((a, b) => a.message_id - b.message_id)) {
      if (Number.isInteger(store?.source_message_id) && message.message_id <= store.source_message_id) continue;
      if (skipped.some(item => externalMessageMatches(message, item))) continue;
      const queued = queue.find(item => externalMessageMatches(message, item));
      const independent = queued?.turn_context
        ? normalizeExternalAnalysisMode(queued.turn_context.external_analysis_mode) === 'independent'
        : isIndependentTurn(store, message);
      if (!queued && !(Number(message.message_id) > Number(store?.external_start_after ?? -1)
        && (independent || /<state_handoff\b/i.test(message.message)))) continue;
      if (/<life_state\b/i.test(message.message) && !queued) continue;
      pending = true;
      const parsed = independent ? parseStoryTime(message.message) : parseHandoffStoryTime(message.message);
      if (!parsed) { notice = '本轮未提供有效时间，沿用最近时间；结算时核对正文。'; continue; }
      if (timeline && storyTimeMinutes(parsed) < storyTimeMinutes(timeline)) { notice = '本轮时间早于已有记录，暂沿用最近时间；结算时核对正文。'; continue; }
      timeline = parsed; sourceMessageId = message.message_id; notice = ''; source = independent ? 'story_time' : 'handoff'; carried = false;
    }
    return { timeline, sourceMessageId, settled, notice, pending, source, carried };
  }
  async function refreshStoryClockContext(adapter, messages) {
    const identity = operationChatIdentity(adapter), store = await adapter.getStore() || {};
    const branch = messages || (adapter.listMessages ? await adapter.listMessages() : []);
    assertOperationChatUnchanged(adapter, identity);
    runtime.externalAnalysisMode = normalizeExternalAnalysisMode(store.external_analysis_mode);
    runtime.cyclePresenceEnabled = store.cycle_presence_enabled === true;
    runtime.storyClock = resolveStoryClock(store, branch);
    return store;
  }

  function independentCharacterReference(profiles) {
    return Object.values(sanitizeCharacterProfiles(profiles)).map(({ name, sex, summary, wake_start, wake_end }) => ({ name, sex, summary, wake_start, wake_end }));
  }
  function independentJudgmentRules(context, snapshot) {
    const options = { snapshot, effectMode: context.effect_mode, playLibraryEnabled: context.play_library_enabled,
      selectedPlayRouteIds: context.active_play_routes, playCombinations: context.play_combinations,
      effectDismissals: context.effect_dismissals, autoProfileEnabled: context.auto_profile_enabled !== false,
      userTrackingEnabled: context.user_tracking_enabled, userName: context.tracked_user_name,
      characterProfiles: context.character_profiles || {} };
    const modules = modulesWithPlayRequirements(modulesFromStore(context, 'vnext'), context.active_play_routes || []);
    const selected = normalizeActivePlayIds(context.active_play_routes || []);
    const effects = [
      buildExternalPresetEffectJudgmentPrompt(selected, snapshot, options.effectDismissals),
      buildExternalStrikingEffectJudgmentPrompt(selected, snapshot, options.effectDismissals),
      buildExternalPlayCombinationJudgmentPrompt(snapshot, options.playCombinations || []),
      normalizeEffectMode(context.effect_mode) === 'open' ? buildExternalOpenEffectJudgmentPrompt() : '',
    ].filter(Boolean);

    let archive = buildBodyArchivePrompt(options)
      .replace('自然完成正文，并按正文结束时的事实依次判断：', '阅读已完成的正文，按本轮结束时的事实依次判断：')
      .replace('其他权威设定', '本次提供的人物资料')
      .replace('- 没有未结束状态：删除角色。', '- 没有需保留的未决项目：从本轮活动记录删除角色，手动档案由脚本保留。' + (modules.reproductive ? '待判定窗口按下方生殖规则优先保留。' : ''))
      .replace('未结束状态只指User', '普通未结束状态指User')
      .replace('且正文没有明确结束', '且本轮没有明确结束事实')
      .replace('正文明确结束连续场景', '本轮明确结束连续场景');
    if (!effects.length) archive = archive.replace('\n6. 哪些持续影响（effects）需要建立、继承或删除？', '');
    const sections = [archive, buildManualCharacterProfilePrompt(options.characterProfiles, true)];
    if (context.play_library_enabled === true && options.autoProfileEnabled) {
      sections.push('# 玩法库建档\n\n即使没有开启其他观察项目，正文结束时仍在当前情景且可以直接观察的角色也使用 detailed，并保留 effects: {}。离场后按相同的 retained／删除规则处理。');
    }
    if (effects.length) sections.push('# 持续影响\n\n只记录当前玩法直接留下、正文结束时仍在的状态。写清状态名称、当前设置和仍在的直接影响。', ...effects.map(text => text.replace(/交接/g, '记录')));
    if (modules.daily_needs.length) {
      sections.push(DAILY_COMMON_PROMPT.replace('以“当前最低阶段”为起点，按本轮最终事实确定 stage。', '以前轮状态为起点，结合本轮满足、加重和缓解确定 stage。时间推进由脚本结算。'));

      sections.push(modules.daily_needs.map(key => {
        const rule = DAILY_NEED_PROMPTS[key];
        return rule.slice(0, rule.indexOf('：') + 1) + rule.slice(rule.indexOf('。') + 1);
      }).join('\n'));
    }
    if (modules.reproductive) {
      sections.push(REPRODUCTIVE_PROTOCOL_PROMPT
        .replace('字段结构按尾部格式填写。', '受孕风险及补救事实写入 conception_updates，周期与孕期写入 state；具体结构按 current_state_schema 填写。')
        .replace('均视为 sperm_entered:"是"', '均视为形成受孕暴露')
        .replace('时为 "否"。', '时不算新的暴露。')
        .replace('- sperm_entered 为 "是"：建立或更新 conception；为 "否"：不建立新的 conception。事实不清楚时不得猜测，也不得取消上一份仍“待判定”的窗口。', '- 本轮形成暴露或补救时，在 conception_updates 记录事实与事件关系。没有新变化时写空数组，脚本保留上一份仍待判定的窗口。')
        .replace('只属于一个 event_no；新的独立行为完成后才增加 event_no。', '属于同一事件；新的独立行为完成后才算新事件。编号由脚本分配。')
        .replace('- reproductive:null 才表示永久删除长期生殖档案；省略 reproductive 不表示永久删除。', '- 省略 reproductive 不表示永久删除长期档案。明确结束某项生殖状态时，在 change_evidence.ended_reproductive 指明角色和项目。'));
    }
    if (cyclePresenceActive(context.cycle_presence_enabled, modules)) sections.push(buildCyclePresenceRecordingRule());
    return sections.filter(Boolean).join('\n\n');
  }

  function buildIndependentPromptPlan(options, modules) {
    const clock = options.storyClock || options.independentClock || runtime.storyClock || {};
    const time = clock.timeline || options.snapshot?.timeline;
    const anchor = storyTimeMinutes(time) !== null ? clock.carried
      ? `最近记录时间：D${time.day} ${time.time}。若后续正文已推进时间，以后续情节为准，保持日期编号连续。`
      : `当前剧情时间：D${time.day} ${time.time}。接续此时间展开本轮剧情。`
      : '当前剧情时间尚未确定；按本轮正文确定时间，已有日期编号继续沿用，首次建立才从D1开始。';
    const routed = { ...options, externalBody: true, independentBody: true,
      playRouteIds: options.playRouteIds || options.dynamicModuleIds || options.selectedPlayRouteIds || runtime.activePlayIds,
      playCombinations: options.playCombinations || runtime.playCombinations,
