  function reconcileCyclePresence(snapshot, previous = snapshot, enabled = runtime.cyclePresenceEnabled, modules = effectiveRuntimeModules()) {
    const next = cloneJson(snapshot);
    for (const [name, character] of Object.entries(next?.characters || {})) {
      const context = cyclePresenceActive(enabled, modules) ? cyclePresenceContext(character, next.timeline) : null;
      if (!context) {
        if (isPlainObject(character.effects)) delete character.effects[CYCLE_PRESENCE_KEY];
        continue;
      }
      const before = previous?.characters?.[name];
      const oldContext = cyclePresenceContext(before, previous?.timeline);
      const same = oldContext?.stamp === context.stamp;
      const oldNotes = typeof before?.effects?.[CYCLE_PRESENCE_KEY]?.notes === 'string' ? before.effects[CYCLE_PRESENCE_KEY].notes.trim() : '';
      const incoming = character.effects?.[CYCLE_PRESENCE_KEY]?.notes;
      let notes = typeof incoming === 'string' ? incoming.trim().slice(0, 500) : '';

      if (!same && oldContext && (notes === oldNotes || notes === oldContext.baseline)) notes = '';
      if (!notes && same) notes = oldNotes.slice(0, 500);
      if (!isPlainObject(character.effects)) character.effects = {};
      character.effects[CYCLE_PRESENCE_KEY] = { name: context.name, notes: notes || context.baseline };
    }
    return next;
  }

