    if (runtime.debugExternalSelectedIndex === null) runtime.debugExternalSelectedIndex = runtime.externalDebugTraces.length - 1;
    if (['response', 'error'].includes(entry.phase)) runtime.externalLastResponse = entry;
    return entry;
