  function createExternalStateTrace(adapter) {
    let response = null;
    return {
      onTrace(event) {
        try { assertStateOperation(adapter); } catch (_) { return; }
        const entry = recordExternalTrace(event);
        if (['response', 'error'].includes(entry.phase)) {
          response = entry;
          entry.state_result = entry.phase === 'response' ? 'checking' : 'not_saved';
        }
      },
      finish(status, message = '') {
        try { assertStateOperation(adapter); } catch (_) { return; }
        if (response) Object.assign(response, { state_result: status, state_message: message });
      },
    };
