            state_handoff: EXTERNAL_PROMPTS.extractStateHandoff(message.message) || '' })),
        };
        sourceMessageId = Number.isInteger(Number(lastUserMessage?.message_id)) ? Number(lastUserMessage.message_id) : null;
      } else if ((runtime.externalUpdateEvery === 3 || firstMode === 'independent') && pendingMessages.length) {
        input = buildExternalBatchInput(store || {}, pendingMessages, messages, pendingQueue);
        sourceMessageId = Number(pendingMessages[pendingMessages.length - 1].message_id);
      } else if (store?.external_analysis_mode === 'independent' && !pendingMessages.length) {
        const message = latestAssistantMessage(messages);
        if (!message) throw new Error('先生成一段正文，再查看独立分析的发送内容。');
        const rebuilt = await findLatestBranchSnapshot(adapter, { excludeLastAssistant: true });
        const base = { ...store, snapshot: rebuilt.found ? rebuilt.snapshot : null };
        input = buildExternalBatchInput(base, [message], messages, [{ turn_context: captureExternalTurnContext(base) }]);
        sourceMessageId = message.message_id;
      } else {
        const assistantMessage = pendingMessages[0] || latestAssistantMessage(messages);
        if (!assistantMessage) throw new Error('当前聊天没有可用于后置翻译伪发送的正文楼层');
        sourceMessageId = Number(assistantMessage.message_id);
        const rebuilt = await findLatestBranchSnapshot(adapter, { excludeLastAssistant: true });
        const previousSnapshot = pendingMessages.length && store?.has_valid_snapshot === true ? store.snapshot : rebuilt?.found
          ? rebuilt.snapshot
          : (store?.has_valid_snapshot === true ? store.snapshot : runtime.snapshot);
