    const password = typeof root.prompt === 'function' ? root.prompt('输入调试密码') : null;
    if (password === null) return false;
    const unlocked = unlockDebugMode(password);
    if (!unlocked && typeof root.alert === 'function') root.alert('调试密码不正确');
    return unlocked;
  }

