  function buildDebugCatalogMarkup() {
    const entries = buildPromptCatalog();
    if (!entries.length) return '<div class="ls-debug-empty">当前没有可读取的提示词。</div>';
    if (!entries.some((entry) => entry.id === runtime.debugCatalogSelectedId)) runtime.debugCatalogSelectedId = entries[0].id;
    const selected = entries.find((entry) => entry.id === runtime.debugCatalogSelectedId) || entries[0];
    const list = entries.map((entry) => `<button class="ls-debug-catalog-item" type="button" data-action="debug-catalog-entry" data-prompt-id="${escapeHtml(entry.id)}" aria-pressed="${String(entry.id === selected.id)}"><span>${escapeHtml(entry.label)}</span><small>${escapeHtml(entry.id)} · ${entry.length}字</small></button>`).join('');
    return `<div class="ls-debug-split"><div class="ls-debug-catalog-list">${list}</div><section class="ls-debug-document"><div class="ls-debug-document-head"><div><strong>${escapeHtml(selected.label)}</strong><small>${escapeHtml(selected.group)} · ${escapeHtml(selected.id)} · ${escapeHtml(selected.source)}</small></div><button type="button" data-action="debug-copy" data-copy-kind="catalog">复制</button></div><pre>${escapeHtml(selected.content)}</pre></section></div>`;
  }

  function buildNarrativeEditorMarkup() {
    const definitions = buildNarrativeEditorDefinitions();
    if (!definitions.length) return '<div class="ls-debug-empty">当前没有可编辑的叙事条目。</div>';
    if (!definitions.some((item) => item.id === runtime.narrativeEditorSelectedId)) runtime.narrativeEditorSelectedId = definitions[0].id;
    const copyId = NARRATIVE_COPY_IDS.includes(runtime.narrativeCopies?.activeCopy) ? runtime.narrativeCopies.activeCopy : 'default';
    const selected = resolveNarrativeEntry(runtime.narrativeEditorSelectedId, copyId);
    const selectedCopyEntries = copyId === 'default' ? {} : runtime.narrativeCopies?.copies?.[copyId]?.entries || {};
    const copyCounts = {
      copy1: Object.keys(runtime.narrativeCopies?.copies?.copy1?.entries || {}).length,
      copy2: Object.keys(runtime.narrativeCopies?.copies?.copy2?.entries || {}).length,
    };
    const readOnly = copyId === 'default';
    const list = definitions.map((definition) => {
      const entry = resolveNarrativeEntry(definition.id, copyId);
      return `<button class="ls-narrative-item" type="button" data-action="narrative-entry" data-narrative-id="${escapeHtml(definition.id)}" aria-pressed="${String(definition.id === selected.id)}"><span>${escapeHtml(entry.title)}</span><small>${escapeHtml(definition.group)} · ${escapeHtml(definition.id)}</small>${entry.modified ? '<em>已修改</em>' : ''}</button>`;
    }).join('');
    const lockedParts = [selected.lockedPrefix, selected.lockedSuffix].filter(Boolean).join('｜');
    const copyButtons = NARRATIVE_COPY_IDS.map((id) => `<button type="button" data-action="narrative-copy" data-narrative-copy="${id}" aria-pressed="${String(copyId === id)}">${NARRATIVE_COPY_LABELS[id]}${id === 'default' ? '' : `（${copyCounts[id]}）`}</button>`).join('');
    const summaryField = selected.canEditStateSummary
      ? `<label class="ls-narrative-field"><span>当前状态短句</span><textarea class="ls-narrative-summary" ${readOnly ? 'disabled' : ''}>${escapeHtml(selected.state_summary)}</textarea></label>`
      : '';
    const notice = runtime.narrativeEditorNotice ? `<div class="ls-narrative-notice">${escapeHtml(runtime.narrativeEditorNotice)}</div>` : '';
    return `<div class="ls-narrative-toolbar"><div class="ls-narrative-copy-row"><strong>当前版本</strong>${copyButtons}</div><div class="ls-narrative-help">默认原版只读；副本修改会从下一次生成开始同时用于内置与外接模式。</div>${notice}</div><div class="ls-debug-split ls-narrative-split"><div class="ls-narrative-list">${list}</div><section class="ls-narrative-editor"><div class="ls-narrative-editor-head"><strong>${escapeHtml(selected.title)}</strong><small>${escapeHtml(selected.group)} · ${escapeHtml(selected.id)}</small></div><div class="ls-narrative-locked">${lockedParts ? `固定内容：${escapeHtml(lockedParts)}` : '此条目没有阶段或日期字段'}</div><label class="ls-narrative-field"><span>副标题</span><input class="ls-narrative-subtitle" type="text" maxlength="120" value="${escapeHtml(selected.subtitle)}" ${readOnly ? 'disabled' : ''}></label>${summaryField}<label class="ls-narrative-field"><span>叙事正文</span><textarea class="ls-narrative-body" ${readOnly ? 'disabled' : ''}>${escapeHtml(selected.body)}</textarea></label><div class="ls-narrative-editor-actions"><button type="button" data-action="narrative-save" ${readOnly ? 'disabled' : ''}>保存修改</button><button class="ls-danger" type="button" data-action="narrative-reset-entry" ${readOnly || !Object.prototype.hasOwnProperty.call(selectedCopyEntries, selected.id) ? 'disabled' : ''}>恢复本条默认</button><button type="button" data-action="narrative-copy-model">复制给模型</button></div><div class="ls-narrative-transfer-wrap"><textarea class="ls-narrative-transfer" placeholder="导出的 JSON 会显示在这里，也可以粘贴 JSON 导入当前副本">${escapeHtml(runtime.narrativeTransferText || '')}</textarea><div class="ls-narrative-actions"><button type="button" data-action="narrative-export">导出当前版本</button><button type="button" data-action="narrative-import" ${readOnly ? 'disabled' : ''}>导入到当前副本</button><button class="ls-danger" type="button" data-action="narrative-reset-copy" ${readOnly || Object.keys(selectedCopyEntries).length === 0 ? 'disabled' : ''}>当前副本全部恢复</button><button class="ls-danger" type="button" data-action="narrative-reset-all" ${copyCounts.copy1 + copyCounts.copy2 === 0 ? 'disabled' : ''}>全面恢复默认</button></div></div></section></div>`;
  }

  function buildDebugPreviewMarkup() {
    const preview = buildDebugPromptPreview();
    const labels = { protocol: '顶层', judgment: '判例层', narrative: '叙事层', state: '状态提醒', output: '尾部' };
    const layers = Object.entries(preview.layers).map(([key, content]) => `<details class="ls-debug-layer" ${key === 'judgment' ? 'open' : ''}><summary><span>${labels[key] || key}</span><small>${String(content || '').length}字</small></summary><pre>${escapeHtml(content || '（本组合不生成该层）')}</pre></details>`).join('');
    return `<div class="ls-debug-preview-head"><span>工作流：${preview.workflow_mode === WORKFLOW_MODES.EXTERNAL ? '外接 API' : '内置'}</span><span>组合：${escapeHtml(preview.combination_id)}</span></div>${layers}<details class="ls-debug-layer"><summary><span>预算信封</span><small>${preview.envelope.length}字</small></summary><pre>${escapeHtml(preview.envelope)}</pre></details>`;
  }

  function buildDebugContentFilterMarkup(trace) {
    const current = trace?.content_filter?.current_assistant;
    const recent = Array.isArray(trace?.content_filter?.recent_assistants) ? trace.content_filter.recent_assistants : [];
    if (!current) return '';
    const rows = [current, ...recent];
    const originalLength = rows.reduce((total, item) => total + Number(item?.original_length || 0), 0);
    const filteredLength = rows.reduce((total, item) => total + Number(item?.filtered_length || 0), 0);
    const matches = rows.reduce((total, item) => total + Number(item?.match_count || 0), 0);
    const htmlComments = rows.reduce((total, item) => total + Number(item?.html_comment_count || 0), 0);
    const modeLabel = current.mode === 'extract' ? '提取标签' : (current.mode === 'block' ? '屏蔽标签' : '不处理');
    const missing = rows.some((item) => item?.required_tag_missing === true);
    return `<div class="ls-debug-filter-summary${missing ? ' ls-debug-filter-warning' : ''}"><span>正文处理：${escapeHtml(modeLabel)}</span><span>原始 ${originalLength}字 → 发送 ${filteredLength}字</span><span>标签命中 ${matches} 段</span><span>HTML 注释 ${current.strip_html_comments === false ? '保留' : `屏蔽 ${htmlComments} 段`}</span>${missing ? '<strong>有助手楼层未命中提取标签</strong>' : ''}</div>`;
  }

  function buildDebugExternalMarkup() {
    const traces = runtime.externalDebugTraces;
    const pseudoStatus = runtime.debugExternalPseudoStatus === 'translator'
      ? '正在组装后置翻译伪请求…'
      : (runtime.debugExternalPseudoStatus === 'preflight'
        ? '正在组装前置推演伪请求…'
        : (runtime.debugExternalPseudoStatus === 'error' ? `伪发送失败：${runtime.debugExternalPseudoError}` : '不会请求外接 API，也不会结算状态'));
    const controls = `<div class="ls-debug-pseudo-controls"><div><strong>外接伪发送</strong><small>${escapeHtml(pseudoStatus)}</small></div><div><button type="button" data-action="debug-pseudo-external" data-pseudo-kind="translator" ${['translator', 'preflight'].includes(runtime.debugExternalPseudoStatus) ? 'disabled' : ''}>后置翻译</button><button type="button" data-action="debug-pseudo-external" data-pseudo-kind="preflight" ${['translator', 'preflight'].includes(runtime.debugExternalPseudoStatus) ? 'disabled' : ''}>前置推演</button></div></div>`;
    if (!traces.length) return `${controls}<div class="ls-debug-empty">尚未记录外接请求。“后置翻译”读取当前最后一个正文楼层；“前置推演”读取输入框或最后一条用户消息。</div>`;
    if (!Number.isInteger(runtime.debugExternalSelectedIndex) || runtime.debugExternalSelectedIndex < 0 || runtime.debugExternalSelectedIndex >= traces.length) {
      runtime.debugExternalSelectedIndex = traces.length - 1;
    }
    const selected = traces[runtime.debugExternalSelectedIndex];
    const list = traces.map((trace, index) => `<button class="ls-debug-trace-item" type="button" data-action="debug-external-trace" data-trace-index="${index}" aria-pressed="${String(index === runtime.debugExternalSelectedIndex)}"><span>${escapeHtml(trace.kind || trace.phase || '外接调用')}</span><small>${escapeHtml(trace.phase || '')} · ${escapeHtml(String(trace.captured_at || '').replace('T', ' ').replace(/\.\d{3}Z$/, 'Z'))}</small></button>`).join('');
    return `${controls}${buildDebugContentFilterMarkup(selected)}<div class="ls-debug-split"><div class="ls-debug-trace-list">${list}</div><section class="ls-debug-document"><div class="ls-debug-document-head"><div><strong>${escapeHtml(selected.kind || '外接调用')}</strong><small>${escapeHtml(selected.phase || '')}${selected.pseudo_send === true ? ' · 伪发送' : ''}</small></div><button type="button" data-action="debug-copy" data-copy-kind="external">复制</button></div><pre>${escapeHtml(JSON.stringify(selected, null, 2))}</pre></section></div>`;
  }

  function buildDebugLogsMarkup() {
    const diagnostics = getPromptDiagnostics();
    const logs = runtime.logs.length
      ? runtime.logs.map((item) => `[${item.time}] ${item.code}: ${item.message}`).join('\n')
      : '暂无运行记录';
    return `<details class="ls-debug-layer" open><summary><span>运行记录</span><small>${runtime.logs.length}条</small></summary><pre>${escapeHtml(logs)}</pre></details><details class="ls-debug-layer"><summary><span>Prompt 诊断</span></summary><pre>${escapeHtml(JSON.stringify(diagnostics, null, 2))}</pre></details>`;
  }

  function buildDebugCenterMarkup() {
    if (!runtime.debugUnlocked || !runtime.debugCenterOpen) return '';
    const tabs = [
      ['catalog', '提示词资料库'],
      ['narrative', '叙事编辑'],
      ['preview', '组合预览'],
      ['actual', '实际请求'],
      ['external', '外接调用'],
      ['logs', '运行记录'],
    ];
    const body = runtime.debugTab === 'narrative' ? buildNarrativeEditorMarkup()
      : runtime.debugTab === 'preview' ? buildDebugPreviewMarkup()
      : runtime.debugTab === 'actual' ? buildPromptViewerMarkup()
        : runtime.debugTab === 'external' ? buildDebugExternalMarkup()
          : runtime.debugTab === 'logs' ? buildDebugLogsMarkup()
            : buildDebugCatalogMarkup();
    return `<section class="ls-debug-center"><header class="ls-debug-center-head"><div><strong>调试中心</strong><small>RPE Prompt Debug API V1</small></div><div class="ls-debug-center-actions"><button type="button" data-action="debug-close">返回状态栏</button><button type="button" data-action="debug-lock">退出并锁定</button></div></header><nav class="ls-debug-tabs">${tabs.map(([id, label]) => `<button type="button" data-action="debug-tab" data-debug-tab="${id}" aria-pressed="${String(runtime.debugTab === id)}">${label}</button>`).join('')}</nav><div class="ls-debug-center-body">${body}</div></section>`;
  }

  function formatDuration(value, prefix = '') {
    const totalMinutes = Math.max(0, Math.round(Number(value) * 60));
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    let formatted;
    if (hours === 0) formatted = `${minutes} 分钟`;
    else if (minutes === 0) formatted = `${hours} 小时`;
    else formatted = `${hours} 小时 ${minutes} 分钟`;
    return `${prefix}${formatted}`;
  }

  function formatDays(value, prefix = '') {
    return `${prefix}${Math.round(Number(value))} 天`;
  }

  function formatGestationDays(value) {
    const days = Math.max(0, Math.round(Number(value)));
    return `${Math.floor(days / 7)}周＋${days % 7}天`;
  }

  function displayValue(value) {
    return VALUE_LABELS[value] || String(value);
  }

  function displayReproductiveValue(group, value) {
    const label = REPRODUCTIVE_LABELS[group]?.[value];
    if (label) return label;
    logStateError('unknown_reproductive_value', `生殖字段 ${group} 出现未识别值：${String(value)}`);
    return '未知状态';
  }

  function effectLabel(key, effect = null) {
    return EFFECT_LABELS[key] || playEffectLabel(key) || normalizeEffectName(effect?.name) || '持续影响';
  }

  const NEED_ICONS = Object.freeze({ drink: '水', meal: '食', urination: '尿', bowel_movement: '便', sleep: '眠' });

  function metaRow(label, value) {
    return `<div class="ls-meta-row"><span>${escapeHtml(label)}</span><span class="ls-meta-value">${escapeHtml(value)}</span></div>`;
  }

  function initialNeedOffsetForDisplay(characterName, needKey, need) {
    const profile = sanitizeCharacterProfiles(runtime.characterProfiles)[characterName];
    const offsets = sanitizeProfileInitialOffsets(profile?.initial_offsets);
    if (profile?.active === true && Object.prototype.hasOwnProperty.call(offsets, needKey)) return offsets[needKey];
    return deterministicInitialOffset(characterName, needKey, need?.stage);
  }

  function buildNeedCard(characterName, needKey, need) {
    const label = NEED_LABELS[needKey] || needKey;
    const stage = NEED_STAGES.has(need.stage) ? need.stage : '';
    const stageClass = stage ? ` ls-stage-${NEED_STAGE_ROUTE_IDS[stage]}` : '';
    const stageBadge = stage ? `<span class="ls-stage-badge">${escapeHtml(displayValue(stage))}</span>` : '';
    const useAwake = needKey === 'sleep' && 'awake_for' in need;
    const hasDuration = useAwake || Object.prototype.hasOwnProperty.call(need, 'elapsed');
    const hasInitialDuration = !hasDuration && !(needKey === 'sleep' && need.sleeping === true);
    const initialDuration = hasInitialDuration ? initialNeedOffsetForDisplay(characterName, needKey, need) : null;
    const mainValue = useAwake
      ? formatDuration(need.awake_for)
      : ('elapsed' in need ? formatDuration(need.elapsed) : (initialDuration !== null ? formatDuration(initialDuration) : (stage ? displayValue(stage) : '—')));
    const caption = useAwake ? '连续清醒' : ('elapsed' in need ? '距上次有效满足' : (initialDuration !== null ? '首次建档初值' : '暂无可靠时间锚点'));
    const meta = [];
    if (useAwake && 'elapsed' in need) meta.push(metaRow('距上次睡眠', formatDuration(need.elapsed)));
    if (!useAwake && 'awake_for' in need) meta.push(metaRow('连续清醒', formatDuration(need.awake_for)));
    if ('last_at' in need) meta.push(metaRow('最后满足', need.last_at));
    if ('wake_at' in need) meta.push(metaRow('起床时间', need.wake_at));
    if ('sleeping' in need) meta.push(metaRow('当前状态', need.sleeping ? '正在睡眠' : '清醒'));
    if ('notes' in need) meta.push(metaRow('说明', need.notes));
    if ('sleep_information' in need) meta.push(metaRow('睡眠情况', need.sleep_information));
    return `<article class="ls-need-card${stageClass}${hasDuration ? '' : ' ls-no-duration'}"><div class="ls-need-top"><span class="ls-need-icon">${escapeHtml(NEED_ICONS[needKey] || '项')}</span><span class="ls-need-name">${escapeHtml(label)}</span>${stageBadge}</div><div class="ls-need-time">${escapeHtml(mainValue)}</div><div class="ls-need-caption">${escapeHtml(caption)}</div>${meta.length ? `<div class="ls-meta">${meta.join('')}</div>` : ''}</article>`;
  }

  function buildEffectCard(key, effect, index = 0) {
    if (key === CYCLE_PRESENCE_KEY) {
      const context = cyclePresenceContext(runtime.snapshot?.characters?.[runtime.activeCharacter], runtime.snapshot?.timeline);
      const state = !context || effect.notes === context.baseline ? '阶段底稿' : '当前表现';
      return `<article class="ls-effect-card ls-builtin-cycle-effect"><div class="ls-effect-head"><span>${escapeHtml(effect.name || '周期影响')}</span><span class="ls-effect-status">内置 · ${state}</span></div><div class="ls-effect-details">${escapeHtml(effect.notes || context?.baseline || '')}</div><small class="ls-effect-removal-hint">随周期自动更新；关闭后不再增强周期表现。</small><div class="ls-effect-actions"><button class="ls-effect-end" type="button" data-action="cycle-presence-off">关闭当前聊天的周期增强</button></div></article>`;
    }
    const label = effectLabel(key, effect);
    const status = '持续中';
    const details = [];
    if ('elapsed' in effect) details.push(formatDuration(effect.elapsed, '已持续 '));
    if ('last_at' in effect) details.push(`时间 ${effect.last_at}`);
    if ('notes' in effect) details.push(effect.notes);
    const editable = isEditablePlayEffect(key);
    const editing = editable && runtime.effectEditor?.character === runtime.activeCharacter && runtime.effectEditor.effectKey === key;
    const editButton = editable ? `<button class="ls-effect-edit" type="button" data-action="edit-effect" data-effect-index="${index}">编辑当前状态</button>` : '';
    const nameEditor = !isPresetEffectKey(key) ? `<label>名称<input maxlength="24" data-role="effect-name-editor" value="${escapeHtml(normalizeEffectName(effect.name))}" placeholder="例如：手腕压痕"></label>` : '';
    const editor = editing ? `<div class="ls-effect-editor" data-draft-key="${escapeHtml(`effect:${JSON.stringify([runtime.activeCharacter, key])}`)}">${nameEditor}<textarea maxlength="500" data-role="effect-notes-editor" placeholder="填写当前仍在的部位、数量、佩戴或身体反应">${escapeHtml(effect.notes || '')}</textarea><div class="ls-effect-editor-actions"><button type="button" data-action="cancel-effect-edit">取消</button><button type="button" data-action="save-effect-edit" data-effect-index="${index}">保存</button></div></div>` : '';
    return `<article class="ls-effect-card"><div class="ls-effect-head"><span>${escapeHtml(label)}</span>${status ? `<span class="ls-effect-status">${escapeHtml(status)}</span>` : ''}</div>${details.length ? `<div class="ls-effect-details">${escapeHtml(details.join(' · '))}</div>` : ''}<div class="ls-effect-actions">${editButton}<button class="ls-effect-end" type="button" data-action="end-effect" data-effect-index="${index}">移除记录</button></div>${effectRemovalHint(key) ? `<small class="ls-effect-removal-hint">${escapeHtml(effectRemovalHint(key))}</small>` : ''}${editor}</article>`;
  }

  function buildGroupedEffectMarkup(effects) {
    const ordinary = [];
    const combinationGroups = new Map();
    effects.forEach(([key, effect], index) => {
      const parts = playEffectParts(key);
      const combination = parts ? playCombinationForEffect(key, runtime.playCombinations) : null;
      const selection = combination ? playCombinationSelection(combination) : null;
      if (combination?.layout_version === 2 && selection && !selection.legacy) {
        if (!combinationGroups.has(combination.id)) combinationGroups.set(combination.id, { combination, selection, items: [] });
        combinationGroups.get(combination.id).items.push({ key, effect, index, phase: parts.phase });
      } else {
        ordinary.push(buildEffectCard(key, effect, index));
      }
    });
    const phaseOrder = ['base', 'jewelry', 'accessory', 'extension', 'result', 'visible', 'recovery', 'process'];
    const grouped = [...combinationGroups.values()].map(({ combination, selection, items }) => {
      const cards = items.sort((left, right) => phaseOrder.indexOf(left.phase) - phaseOrder.indexOf(right.phase))
        .map((item) => buildEffectCard(item.key, item.effect, item.index)).join('');
      const groupLabel = combination.kind === 'marking' ? '标记' : '身体改造';
      return `<section class="ls-effect-group"><div class="ls-effect-group-title">${groupLabel}｜${escapeHtml(selection.entry.label)}</div>${cards}</section>`;
    });
    return Object.freeze({ markup: [...ordinary, ...grouped].join(''), count: ordinary.length + grouped.length });
  }

  function buildConceptionResultMarkup(name, conception) {
    if (!name || conception?.outcome !== '待判定' || !Number.isInteger(conception.window_id)) return '';
    const key = JSON.stringify([operationChatIdentity(runtime.adapter),name,conception.window_id,conception.window_started_at]);
    const pending = runtime.conceptionResultPending?.has(key) || runtime.generationActive || runtime.externalStatus === 'translating';
    return `<details class="ls-conception-result" data-result-key="${escapeHtml(key)}"${runtime.conceptionResultExpanded?.has(key)?' open':''}><summary>手动指定本次结果</summary><small class="ls-pregnancy-awareness-help">仅结束当前窗口，不改变以后事件的规则，也不自动让双方知情。</small><div class="ls-pregnancy-awareness-options">${['已受孕','未受孕'].map(value => `<button type="button" data-action="conception-result" data-character-name="${escapeHtml(name)}" data-result="${value}" data-window-id="${conception.window_id}" data-window-start="${escapeHtml(conception.window_started_at)}"${pending ? ' disabled' : ''}>指定${value}</button>`).join('')}</div></details>`;
  }

  function bindConceptionResultDetails(panel) {
    panel.addEventListener('click',event=>{
      const summary=event.target.closest?.('.ls-conception-result > summary'), item=summary?.parentElement;
      if(!item)return;
      if(!runtime.conceptionResultExpanded)runtime.conceptionResultExpanded=new Set();
      if(item.open)runtime.conceptionResultExpanded.delete(item.dataset.resultKey);else runtime.conceptionResultExpanded.add(item.dataset.resultKey);
    },true);
    panel.addEventListener('toggle',event=>{
      const item=event.target;
      if (!item?.isConnected || !item.matches?.('.ls-conception-result')) return;
      if (!runtime.conceptionResultExpanded) runtime.conceptionResultExpanded=new Set();
      if(item.open)runtime.conceptionResultExpanded.add(item.dataset.resultKey);else runtime.conceptionResultExpanded.delete(item.dataset.resultKey);
    },true);
  }

  function queueConceptionResultChange(button, event) {
    event?.preventDefault(); event?.stopPropagation();
    const name = button.dataset.characterName;
    const key=button.closest('.ls-conception-result')?.dataset.resultKey, adapter=runtime.adapter, identity=operationChatIdentity(adapter);
    if (!runtime.conceptionResultPending) runtime.conceptionResultPending = new Set();
    if (runtime.conceptionResultPending.has(key)) return;
    runtime.conceptionResultPending.add(key); button.disabled = true;
    setConceptionResult(name, button.dataset.result, adapter, { window_id: Number(button.dataset.windowId), window_started_at: button.dataset.windowStart })
      .catch(error => { if(operationChatIdentity(adapter)===identity){setManualSaveNotice(error.message);logStateError('conception_result_failed',error.message);} })
      .finally(() => { runtime.conceptionResultPending.delete(key); refreshStatePanel(); });
  }

  function buildPregnancyAwarenessMarkup(characterName, pregnancy, kind = 'pregnancy') {
    if (!characterName || !isPlainObject(pregnancy)) return '';
    if (kind === 'conception' && pregnancy.outcome !== '待判定') return '';
    const topic = kind === 'conception' ? '受孕风险' : '孕期';
    const windowAttributes = kind === 'conception'
      ? ` data-awareness-window-id="${escapeHtml(pregnancy.window_id)}" data-awareness-window-start="${escapeHtml(pregnancy.window_started_at)}"` : '';
    const rows = [['character_awareness', '角色本人'], ['user_awareness', 'User角色']].map(([field, label]) => {
      const current = pregnancy[field] === '已知' ? '已知' : '未知';
      const pending = runtime.pregnancyAwarenessPending.has(JSON.stringify([characterName, kind, field]));
      const buttons = ['已知', '未知'].map((value) => `<button type="button" data-action="pregnancy-awareness" data-awareness-kind="${kind}"${windowAttributes} data-character-name="${escapeHtml(characterName)}" data-awareness-field="${field}" data-awareness-value="${value}" aria-pressed="${String(current === value)}"${pending ? ' disabled' : ''}>${value}</button>`).join('');
      return `<div class="ls-pregnancy-awareness-row"><span>${label}</span><div class="ls-pregnancy-awareness-options" role="group" aria-label="${escapeHtml(characterName)} · ${label}的${topic}认知" aria-busy="${String(pending)}">${buttons}</div></div>`;
    }).join('');
    return `<div class="ls-pregnancy-awareness">${rows}<small class="ls-pregnancy-awareness-help">修改当前认知，后续可随剧情更新</small>${kind === 'conception' ? buildConceptionResultMarkup(characterName,pregnancy) : ''}</div>`;
  }

  function syncPregnancyAwarenessControls(document = runtime.hostDocument || getHostDocument()) {
    for (const panelId of [CONFIG.panelId, CONFIG.inlinePanelId]) {
      const buttons = document?.getElementById(panelId)?.querySelectorAll('[data-action="pregnancy-awareness"]') || [];
      for (const button of buttons) {
        const { characterName, awarenessField, awarenessValue, awarenessKind = 'pregnancy' } = button.dataset;
        const pregnancy = runtime.snapshot?.characters?.[characterName]?.reproductive?.[awarenessKind];
        const pending = runtime.pregnancyAwarenessPending.has(JSON.stringify([characterName, awarenessKind, awarenessField]));
        button.disabled = pending || !isPlainObject(pregnancy);
        button.setAttribute('aria-pressed', String((pregnancy?.[awarenessField] === '已知' ? '已知' : '未知') === awarenessValue));
        button.closest('.ls-pregnancy-awareness-options')?.setAttribute('aria-busy', String(pending));
      }
    }
  }

  function queuePregnancyAwarenessChange(button, event) {
    event.preventDefault();
    event.stopPropagation();

    if (button.disabled) return;
    const { characterName, awarenessField, awarenessValue, awarenessKind = 'pregnancy' } = button.dataset;
    if (!characterName || !['character_awareness', 'user_awareness'].includes(awarenessField)
      || !['已知', '未知'].includes(awarenessValue)) return;
    const pregnancy = runtime.snapshot?.characters?.[characterName]?.reproductive?.[awarenessKind];
    if (!isPlainObject(pregnancy) || (pregnancy[awarenessField] === '已知' ? '已知' : '未知') === awarenessValue) return;
    const expectedWindow = awarenessKind === 'conception' ? {
      window_id: Number(button.dataset.awarenessWindowId), window_started_at: button.dataset.awarenessWindowStart,
    } : null;
    const key = JSON.stringify([characterName, awarenessKind, awarenessField]);
    if (runtime.pregnancyAwarenessPending.has(key)) return;
    const adapter = runtime.adapter;
    const chatIdentity = tavernChatIdentity(resolveSillyTavernContext());
    runtime.pregnancyAwarenessPending.add(key);
    syncPregnancyAwarenessControls(button.ownerDocument);
    runtime.queue = runtime.queue
      .then(() => {
        if (adapter !== runtime.adapter || chatIdentity !== tavernChatIdentity(resolveSillyTavernContext())) return;
        return setReproductiveAwareness(characterName, awarenessKind, awarenessField, awarenessValue, adapter, expectedWindow);
      })
      .catch((error) => logStateError('pregnancy_awareness_change_failed', error, 'error'))
      .finally(() => {
        runtime.pregnancyAwarenessPending.delete(key);
        syncPregnancyAwarenessControls(button.ownerDocument);
      });
  }

  function reproductiveCard(icon, title, mainValue, caption, record, metaItems = [], controls = '') {
    const stage = NEED_STAGES.has(record?.stage) ? record.stage : '';
    const stageClass = stage ? ` ls-stage-${NEED_STAGE_ROUTE_IDS[stage]}` : '';
    const stageBadge = stage ? `<span class="ls-stage-badge">${escapeHtml(displayValue(stage))}</span>` : '';
    const meta = metaItems.filter((item) => item && item[1] !== undefined && item[1] !== null && item[1] !== '')
      .map(([label, value]) => metaRow(label, value));
    if (record?.notes) meta.push(metaRow('说明', record.notes));
    return `<article class="ls-need-card ls-repro-card${stageClass}"><div class="ls-need-top"><span class="ls-need-icon">${runtime.uiStyle === UI_STYLES.MODERN && icon === '经' ? modernUiIcon('cycle') : escapeHtml(icon)}</span><span class="ls-need-name">${escapeHtml(title)}</span>${stageBadge}</div><div class="ls-need-time">${escapeHtml(mainValue)}</div><div class="ls-need-caption">${escapeHtml(caption)}</div>${meta.length ? `<div class="ls-meta">${meta.join('')}</div>` : ''}${controls}</article>`;
  }

  function buildReproductiveSection(reproductive, characterName = '') {
    if (!isPlainObject(reproductive) && !characterName) return '';
    const cards = [];
    const cycle = reproductive?.menstrual_cycle;
    if (isPlainObject(cycle)) {
      const main = 'cycle_day' in cycle ? `第${cycle.cycle_day}天` : displayReproductiveValue('cyclePhase', cycle.phase || '周期未知');
      cards.push(reproductiveCard('经', '月经周期', main, displayReproductiveValue('cyclePhase', cycle.phase || '周期未知'), cycle, [
        ['周期起点', cycle.last_period_start_at],
        ['知情提示', cycle.user_awareness === '未知' ? 'User 不知道具体经期' : ''],
      ]));
    }
    const conception = reproductive?.conception;
    if (isPlainObject(conception)) {
      const main = 'elapsed_days' in conception
        ? `${conception.elapsed_days}／7天`
        : displayReproductiveValue('conceptionOutcome', conception.outcome || '待判定');
      const ledgerEntries = Object.values(sanitizeConceptionEventLedger(runtime.conceptionEventLedger))
        .filter((entry) => entry.character === characterName && entry.window_id === conception.window_id && entry.closed !== true);
      const sceneSummary = sceneRiskGroups(ledgerEntries).map(({ scene, risk }) => `场景${scene} ${risk}%`).join(' · ');
      cards.push(reproductiveCard('判', '受孕判定', main, displayReproductiveValue('conceptionOutcome', conception.outcome || '待判定'), conception, [
        ['最低暴露', conception.sperm_entered === '是' ? '已形成' : (conception.sperm_entered === '否' ? '未形成' : '')],
        ['情况', conception.situation],
        ['单次风险', 'event_risk_percent' in conception ? `${conception.event_risk_percent}%` : ''],
        ['实际综合风险', 'combined_risk_percent' in conception ? `${conception.combined_risk_percent}%` : ''],
        ['场景贡献', sceneSummary],
        ['受孕窗口ID', conception.window_id],
        ['NSFW场景ID', conception.scene_id],
        ['窗口起点', conception.window_started_at],
        ['最后风险时间', conception.last_risk_at],
        ...(!characterName ? [['角色本人', conception.character_awareness || '未知'], ['User角色', conception.user_awareness || '未知']] : []),
      ], buildPregnancyAwarenessMarkup(characterName, conception, 'conception')));
    }
    const pregnancy = reproductive?.pregnancy;
    if (isPlainObject(pregnancy)) {
      const main = 'gestation_days' in pregnancy
        ? formatGestationDays(pregnancy.gestation_days)
        : (pregnancy.phase ? displayReproductiveValue('pregnancyPhase', pregnancy.phase) : displayReproductiveValue('pregnancyConfirmation', pregnancy.confirmation));
      const caption = pregnancy.phase ? displayReproductiveValue('pregnancyPhase', pregnancy.phase) : displayReproductiveValue('pregnancyConfirmation', pregnancy.confirmation);
      cards.push(reproductiveCard('孕', '孕期追踪', main, caption, pregnancy, [
        ['确认', 'confirmation' in pregnancy ? displayReproductiveValue('pregnancyConfirmation', pregnancy.confirmation) : ''],
        ['末次月经', pregnancy.last_period_start_at],
        ['预产期', pregnancy.estimated_due_at],
        ...(!characterName ? [['角色本人', pregnancy.character_awareness || '未知'], ['User角色', pregnancy.user_awareness || '未知']] : []),
      ], buildPregnancyAwarenessMarkup(characterName, pregnancy)));
    }
    const decisions = conceptionDecisionNotices(runtime.conceptionDecisionLedger, runtime.activeConceptionDecisions)
      .filter((notice) => notice.character === characterName);
    for (const decision of decisions) {
      cards.push(reproductiveCard('果', '受孕后台结算', decision.outcome, `实际综合风险 ${decision.probabilityPercent}%`, {}, [
        ['后台结果', decision.outcome],
        ['结算概率', `${decision.probabilityPercent}%`],
        ['剧情认知', '角色与User仍按各自已经获得的信息行动'],
      ]));
    }
    if (!isPlainObject(conception)) {
      const zeroed = Object.values(sanitizeConceptionEventLedger(runtime.conceptionEventLedger))
        .filter((entry) => entry.character === characterName && entry.closed && entry.resolution === '风险已解除')
        .sort((left, right) => (right.window_id || 0) - (left.window_id || 0))[0];
      if (zeroed) {
        cards.push(reproductiveCard('零', '受孕风险审计', '0%', '风险已解除', {}, [
          ['受孕窗口ID', zeroed.window_id],
          ['最后风险时间', zeroed.last_risk_at],
          ['记录', '零值记录已保留，不会因分支重建复活'],
        ]));
      }
    }
    return cards.length
      ? `<section class="ls-section"><h3 class="ls-section-title">生殖状态<span class="ls-section-count">${cards.length}</span></h3><div class="ls-need-grid">${cards.join('')}</div></section>`
      : '';
  }

  function buildCharacterTab(name, character, index, activeName) {
    const retained = character.mode === 'retained';
    const modeLabel = retained ? '最小因果保留' : '同行详细关注';
    return `<button class="ls-character-tab${retained ? ' ls-tab-retained' : ''}" type="button" role="tab" data-action="character" data-character-index="${index}" aria-selected="${String(name === activeName)}"><span class="ls-avatar">${escapeHtml(Array.from(name)[0] || '角')}</span><span class="ls-tab-copy"><span class="ls-tab-name">${escapeHtml(name)}</span><span class="ls-tab-mode">${modeLabel}</span></span></button>`;
  }

  function buildCharacterMarkup(name, character, modern = false) {
    const retained = character.mode === 'retained';
    const needs = NEED_KEYS
      .map((key) => [key, character.needs?.[key]])
      .filter(([, need]) => isPlainObject(need));
    const effects = Object.entries(character.effects || {}).filter(([, effect]) => isPlainObject(effect));
    const groupedEffects = buildGroupedEffectMarkup(effects);
    const subtitle = 'observed_for' in character
      ? `已连续观察 ${formatDuration(character.observed_for)}`
      : (retained ? '保留尚未结束的最小因果' : '持续观察中');
    const modeLabel = retained ? '最小因果保留' : '同行详细关注';
    const needSection = needs.length
      ? `<section class="ls-section ls-daily-section"><h3 class="ls-section-title">${modern ? modernUiIcon('status')+'日常状态' : '身体需求'}<span class="ls-section-count">${needs.length}</span></h3><div class="${modern ? 'ls-modern-needs' : 'ls-need-grid'}">${needs.map(([key, need]) => modern ? buildModernNeedRow(name, key, need) : buildNeedCard(name, key, need)).join('')}</div></section>`
      : '';
    const effectSection = effects.length
      ? `<section class="ls-section ls-effects-section"><h3 class="ls-section-title">${modern ? modernUiIcon('effect') : ''}持续影响<span class="ls-section-count">${groupedEffects.count}</span></h3><div class="ls-effect-list">${groupedEffects.markup}</div></section>`
      : '';
    const reproductiveSection = buildReproductiveSection(character.reproductive, name);
    const desireProfile = runtime.sexualDesireProfiles?.[name];
    const desireBaseline = runtime.sexualDesireBaselines?.[name] || desireProfile?.baseline || '常态';
    const desireSection = effectiveRuntimeModules().sexual_desire && !retained && desireProfile
      ? `<section class="ls-section"><h3 class="ls-section-title">性欲状态</h3><div class="ls-desire-card"><div class="ls-desire-value"><span class="ls-desire-score">${escapeHtml(desireProfile.score)}</span><span class="ls-desire-stage">${escapeHtml(desireProfile.stage)}</span></div><div class="ls-desire-baselines" aria-label="选择性欲基线">${['偏低', '常态', '偏高'].map((baseline) => `<button class="ls-desire-baseline" type="button" data-action="sexual-desire-baseline" data-baseline="${baseline}" aria-pressed="${String(desireBaseline === baseline)}">${baseline}</button>`).join('')}</div></div></section>`
      : '';
    if (modern) return `<article class="ls-profile${retained ? ' ls-profile-retained' : ''}"><header class="ls-profile-head"><div class="ls-profile-identity"><span class="ls-sunny-seal" aria-hidden="true">${escapeHtml(Array.from(name)[0] || '')}</span><div class="ls-profile-copy"><small class="ls-modern-eyebrow">当前人物 · ${retained ? '简要记录' : '详细记录'}</small><div class="ls-profile-name">${escapeHtml(name)}</div><div class="ls-profile-subtitle">${escapeHtml(subtitle)}</div></div></div><button class="ls-modern-edit" type="button" data-action="modern-edit-character" data-character-name="${escapeHtml(name)}">${modernUiIcon('edit')}编辑档案</button></header><div class="ls-modern-columns${needs.length ? '' : ' ls-without-needs'}">${needSection}<div class="ls-modern-secondary">${reproductiveSection}${desireSection}${buildStaminaMarkup(name, character)}${effectSection}</div></div></article>`;
    return `<article class="ls-profile${retained ? ' ls-profile-retained' : ''}"><header class="ls-profile-head"><div><div class="ls-profile-name">${escapeHtml(name)}</div><div class="ls-profile-subtitle">${escapeHtml(subtitle)}</div></div><span class="ls-mode-badge">${modeLabel}</span></header>${desireSection}${buildStaminaMarkup(name, character)}${needSection}${effectSection}${reproductiveSection}</article>`;
  }

  function availableArchiveNames(snapshot = runtime.snapshot, archives = runtime.archives) {
    const activeNames = new Set(isPlainObject(snapshot?.characters) ? Object.keys(snapshot.characters) : []);
    return Object.keys(sanitizeArchiveMap(archives)).filter((name) => !activeNames.has(name));
  }

  function archiveKindLabel(entry) {
    const reproductive = entry?.reproductive;
    const kinds = [];
    if (isPlainObject(reproductive?.menstrual_cycle)) kinds.push(reproductive.menstrual_cycle.user_awareness === '未知' ? '周期（User不知情）' : '周期');
    if (isPlainObject(reproductive?.conception)) kinds.push(reproductive.conception.user_awareness === '未知' ? '受孕（User不知情）' : '受孕');
    if (isPlainObject(reproductive?.pregnancy)) kinds.push(reproductive.pregnancy.user_awareness === '未知' ? '孕期（User不知情）' : '孕期');
    return kinds.join('、') || '离场身体档案';
  }

  function buildArchivePickerMarkup(snapshot = runtime.snapshot, archives = runtime.archives, pendingRestore = runtime.pendingRestore) {
    const names = availableArchiveNames(snapshot, archives);
    if (names.length === 0) return '<div class="ls-archive-picker"><div class="ls-archive-title">没有可恢复的离场档案</div></div>';
    const buttons = names.map((name, index) => {
      const selected = pendingRestore?.name === name;
      return `<div class="ls-archive-item" aria-pressed="${String(selected)}"><button class="ls-archive-main" type="button" data-action="restore-archive" data-archive-index="${index}"><span class="ls-archive-name">${escapeHtml(name)}</span><br><span class="ls-archive-kind">${escapeHtml(selected ? '等待下次生成恢复' : archiveKindLabel(archives[name]))}</span></button><button class="ls-archive-delete" type="button" data-action="delete-archive" data-archive-index="${index}" title="只删除脚本长期档案">删除</button></div>`;
    }).join('');
    return `<div class="ls-archive-picker"><div class="ls-archive-title">恢复长期档案</div><div class="ls-archive-help">选择角色后，将在下一次生成前注入最后锚点；脚本不会直接改写当前状态。</div><div class="ls-archive-list">${buttons}</div></div>`;
  }

  function buildCharacterProfileEditorMarkup(profile, character, dailyNeeds, reproductiveEnabled, custom = false) {
    const editorId = `ls-profile-editor-${++profileEditorSequence}`;
    const sex = normalizeCharacterProfileSex(profile?.sex);
    const initialStages = sanitizeProfileInitialStages(profile?.initial_stages);
    const stageRows = dailyNeeds.map((needKey) => {
      const selectedStage = NEED_STAGES.has(character?.needs?.[needKey]?.stage)
        ? character.needs[needKey].stage
        : (initialStages[needKey] || '平稳期');
      return buildProfileStageControlMarkup(needKey, selectedStage, editorId);
    }).join('');
    const cycleRow = reproductiveEnabled ? buildProfileCycleControlMarkup(profile, character, sex) : '';
    const nameRow = custom
      ? '<label class="ls-character-profile-name-input"><span>姓名</span><input type="text" maxlength="120" data-role="character-profile-name" placeholder="输入人物姓名"></label>'
      : '';
    const note = custom ? '填写姓名并选择初始状态。' : '修改后会立即更新当前档案。';
    return `<div class="ls-character-profile-setup ls-profile-editor${custom ? ' ls-character-profile-custom' : ''}" data-draft-key="${escapeHtml(`profile:${JSON.stringify(custom ? null : profile.name)}`)}"><div class="ls-character-profile-setup-note">${note}</div>${nameRow}${buildProfileSexControlMarkup(sex, editorId)}${stageRows ? `<div class="ls-pe-section-heading"><h4>日常状态</h4><span>选择当前阶段</span></div><div class="ls-character-profile-stages">${stageRows}</div>` : '<div class="ls-character-profile-setup-note">当前没有开启日常追踪项。</div>'}${cycleRow}${buildStaminaEditor(profile?.name)}<div class="ls-pe-actions"><button type="button" data-action="${custom ? 'custom-character-profile' : 'cancel-character-profile'}">取消</button><button class="ls-pe-save" type="button" data-action="${custom ? 'confirm-custom-character-profile' : 'confirm-character-profile'}"${custom ? '' : ` data-profile-name="${escapeHtml(profile.name)}"`}>${custom ? '建立档案' : '保存档案'}</button></div></div>`;
  }

  function buildCharacterProfileManagerMarkup(snapshot = runtime.snapshot, inputProfiles = runtime.characterProfiles, setupName = runtime.characterProfileSetupName, setupDailyNeeds = effectiveRuntimeModules().daily_needs, customOpen = runtime.characterProfileCustomOpen, setupReproductive = effectiveRuntimeModules().reproductive) {
    const profileMap = sanitizeCharacterProfiles(inputProfiles);
    for (const name of Object.keys(isPlainObject(snapshot?.characters) ? snapshot.characters : {})) {
      const normalizedName = normalizeCharacterProfileName(name);
      if (!normalizedName) continue;
      const existingName = Object.keys(profileMap).find((item) => item.toLocaleLowerCase() === normalizedName.toLocaleLowerCase());
      if (existingName) {
        if (profileMap[existingName].sex === 'unknown' && isPlainObject(snapshot.characters[name]?.reproductive)) {
          profileMap[existingName] = { ...profileMap[existingName], sex: 'female' };
        }
        continue;
      }
      profileMap[normalizedName] = {
        name: normalizedName,
        sex: isPlainObject(snapshot.characters[name]?.reproductive) ? 'female' : 'unknown',
        summary: '当前档案',
        wake_start: '07:00',
        wake_end: '09:00',
        active: false,
      };
    }
    const profiles = Object.values(profileMap).sort((left, right) => {
      const leftCurrent = isPlainObject(snapshot?.characters?.[left.name]);
      const rightCurrent = isPlainObject(snapshot?.characters?.[right.name]);
      return Number(rightCurrent) - Number(leftCurrent) || Number(right.active) - Number(left.active);
    });
    const scanning = runtime.characterProfileScanStatus === 'scanning';
    const status = scanning
      ? (runtime.characterProfileScanReport?.repair_status === 'repairing' ? '正在修复扫描格式…' : runtime.characterProfileScanRetrying ? '接口未接受格式要求，正在兼容重试…' : '正在读取角色卡并分析人物…')
      : (runtime.characterProfileScanStatus === 'error'
        ? `扫描失败：${runtime.characterProfileScanError || '未知错误'}`
        : (runtime.characterProfileScanReport?.repair_status === 'repaired' ? `已修复格式，列出 ${profiles.length} 人，请选择需要建档的人物。` : profiles.length > 0 ? `已列出 ${profiles.length} 人` : '点击扫描当前角色卡与角色世界书'));
    const sexLabels = { female: '女', male: '男', unknown: '未知' };
    const selectedNeeds = new Set(Array.isArray(setupDailyNeeds) ? setupDailyNeeds : []);
    const dailyNeeds = NEED_KEYS.filter((needKey) => selectedNeeds.has(needKey));
    const cards = profiles.map((profile) => {
      const character = snapshot?.characters?.[profile.name];
      const inSnapshot = isPlainObject(character);
      const setting = setupName === profile.name;
      const setup = setting ? buildCharacterProfileEditorMarkup(profile, character, dailyNeeds, setupReproductive, false) : '';
      const action = setting
        ? `<button type="button" data-action="cancel-character-profile">取消</button>`
        : (profile.active
          ? `<div class="ls-character-profile-actions"><button type="button" data-action="prepare-character-profile" data-profile-name="${escapeHtml(profile.name)}">编辑</button><button type="button" data-action="toggle-character-profile" data-profile-name="${escapeHtml(profile.name)}" data-profile-active="true">删档</button></div>`
          : `<button type="button" data-action="prepare-character-profile" data-profile-name="${escapeHtml(profile.name)}">${inSnapshot ? '编辑并保留' : '建档'}</button>`);
      return `<article class="ls-character-profile-card${profile.active ? ' ls-character-profile-active' : ''}${setting ? ' ls-character-profile-setting' : ''}"><div class="ls-character-profile-copy"><div class="ls-character-profile-name">${escapeHtml(profile.name)}<span>${sexLabels[profile.sex]}</span>${inSnapshot ? '<span>当前有档案</span>' : ''}</div><div class="ls-character-profile-summary">${escapeHtml(profile.summary)}</div><div class="ls-character-profile-wake">通常在 ${escapeHtml(profile.wake_start)}–${escapeHtml(profile.wake_end)} 起床</div></div>${action}${setup}</article>`;
    }).join('');
    const customEditor = customOpen
      ? buildCharacterProfileEditorMarkup({ sex: 'unknown' }, null, dailyNeeds, setupReproductive, true)
      : '';
    return `<section class="ls-character-profile-manager"><div class="ls-effect-mode-control ls-auto-profile-control"><div class="ls-effect-mode-options"><span class="ls-effect-mode-label">自动建档</span><button class="ls-format-button ls-effect-mode-option" type="button" data-action="auto-profile" aria-pressed="${runtime.autoProfileEnabled !== false}">${runtime.autoProfileEnabled !== false ? '开' : '关'}</button><button class="ls-effect-help-toggle" type="button" data-action="auto-profile-help" aria-label="自动建档说明" aria-expanded="${runtime.autoProfileHelpOpen === true}"><span aria-hidden="true">?</span></button></div>${runtime.autoProfileHelpOpen ? '<div class="ls-effect-help" role="note">开启时，模型可以自动建档，也能手动添加。关闭后，只由用户手动建档；已有档案照常更新。</div>' : ''}</div><header class="ls-character-profile-head"><div><div class="ls-character-profile-title">人物档案</div><div class="ls-character-profile-status">${escapeHtml(status)}</div></div><div class="ls-character-profile-head-actions"><button type="button" data-action="scan-character-profiles"${scanning ? ' disabled' : ''}>${scanning ? '扫描中…' : '扫描角色卡'}</button><span class="ls-scan-compatibility-actions" role="group" aria-label="兼容扫描与说明"><button type="button" data-action="scan-character-profiles-compatible"${scanning ? ' disabled' : ''}>兼容扫描</button><button class="ls-effect-help-toggle" type="button" data-action="scan-compatibility-help" aria-label="兼容扫描说明" aria-expanded="${runtime.scanCompatibilityHelpOpen === true}"><span aria-hidden="true">?</span>说明</button></span><button type="button" data-action="custom-character-profile" aria-pressed="${String(customOpen)}">自定义建档</button><button type="button" data-action="character-profiles">关闭</button></div></header>${runtime.scanCompatibilityHelpOpen ? '<div class="ls-effect-help ls-scan-compatibility-help" role="note">普通扫描报“参数无效”等错误时，可尝试兼容扫描，尤其适用于 Gemini 或部分中转接口。仍使用当前酒馆连接和模型，结果检查后进入同一候选名单，不会自动全部建档。若回复因长度限制中断，可适当提高酒馆的回复长度后重试。</div>' : ''}${buildPeopleSupportMarkup()}${customEditor}<div class="ls-character-profile-list">${cards || '<div class="ls-character-profile-empty">扫描角色卡，或直接自定义建档。</div>'}</div></section>`;
  }

  function getPlayPageSize(document = runtime.hostDocument) {
    const width = document?.documentElement?.clientWidth || document?.defaultView?.innerWidth || 0;
    return width > 0 && width <= 720 ? 4 : 6;
  }

  const PLAY_CONTROL_TOOL_IDS = Object.freeze(['smart_chastity_belt', 'smart_chastity_belt_arousal', 'metal_chastity_belt']);
  const PLAY_STRIKING_IDS = Object.freeze(STRIKING_LIBRARY_ENTRIES.map((entry) => entry.id));
  const PLAY_TOOL_IDS = Object.freeze([...PLAY_CONTROL_TOOL_IDS, ...PLAY_STRIKING_IDS]);
  const PLAY_DRUG_GROUPS = Object.freeze([
    Object.freeze({ label: '氟班色林', ids: Object.freeze(['flibanserin', 'flibanserin_x']) }),
    Object.freeze({ label: '比沙可啶', ids: Object.freeze(['bisacodyl', 'bisacodyl_x']) }),
    Object.freeze({ label: '呋塞米', ids: Object.freeze(['furosemide', 'furosemide_x']) }),
    Object.freeze({ label: '黄体酮', ids: Object.freeze(['progesterone', 'progesterone_x']) }),
  ]);

  function activePlayCategoryLabels(playIds = runtime.activePlayIds, combinations = runtime.playCombinations) {
    const selected = new Set(normalizeActivePlayIds(playIds));
    const labels = [];
    const activeCombinations = sanitizePlayCombinations(combinations).filter((item) => item.active !== false);
    if (PLAY_TOOL_IDS.some((id) => selected.has(id)) || activeCombinations.some((item) => item.kind !== 'restraint' && NARRATIVE_LIBRARY_PLAY_KINDS.includes(item.kind))) labels.push('道具');
    if (PLAY_DRUG_GROUPS.some((group) => group.ids.some((id) => selected.has(id)))) labels.push('药物');
    if (activeCombinations.some((item) => item.kind === 'marking')) labels.push('标记');
    if (activeCombinations.some((item) => item.kind === 'body_modification')) labels.push('身体改造');
    if (activeCombinations.some((item) => item.kind === 'clamp_pressure')) labels.push('夹持与牵引');
    if (activeCombinations.some((item) => item.kind === 'restraint')) labels.push('捆绑与束具');
    return Object.freeze(labels);
  }

  function buildActivePlayStatusMarkup() {
    const labels = activePlayCategoryLabels();
    if (labels.length === 0) return '';
    return `<div class="ls-active-play-status"><span>当前玩法：<strong>${escapeHtml(labels.join('、'))}</strong></span><button type="button" data-action="clear-play-injection" title="清空玩法原文与待执行过程，已建立状态保留">清空玩法注入</button><small>已建立状态保留</small></div>`;
  }

  function activePlayCombinationCards() {
    const combinations = sanitizePlayCombinations(runtime.playCombinations).filter((combination) => combination.active !== false);
    if (combinations.length === 0) return '<div class="ls-play-empty">当前没有应用到角色的玩法搭配。</div>';
    return combinations.map((combination) => {
      const selection = playCombinationSelection(combination);
      const completed = playCombinationIsCompleted(combination, runtime.snapshot);
      const manualCompletion = combination.layout_version === 2
        && ((combination.kind === 'marking' && !selection?.wearable) || combination.kind === 'body_modification');
      const pendingDescriptor = pendingStateEffectDescriptor(combination);
      const pendingEffect = pendingDescriptor
        ? runtime.snapshot?.characters?.[combination.character]?.effects?.[pendingDescriptor.key] : null;
      const summary = manualCompletion && !completed
        ? '进行中，完成后建立状态'
        : (pendingDescriptor
        ? (effectIsPersisting(pendingEffect) ? '当前状态已建立' : '本次准备')
        : (selection?.narrativeOnly ? '本次准备'
        : (combination.kind === 'body_modification' && !selection?.legacy
        ? `${bodyModificationEffectDescriptors({ ...combination, completed: true }).length} 项当前状态`
        : (combination.kind === 'marking' && !selection?.legacy ? '当前状态已建立' : '本次准备'))));
      const completeButton = (['restraint', 'marking', 'body_modification'].includes(combination.kind)
        ? `<button type="button" data-action="insert-play-input-draft" data-combination-id="${combination.id}">填入草稿</button>` : '')
        + (manualCompletion && !completed
        ? `<button type="button" data-action="complete-play-combination" data-combination-id="${combination.id}">完成并建立状态</button>` : '');
      return `<article class="ls-play-combination-card"><div><strong>${escapeHtml(selection?.label || '玩法搭配')}</strong><small>${escapeHtml(combination.character)}｜${escapeHtml(summary)}</small></div><div class="ls-play-combination-actions">${completeButton}<button type="button" data-action="edit-play-combination" data-combination-id="${combination.id}">修改</button><button type="button" data-action="remove-play-combination" data-combination-id="${combination.id}">移除搭配</button></div></article>`;
    }).join('');
  }

  function buildCurrentPlayCombinationsMarkup() {
    const count = sanitizePlayCombinations(runtime.playCombinations).filter((combination) => combination.active !== false).length;
    return `<details class="ls-play-current"${runtime.playEditingId ? ' open' : ''}><summary><strong>当前搭配</strong><span>${count} 套 · 展开管理</span></summary><div class="ls-play-current-body"><div class="ls-play-current-head"><small>移除后停止对应原文注入，已经建立的状态不受影响</small><button type="button" data-action="clear-play-combinations"${count === 0 ? ' disabled' : ''}>清空搭配</button></div><div class="ls-play-combination-list">${activePlayCombinationCards()}</div></div></details>`;
  }

  function buildPlayLibraryHome() {
    const activeNarrativeTools = sanitizePlayCombinations(runtime.playCombinations).filter((item) => item.active !== false && item.kind !== 'restraint' && NARRATIVE_LIBRARY_PLAY_KINDS.includes(item.kind)).length;
    const activeTools = PLAY_TOOL_IDS.filter((id) => runtime.activePlayIds.includes(id)).length + activeNarrativeTools;
    const drugIds = PLAY_DRUG_GROUPS.flatMap((group) => group.ids);
    const activeDrugs = drugIds.filter((id) => runtime.activePlayIds.includes(id)).length;
    const activeMarkings = sanitizePlayCombinations(runtime.playCombinations).filter((item) => item.active !== false && item.kind === 'marking').length;
    const activeBodyMods = sanitizePlayCombinations(runtime.playCombinations).filter((item) => item.active !== false && item.kind === 'body_modification').length;
    const activeClampPressure = sanitizePlayCombinations(runtime.playCombinations).filter((item) => item.active !== false && item.kind === 'clamp_pressure').length;
    const categories = [
      ['tools', '道具', '器具与控制装置', `${activeTools} 项已开启`],
      ['drugs', '药物', '现实版与强化版分组', `${activeDrugs} 项已开启`],
      ['marking', '标记', '按部位、标记和载体搭配', `${activeMarkings} 套当前搭配`],
      ['body_modification', '身体改造', '穿孔位置、首饰与材质搭配', `${activeBodyMods} 套当前搭配`],
      ['clamp_pressure', '夹持与牵引', '夹具、坠子、连接配件与吸附器具', `${activeClampPressure} 套当前搭配`],
      ['restraint', '捆绑与束具', '选择绑法、绳材或成品束具，配套输入草稿', `${sanitizePlayCombinations(runtime.playCombinations).filter(item => item.kind === 'restraint' && item.active !== false).length} 套当前搭配`],
    ];
    return `<div class="ls-play-category-grid">${categories.map(([page, label, summary, status]) => `<button class="ls-play-category" type="button" data-action="play-library-page" data-play-page="${page}"><strong>${label}</strong><span>${summary}</span><small>${status}</small></button>`).join('')}</div>`;
  }

  function buildExistingPlayItem(module) {
    return `<button class="ls-play-item" type="button" data-action="toggle-play" data-module-id="${module.id}" aria-pressed="${String(runtime.activePlayIds.includes(module.id))}" title="点击开启或关闭本聊天持续玩法"><span class="ls-play-icon" aria-hidden="true">${escapeHtml(module.shortLabel)}</span><span class="ls-play-copy"><span class="ls-play-name">${escapeHtml(module.label)}</span><span class="ls-play-summary">${escapeHtml(module.summary)}</span></span></button>`;
  }

  function buildLargeEquipmentEntryCard(entry, kind, selectedId) {
    const chapter = narrativeOnlyPlayLibrary(kind)?.title || kind;
    const searchText = `${chapter} ${equipmentDisplayGroup(kind, entry)} ${entry.label} ${entry.summary}`.toLowerCase();
    const hidden = runtime.playLibrarySearch && !searchText.includes(runtime.playLibrarySearch.toLowerCase());
    return `<article class="ls-play-library-entry${hidden ? ' ls-search-hidden' : ''}" data-play-search="${escapeHtml(searchText)}"><button type="button" data-action="select-large-equipment-entry" data-equipment-kind="${kind}" data-entry-id="${entry.id}" aria-pressed="${String(selectedId === entry.id)}"><strong>${escapeHtml(entry.label)}</strong><small>${escapeHtml(entry.summary)}</small></button><details><summary>查看原文</summary><div>${escapeHtml(entry.raw)}</div></details></article>`;
  }

  function largeEquipmentDetailPlaceholder(kind, entry) {
    if (entry?.connection) return '可补颜色、材质或外观；连接关系在上方展开定制。';
    if (kind === 'large_machine') return '不填沿用原案。需要调整时，再补附件、摆放方式或初始设置。';
    if (kind === 'large_furniture') return '填写这次采用的朝向、姿势、固定点、高低或角度。';
    if (kind === 'sensory_control') return '填写作用部位、移动路径、强度、温度或与其他器具的使用次序。';
    if (kind === 'insertion_filling') return '填写这次准备的尺寸、材质、温度、档位、留置或固定方式。';
    if (kind === 'mouth_face') return '填写这次准备的尺寸、松紧、连接位置或搭配。';
    if (entry?.label === '炮机') return '填写附件、对齐部位、角度、行程和速度。';
    if (entry?.label === '程序机') return '填写附件、部位、深度、速度、停顿和节奏。';
    if (entry?.label === '双轴机') return '写清两根轴的部位、附件、速度、行程和同步方式。';
    if (entry?.label === '鞍马机') return '填写骑姿、附件、运行模式、速度和强度。';
    if (entry?.label === '工作站') return '填写固定姿势、杆头附件、对齐位置和距离。';
    return '填写这次采用的附件、部位、姿势、角度、深浅和速度。';
  }

  function buildEquipmentGuidance(kind, entry) {
    const guide = equipmentGuide(kind, entry);
    const text = guide.text ? `<details class="ls-play-plain-guide"><summary>款式与搭配说明</summary><p>${escapeHtml(guide.text)}</p></details>` : '';
    const references = guide.references.length ? `<details class="ls-play-design-reference"><summary><strong>填写参考</strong><span>点击填入，可继续修改</span></summary><div class="ls-play-reference-list">${guide.references.map((reference, index) => `<button type="button" data-action="append-equipment-reference" data-reference-index="${index}"><strong>${escapeHtml(reference.label)}</strong><span>${escapeHtml(reference.text)}</span></button>`).join('')}</div></details>` : '';
    return text + references;
  }

  function buildEquipmentConnectionEditor(draft, entry) {
    const guide = equipmentGuide(draft.kind, entry).connection;
    if (!entry.connection || !guide) return '';
    return `<div class="ls-play-draft-group"><p class="ls-play-plain-guide">${escapeHtml(guide.summary)}</p><details class="ls-equipment-connection"${draft.connection_detail ? ' open' : ''}><summary>自定义连接（选填）</summary><p class="ls-play-plain-guide">${escapeHtml(guide.hint)}</p><label class="ls-play-detail"><span>本次连接关系</span><textarea maxlength="500" data-role="equipment-connection-detail" placeholder="${escapeHtml(guide.reference)}">${escapeHtml(draft.connection_detail || '')}</textarea></label><button type="button" data-action="reset-equipment-connection">恢复默认连接</button></details></div>`;
  }

  function buildLargeEquipmentDraftEditor() {
    if (runtime.playDraft?.kind === 'restraint') return '';
    const draft = NARRATIVE_LIBRARY_PLAY_KINDS.includes(runtime.playDraft?.kind) ? runtime.playDraft : null;
    if (!draft) return '';
    const library = narrativeOnlyPlayLibrary(draft.kind);
    const entry = library.entries.find((candidate) => candidate.id === draft.entry_id) || null;
    if (!entry) return '';
    const variantOptions = entry.variants.map((variant) => ({
      action: 'select-large-equipment-variant',
      attributes: { 'data-variant-id': variant.id },
      value: variant.id,
      label: variant.label,
      selected: draft.variant_id === variant.id,
      body: variant.body,
      role: '款式',
    }));
    const variants = variantOptions.length > 0
      ? `<div class="ls-play-draft-group"><strong>款式</strong>${buildExpandablePlayChoices('large-equipment-variant', variantOptions)}</div>`
      : '';
    return `<section class="ls-play-draft"><h4>${escapeHtml(entry.label)}</h4>${variants}${buildEquipmentConnectionEditor(draft, entry)}<div class="ls-play-draft-group"><strong>本次设置（选填）</strong><label class="ls-play-detail"><textarea maxlength="500" data-role="large-equipment-detail" placeholder="${escapeHtml(largeEquipmentDetailPlaceholder(draft.kind, entry))}">${escapeHtml(draft.detail || '')}</textarea></label>${buildEquipmentGuidance(draft.kind, entry)}</div>${buildPlayDraftFooter(draft)}</section>`;
  }

  function buildLargeEquipmentSection(kind, library) {
    const selectedId = runtime.playDraft?.kind === kind ? runtime.playDraft.entry_id : '';
    const label = library.title.replace(/^器具章节[·・]?/, '').replace(/\s+v\d+$/i, '');
    const grouped = library.entries.filter((entry) => equipmentDisplayGroup(kind, entry));
    const regular = library.entries.filter((entry) => !equipmentDisplayGroup(kind, entry));
    const cards = regular.map((entry) => buildLargeEquipmentEntryCard(entry, kind, selectedId)).join('');
    const extra = grouped.length ? `<details class="ls-play-library-section ls-equipment-subgroup"${grouped.some((entry) => entry.id === selectedId) || runtime.playLibrarySearch ? ' open' : ''}><summary><strong>固定与牵引</strong><span>${grouped.length} 项</span></summary><div class="ls-play-library-list">${grouped.map((entry) => buildLargeEquipmentEntryCard(entry, kind, selectedId)).join('')}</div></details>` : '';
    const restraintLink = kind === 'large_furniture' ? '<button type="button" data-action="restraint-filter" data-furniture-only="true">选择家具固定预设</button>' : '';
    return `<details class="ls-play-library-section"${selectedId || runtime.playLibrarySearch ? ' open' : ''}><summary><strong>${escapeHtml(label)}</strong><span>${library.entries.length} 项</span></summary><div class="ls-play-library-list">${restraintLink}${cards}${extra}</div></details>`;
  }

  function buildToolsPlayPage() {
    const controls = PLAY_CONTROL_TOOL_IDS.map((id) => DYNAMIC_MODULES[id]).filter(Boolean).map(buildExistingPlayItem).join('');
    const striking = STRIKING_LIBRARY_ENTRIES.map((entry) => {
      const module = DYNAMIC_MODULES[entry.id];
      const searchText = `${entry.label} ${entry.summary}`.toLowerCase();
      const hidden = runtime.playLibrarySearch && !searchText.includes(runtime.playLibrarySearch.toLowerCase());
      return `<article class="ls-play-library-entry${hidden ? ' ls-search-hidden' : ''}" data-play-search="${escapeHtml(searchText)}">${buildExistingPlayItem(module)}<details><summary>查看原文</summary><div>${escapeHtml(entry.body)}</div></details></article>`;
    }).join('');
    return `${buildPlaySearchMarkup()}${buildLargeEquipmentDraftEditor()}<div class="ls-play-library-sections"><details class="ls-play-library-section" open><summary><strong>装置</strong><span>${PLAY_CONTROL_TOOL_IDS.length} 项</span></summary><div class="ls-play-library-list"><div class="ls-play-grid">${controls}</div></div></details><details class="ls-play-library-section"><summary><strong>打击器具</strong><span>${PLAY_STRIKING_IDS.length} 项</span></summary><div class="ls-play-library-list"><p>开启后提供对应描写；实际打击留下的身体反应合并记录。</p><div class="ls-play-library-list ls-play-striking-list">${striking}</div></div></details>${buildLargeEquipmentSection('insertion_filling', INSERTION_FILLING_LIBRARY)}${buildLargeEquipmentSection('mouth_face', MOUTH_FACE_LIBRARY)}${buildLargeEquipmentSection('sensory_control', SENSORY_CONTROL_LIBRARY)}${buildLargeEquipmentSection('large_furniture', LARGE_FURNITURE_LIBRARY)}${buildLargeEquipmentSection('large_machine', LARGE_MACHINE_LIBRARY)}</div>`;
  }

  function buildDrugsPlayPage() {
    return `<div class="ls-play-drug-groups">${PLAY_DRUG_GROUPS.map((group, index) => `<details class="ls-play-library-section"${index === 0 ? ' open' : ''}><summary><strong>${escapeHtml(group.label)}</strong><span>${group.ids.length} 项</span></summary><div class="ls-play-library-list"><div class="ls-play-grid">${group.ids.map((id) => DYNAMIC_MODULES[id]).filter(Boolean).map(buildExistingPlayItem).join('')}</div></div></details>`).join('')}</div>`;
  }

  function playApplicationCharacters() {
    return Object.entries(runtime.snapshot?.characters || {})
      .filter(([, character]) => character?.mode === 'detailed')
      .map(([name]) => name);
  }

  function buildPlayCharacterChoices(draft) {
    const names = playApplicationCharacters();
    if (names.length === 0) return `<div class="ls-play-empty">${runtime.playLibraryEnabled ? '当前没有可应用的详细记录角色。角色进入当前情景并建档后即可选择。' : '请先开启玩法库；角色进入当前情景并建档后即可选择。'}</div>`;
    return `<div class="ls-play-choice-row">${names.map((name) => `<button type="button" data-action="select-play-character" data-character-name="${escapeHtml(name)}" aria-pressed="${String(draft?.character === name)}">${escapeHtml(name)}</button>`).join('')}</div>`;
  }

  function buildPlayLibraryEntryCard(entry, section, action, selectedId) {
    const searchText = `${section.label} ${entry.label} ${entry.summary}`.toLowerCase();
    const hidden = runtime.playLibrarySearch && !searchText.includes(runtime.playLibrarySearch.toLowerCase());
    const guide = playCombinationGuide(action === 'select-bodymod-entry' ? 'body_modification' : 'marking', entry.label);
    return `<article class="ls-play-library-entry${hidden ? ' ls-search-hidden' : ''}" data-play-search="${escapeHtml(searchText)}"><button type="button" data-action="${action}" data-entry-id="${entry.id}" aria-pressed="${String(selectedId === entry.id)}"><strong>${escapeHtml(entry.label)}</strong><small>${escapeHtml(guide || entry.summary)}</small></button><details><summary>查看原文</summary><div>${escapeHtml(action === 'select-bodymod-entry' ? bodyModificationSelectedText(entry, bodyModificationInitialJewelry(entry)) : entry.body)}</div></details></article>`;
  }

  function buildPlaySearchMarkup() {
    return `<label class="ls-play-search"><span>搜索条目</span><input type="search" data-role="play-library-search" value="${escapeHtml(runtime.playLibrarySearch)}" placeholder="输入部位或条目名称"></label>`;
  }

  function buildPlayDraftFooter(draft) {
    const withInput = ['marking', 'body_modification'].includes(draft?.kind);
    return `<section class="ls-play-draft-footer"><h4>应用角色</h4>${buildPlayCharacterChoices(draft)}${withInput ? `<small>应用后填入聊天输入框，不自动发送，也不提前建立完成状态。</small><details class="ls-play-plain-guide"><summary>输入草稿预览</summary><p data-role="play-input-preview">${escapeHtml(playInputDraft(draft) || '选择人物并补全设置后生成。')}</p></details>` : ''}<div class="ls-play-draft-actions"><button type="button" data-action="cancel-play-draft">取消</button><button type="button" data-action="apply-play-combination"${draft?.character ? '' : ' disabled'}>${withInput ? '应用并填入草稿' : '应用搭配'}</button></div></section>`;
  }

  function bodyModificationDetailPlaceholder(kind, label = '') {
    if (kind === 'base') return '例如：双侧各一处；仅右侧；左侧两枚。填写左右、数量和具体位置。';
    if (kind === 'jewelry') return '例如：两侧同款，1.6mm 黑钛；左侧金色、右侧钢色。';
    if (label.includes('链条')) return '例如：左乳环连接右乳环；鼻中隔环连接左耳环。写清连接两端。';
    if (label.includes('挂重')) return '例如：双侧各 20g；仅右侧增加 10g。';
    if (label.includes('坠饰')) return '例如：左侧铃铛，右侧细坠；两侧各一枚。';
    if (label.includes('扩径')) return '例如：舌钉从 1.6mm 扩至 2.0mm；本次增加 0.4mm。';
    if (label.includes('挂锁')) return '例如：连接双侧乳环；小锁位于两环之间。';
    return '填写本次实际采用的尺寸、数量、位置或搭配。';
  }

  function buildBodyModificationDetailField(kind, label, value = '', itemId = '') {
