        ? `<button class="ls-play-choice-info" type="button" data-action="toggle-play-option-info" data-info-key="${key}" aria-expanded="${String(runtime.playOptionInfoKey === key)}" title="展开原词条">⌄</button>`
        : '';
      return `<span class="ls-play-choice-unit" data-selected="${String(choice.selected)}"><button type="button" data-action="${choice.action}"${attributes} aria-pressed="${String(choice.selected)}"${choice.disabled ? ` disabled title="${escapeHtml(choice.disabledReason || '当前搭配不适用')}"` : ''}>${escapeHtml(choice.label)}</button>${info}</span>`;
    }).join('');
    const opened = normalized.find((choice) => (
      choice.selected && (choice.body || choice.guide) && playOptionInfoKey(group, choice.value || '', choice.label) === runtime.playOptionInfoKey
