    const details = opened
      ? `<div class="ls-play-option-explanation"><strong>${escapeHtml(opened.label)}</strong>${opened.guide ? `<p class="ls-play-plain-guide">${escapeHtml(opened.guide)}</p>` : ''}${opened.role ? `<p>${escapeHtml(opened.role)}</p>` : ''}<div>${escapeHtml(opened.body || '')}</div></div>`
