      api_key: editor.querySelector('.ls-external-key')?.value || '',
      timeout_ms: editor.querySelector('.ls-external-timeout') ? Number(editor.querySelector('.ls-external-timeout').value) * 1000 : runtime.externalApiConfig?.timeout_ms,
      timeout_user_set: runtime.externalApiConfig?.timeout_user_set === true,
      content_filter_mode: editor.querySelector('.ls-external-filter-mode')?.value || 'none',
      content_filter_tags: editor.querySelector('.ls-external-filter-tags')?.value || '',
      strip_html_comments: editor.querySelector('.ls-external-strip-html-comments')?.checked !== false,
    };
  }

  function externalModelSource(config) {
    const normalized = EXTERNAL_WORKFLOW.normalizeConfig(config);
    return sha256Hex(JSON.stringify([normalized.endpoint, normalized.api_key, normalized.api_format]));
  }

  function resetExternalModelCatalog() {
    runtime.externalModelCatalog.controller?.abort();
    runtime.externalModelCatalog = { source: '', models: [], busy: false, error: '', controller: null };
  }

  function updateExternalModelCatalog(editor) {
    const source = externalModelSource(readExternalConfigForm(editor));
    if (runtime.externalModelCatalog.source && runtime.externalModelCatalog.source !== source) resetExternalModelCatalog();
    const catalog = runtime.externalModelCatalog;
    const custom = readExternalConfigForm(editor).api_format === 'custom';
    const button = editor.querySelector('[data-action="external-models"]');
    const select = editor.querySelector('.ls-external-model-list');
    const feedback = editor.querySelector('.ls-external-model-feedback');
    if (!button || !select || !feedback) return;
    button.disabled = catalog.busy || custom;
    button.textContent = catalog.busy ? '正在拉取…' : '拉取模型';
    const options = '<option value="">选择一个模型</option>' + catalog.models.map(model => `<option value="${escapeHtml(model)}">${escapeHtml(model)}</option>`).join('');
    if (select.innerHTML !== options) select.innerHTML = options;
    select.hidden = custom || !catalog.models.length;
    select.disabled = catalog.busy;
    feedback.textContent = custom ? '自定义地址不推测列表路径，请手动填写模型名。' : catalog.error || (catalog.busy ? '正在读取当前填写的接口，不会保存设置…'
      : catalog.models.length ? `已拉取 ${catalog.models.length} 个模型，选择后请保存。` : '可手动填写，也可拉取后选择；不会自动保存设置。');
    feedback.dataset.level = catalog.error ? 'error' : 'normal';
  }

  async function fetchExternalModelCatalog(editor) {
    if (runtime.externalModelCatalog.busy) return;
    const config = readExternalConfigForm(editor);
    resetExternalModelCatalog();
    const catalog = runtime.externalModelCatalog;
    catalog.source = externalModelSource(config);
    catalog.busy = true; catalog.controller = new AbortController();
    updateExternalModelCatalog(editor);
    try {
      const models = await EXTERNAL_WORKFLOW.fetchModels(config, { signal: catalog.controller.signal });
      if (runtime.externalModelCatalog === catalog) catalog.models = models;
    } catch (error) {
      if (runtime.externalModelCatalog === catalog) catalog.error = error.message || String(error);
    } finally {
      if (runtime.externalModelCatalog === catalog) {
        catalog.busy = false; catalog.controller = null;
        const current = (runtime.hostDocument || getHostDocument())?.querySelector('.ls-external-settings');
        if (current) updateExternalModelCatalog(current);
      }
    }
  }

  function updateExternalConfigFeedback(editor) {
    const feedback = editor.querySelector('.ls-external-config-feedback');
    if (!feedback) return;
    const normalize = EXTERNAL_WORKFLOW?.normalizeConfig;
    const dirty = normalize && JSON.stringify(normalize(readExternalConfigForm(editor))) !== JSON.stringify(normalize(runtime.externalApiConfig || loadExternalApiConfig()));
    const status = runtime.externalConfigStatus;
    const labels = { idle: '当前设置尚未测试', saved: '已保存，尚未测试', testing: '已保存，正在测试连接…',
      passed: '已保存，连接测试通过', failed: '已保存，连接测试失败', save_failed: '保存失败，填写内容已保留' };
    feedback.textContent = status === 'save_failed' ? labels.save_failed : dirty
      ? `有未保存的修改${status === 'testing' ? '；正在测试上次保存的设置' : status === 'failed' ? '；上次连接测试失败' : ''}`
      : labels[status] || labels.idle;
    if (runtime.externalConfigError && ['failed', 'save_failed'].includes(status)) feedback.textContent += `：${runtime.externalConfigError}`;
    feedback.dataset.level = ['failed', 'save_failed'].includes(status) ? 'error' : dirty || status === 'testing' ? 'waiting' : 'normal';
    editor.querySelectorAll('[data-action="external-save"], [data-action="external-test"]').forEach(button => {
      button.disabled = status === 'testing' || Boolean(runtime.externalConnectionTestPromise);
      if (button.dataset.action === 'external-test') button.textContent = status === 'testing' ? '正在测试…' : '保存并测试';
    });
    updateExternalModelCatalog(editor);
  }

