    </section>`;
  }


  function stateUpdateIssue(messageId, code) {
    const reasons = { missing_block: '未找到完整状态块', parse_failed: 'JSON 格式错误', schema_failed: '状态字段不符合要求', message_read_failed: '读取未成功',
      snapshot_save_failed: '保存未成功', snapshot_load_failed: '读取未成功',
      branch_scan_failed: '读取未成功', branch_rebuild_failed: '历史状态恢复未完成',
      unexpected_processing_error: '处理未完成' };
    return { messageId: Number.isInteger(messageId) ? messageId : null, code, reason: reasons[code] || '状态格式未通过' };
  }

  function showStateUpdateFailure(messageId, code, adapter, identity) {
    if (identity && operationChatIdentity(adapter) !== identity) return;
    if (messageId === 0 && code === 'missing_block') return;
    runtime.stateUpdateFeedback = { ...runtime.stateUpdateFeedback, issue: stateUpdateIssue(messageId, code) };
    refreshStatePanel();
  }

  function branchStateUpdateIssue(message, result, messages) {

    if (!message || result?.ok || runtime.workflowMode === WORKFLOW_MODES.EXTERNAL
      || /<state_handoff\b/i.test(message.message)
      || !messages.some(item => item.role === 'user' && Number(item.message_id) < Number(message.message_id))) return null;
    return stateUpdateIssue(Number(message.message_id), result?.code || 'missing_block');
  }

  function buildStateUpdateMarkup() {
    const { sourceMessageId, issue } = runtime.stateUpdateFeedback;
    const hasSource = runtime.hasSnapshot && Number.isInteger(sourceMessageId) && sourceMessageId >= 0;
    const recent = hasSource ? `最近更新：第 ${sourceMessageId} 楼` : (runtime.hasSnapshot ? '已有记录，等待正文更新' : '尚未收到状态');
    let level = hasSource ? 'ready' : 'idle', label = recent, detail = '';
    const external = runtime.workflowMode === WORKFLOW_MODES.EXTERNAL;
    const pending = external ? sanitizeExternalPendingQueue(runtime.externalPendingQueue) : [];
    const repair = runtime.formatRepair;
    if (!external && repair.controller) {
      level = 'waiting'; label = repair.status === 'saving' ? `正在保存第 ${repair.messageId} 楼修复结果` : `正在修复第 ${repair.messageId} 楼格式`; detail = recent;
    } else if (external && runtime.externalStatus === 'translating') {
      level = 'waiting'; label = '正在更新状态'; detail = recent;
      const job = runtime.externalBackgroundJob;
      if (job?.activeMessages.length) detail += `；后台分析第 ${job.activeMessages[0]}～${job.activeMessages.at(-1)} 楼，另待更新 ${Math.max(0, pending.length - job.activeMessages.length)} 轮`;
    } else if (pending.length) {
      const failed = runtime.externalStatus === 'error' || pending.some(item => item.last_error);
      level = failed ? 'error' : 'waiting';
      label = failed ? `外接更新未完成 · ${pending.length} 楼待更新`
        : (runtime.externalUpdateEvery === 3 && pending.length < 3 ? `等待更新 · 已积攒 ${pending.length}/3 楼` : `等待更新 · ${pending.length} 楼待更新`);
      detail = `${runtime.hasSnapshot ? '沿用已有记录；' : ''}${recent}`;
    } else if (issue) {
      level = 'error';
      label = `${Number.isInteger(issue.messageId) ? `第 ${issue.messageId} 楼未更新` : '状态未更新'} · ${issue.reason}`;
      detail = `${runtime.hasSnapshot ? '沿用已有记录；' : ''}${recent}`;
    }
    const inspectId = !external && repair.controller ? repair.messageId : issue?.messageId ?? (hasSource ? sourceMessageId : null);
    if (!external && issue?.code === 'missing_block') detail += '；下一轮将加强状态输出提醒';
    if (!external && issue && repair.messageId === inspectId && repair.status === 'error') detail += `；格式修复未完成：${repair.error}`;
    if (!external && issue && repair.messageId === inspectId && repair.status === 'cancelled') detail += '；格式修复已取消，沿用已有记录';
    if (!external && !issue && repair.status === 'success' && repair.messageId === sourceMessageId) detail = '已采用格式修复结果，聊天原文保留';
    const inspect = !external && Number.isInteger(inspectId) && inspectId >= 0
      ? `<button class="ls-format-button" type="button" data-action="state-return" data-message-id="${inspectId}">查看返回</button>` : '';
    const fix = !external && repair.controller ? `<button class="ls-format-button" data-action="format-repair-cancel" ${repair.status === 'saving' ? 'disabled' : ''} title="${repair.source === 'tavern' ? '停止等待并丢弃迟到结果；酒馆请求可能仍在完成' : '取消本次修复请求'}">${repair.status === 'saving' ? '正在保存' : '取消修复'}</button>`
      : !external && ['parse_failed','schema_failed'].includes(issue?.code) ? runtime.formatRepairSource === 'off'
        ? '<button class="ls-format-button" data-action="format-repair-settings">设置格式修复</button>'
        : `<button class="ls-format-button" data-action="inline-format-repair" data-message-id="${inspectId}">修复本轮状态</button>` : '';
    const externalAction = (action, text, disabled = false) => `<button class="ls-format-button" type="button" data-action="state-external-action" data-external-action="${action}" ${disabled ? 'disabled' : ''}>${text}</button>`;
    const externalActions = external ? `${pending.length ? externalAction(runtime.externalStatus === 'error' ? 'external-retry' : 'external-update-now', runtime.externalStatus === 'error' ? '重试更新' : '立即更新', Boolean(runtime.externalFlushPromise && (!runtime.externalBackgroundJob || runtime.externalBackgroundJob.rangeStart != null))) : ''}${runtime.externalLastResponse ? externalAction('external-response','查看返回') : ''}${externalAction('external-stop-inline','停止外接并切回内置', runtime.generationActive || runtime.externalControl.stopping)}` : '';
    return `${buildStoryTimeMarkup()}<div class="ls-state-update" data-level="${level}" role="status"><span>${escapeHtml(label)}</span>${detail ? `<span class="ls-state-update-detail">${escapeHtml(detail)}</span>` : ''}${inspect}${fix}${externalActions}</div>`;
  }

  function inspectLifeStateReturn(message, modules, previousSnapshot = null) {
    const source = String(message?.message || '');
    const blocks = [...source.matchAll(new RegExp(LIFE_STATE_RE.source, LIFE_STATE_RE.flags))];
    const parts = blocks.map(block => block[0]);
    const last = blocks.at(-1);
    const tail = source.slice(last ? last.index + last[0].length : 0);
    const dangling = tail.search(/<life_state\b/i);
    if (dangling >= 0) parts.push(tail.slice(dangling));
    if (!parts.length) {
      const closing = source.match(/<\/life_state\s*>/i);
      if (closing) parts.push(closing[0]);
    }
    const result = processLifeStateText(source, modules, previousSnapshot);
    let reason = result.ok ? '格式检查通过' : stateUpdateIssue(null, result.code).reason;
    let errors = Array.isArray(result.errors) ? result.errors.slice() : result.error ? [result.error] : [];
    let location = '';
    if (result.code === 'missing_block') {
      reason = dangling >= 0 ? '状态标签未闭合' : parts.length ? '缺少状态开始标签' : '未找到状态块';
      errors = [dangling >= 0 ? '找到了 <life_state> 开头，但没有可识别的 </life_state> 结尾。'
        : parts.length ? '只找到了 </life_state>，没有对应的开始标签。' : '这条回复中没有可识别的 <life_state>…</life_state>，无法更新状态。'];
    } else if (result.code === 'parse_failed' && last) {

      if (sanitizeLifeStateText(last[1]) === stripBoundaryCodeFence(last[1]) && !last[1].includes('```')) {
        try { JSON.parse(last[1]); } catch (error) {
          const match = /position\s+(\d+)/i.exec(error.message);
          if (match) {
            const offset = last[0].indexOf('>') + 1 + Number(match[1]);
            const lines = last[0].slice(0, offset).split('\n');
            location = `最后一个完整状态块内第 ${lines.length} 行，第 ${lines.at(-1).length + 1} 列。`;
          }
        }
      }
      if (!location) location = '无法可靠定位原文行号；下方保留解析器错误信息，其中的位置可能基于兼容处理后的文本。';
    }
    const warnings = [...(result.warnings || [])];
    if (blocks.length > 1) warnings.unshift(`共有 ${blocks.length} 个完整状态块，脚本按最后一个处理；下方保留全部原文。`);
    if (result.ok && dangling >= 0) warnings.unshift('最后一个完整状态块之后还有未闭合的状态开头，未作为有效状态读取。');
    return { messageId: Number(message?.message_id), swipeId: message?.swipe_id ?? null, ok: result.ok, code: result.code || 'ok',
      reason, errors, warnings, location, raw: parts.join('\n\n'), checkedAt: new Date().toISOString() };
  }

  function stateReturnReportText(view = runtime.stateReturnView) {
    if (!view) return '';
    return [`第 ${view.messageId} 楼 · ${view.reason || '读取中'}`, '按当前观察设置检查，仅供排查；查看不会保存或修复状态。',
      view.location || '', view.repairError || '', ...(view.errors || []), ...(view.warnings || []), '── 实际状态块原文 ──', view.raw || '没有可展示的状态块。',
      ...(view.repairedRaw ? ['── 已采用的格式修复结果（聊天原文未改） ──', view.repairedRaw] : [])].filter(Boolean).join('\n\n');
  }

  async function openStateReturn(messageId, adapter = runtime.adapter) {
    const id = Number(messageId);
    if (!Number.isInteger(id) || id < 0 || !adapter?.readMessage) return;
    const identity = operationChatIdentity(adapter);
    const view = { messageId: id, reason: '正在读取状态返回', errors: [], warnings: [], raw: '', loading: true };
    runtime.scanReturnView = null;
    runtime.stateReturnView = view; runtime.externalResponseOpen = true;
    renderExternalResponsePanel();
    try {
      const message = await adapter.readMessage(id);
      const store = await adapter.getStore() || {};
      const messages = adapter.listMessages ? await adapter.listMessages() : [];
      assertOperationChatUnchanged(adapter, identity);
      if (runtime.stateReturnView !== view) return;
      if (!message || message.role !== 'assistant') throw new Error('该楼已删除或不是模型回复，请重新选择。');
      const modules = modulesWithPlayRequirements(modulesFromStore(store, adapter.getStoreSource?.() || 'vnext'), normalizeActivePlayIds(store.active_play_routes));
      Object.assign(view, inspectLifeStateReturn({ ...message, message_id: id }, modules, store.snapshot));
      const repaired = inlineFormatRepairForMessage({ ...message, message_id: id }, store, messages);
      view.repairedRaw = repaired?.raw_state_block || '';
      view.repairAvailable = !repaired && normalizeWorkflowMode(store.state_workflow_mode) === WORKFLOW_MODES.INLINE
        && normalizeFormatRepairSource(store.format_repair_source) !== 'off' && inlineRepairEligible(message.message, view)
        && Number(messages.filter(item => item.role === 'assistant').at(-1)?.message_id) === id;
      const repairIdentity = runtime.formatRepair.identity;
      view.repairError = repairIdentity && externalMessageMatches({ ...message, message_id: id }, repairIdentity)
        && repairIdentity.branch_sha256 === formatRepairBranchHash(messages, id) ? runtime.formatRepair.error : '';
      if (repaired) { view.warnings.unshift('原文仍有以下格式问题；脚本已采用下方修复结果，不需要重复修复。'); view.reason = '已采用修复结果，原文保留'; }
    } catch (error) {
      if (runtime.stateReturnView !== view) return;
      if (operationChatIdentity(adapter) !== identity) { runtime.stateReturnView = null; runtime.externalResponseOpen = false; renderExternalResponsePanel(); }
      else Object.assign(view, { reason: '读取未成功', errors: [error.message], ok: false });
    }
    if (runtime.stateReturnView !== view) return;
    view.loading = false;
    renderExternalResponsePanel();
    (runtime.hostDocument || getHostDocument())?.getElementById(CONFIG.externalResponsePanelId)?.querySelector('[data-action="external-response-close"]')?.focus?.();
  }

  function buildStateReturnMarkup(view = runtime.stateReturnView) {
    if (!view) return '';
    const errors = [view.location, ...(view.errors || [])].filter(Boolean);
    const warnings = view.warnings || [];
    return `<button class="ls-external-response-backdrop" type="button" data-action="external-response-dismiss" aria-label="关闭状态返回"></button><section class="ls-external-response-dialog" role="dialog" aria-modal="true" aria-labelledby="life-state-external-response-title"><header class="ls-external-response-head"><div><h2 id="life-state-external-response-title">第 ${view.messageId} 楼 · 状态返回</h2><div class="ls-external-response-meta"><span>${escapeHtml(view.reason)}</span></div></div><div><button type="button" data-action="external-response-copy" ${view.loading ? 'disabled' : ''}>复制状态与报错</button>${view.repairAvailable ? `<button data-action="inline-format-repair" data-message-id="${view.messageId}" ${runtime.formatRepair.controller ? 'disabled' : ''}>修复本轮状态</button>` : ''}<button type="button" data-action="external-response-close">关闭</button></div></header><div class="ls-external-response-body" style="grid-template-columns:minmax(0,1fr)"><section><h3>${view.repairedRaw ? '原文检查（已采用修复结果）' : '检查结果'}</h3><p class="ls-external-response-empty">${view.repairedRaw ? '脚本已采用修复结果。以下保留原始返回的问题，供对照查看。' : '按当前观察设置检查，仅供排查；查看不会保存或修复状态。'}</p>${view.repairError ? `<div class="ls-external-response-error">${escapeHtml(view.repairError)}</div>` : ''}${errors.length ? `<div class="ls-external-response-error">${errors.map(text => `<div>${escapeHtml(text)}</div>`).join('')}</div>` : ''}${warnings.length ? `<details class="ls-external-response-empty"><summary>兼容处理与提示（${warnings.length}）</summary>${warnings.map(text => `<p>${escapeHtml(text)}</p>`).join('')}</details>` : ''}</section><section><h3>实际状态块原文（未改写）</h3>${view.raw ? `<pre style="font-size:13px;line-height:1.6">${escapeHtml(view.raw)}</pre>` : `<div class="ls-external-response-empty">${view.loading ? '正在读取…' : '没有可展示的状态块。'}</div>`}</section>${view.repairedRaw ? `<section><h3>已采用的修复结果（聊天原文未改）</h3><pre style="font-size:13px;line-height:1.6">${escapeHtml(view.repairedRaw)}</pre></section>` : ''}</div></section>`;
  }

  function buildStatePanelMarkup(snapshot, preferredCharacter = null, modern = false) {
    const update = buildStateUpdateMarkup();
    if (snapshot === null || !isPlainObject(snapshot?.characters)) {
      return `${update}<div class="ls-empty-copy">当前无重要角色追踪</div>`;
    }
    const entries = Object.entries(snapshot.characters);
    if (entries.length === 0) return `${update}<div class="ls-empty-copy">当前无重要角色追踪</div>`;
    const detailed = entries.filter(([, value]) => value.mode === 'detailed');
    const retained = entries.filter(([, value]) => value.mode === 'retained');
    const activeEntry = entries.find(([name]) => name === preferredCharacter) || entries[0];
    const tabs = entries.map(([name, character], index) => buildCharacterTab(name, character, index, activeEntry[0])).join('');
    return `${update}<div class="ls-overview"><div class="ls-title">身体状态</div><div class="ls-mode-counts"><span class="ls-mode-count">同行详细关注 ${detailed.length}</span>${retained.length ? `<span class="ls-mode-count ls-mode-count-retained">最小因果保留 ${retained.length}</span>` : ''}</div></div>${buildNeedAnchorUpdatesMarkup()}${modern ? '<div class="ls-modern-character-layout">' : ''}<div class="ls-character-tabs" role="tablist" aria-label="切换角色">${tabs}</div>${buildCharacterMarkup(activeEntry[0], activeEntry[1], modern)}${modern ? '</div>' : ''}`;
  }

  function inlineNeedDuration(needKey, need) {
    const field = needKey === 'sleep' && Object.prototype.hasOwnProperty.call(need, 'awake_for') ? 'awake_for' : 'elapsed';
    if (!Object.prototype.hasOwnProperty.call(need, field) || !Number.isFinite(Number(need[field]))) return '';
    return formatDuration(need[field]).replace(/\s+/g, '');
  }

  function buildInlineNeedChip(characterName, needKey, need) {
    const stage = NEED_STAGES.has(need?.stage) ? need.stage : '';
    const stageClass = stage ? ` ls-inline-stage-${NEED_STAGE_ROUTE_IDS[stage]}` : '';
    const stageLabel = stage ? stage.replace(/期$/, '') : '未定';
    const duration = inlineNeedDuration(needKey, need) || (!(needKey === 'sleep' && need?.sleeping === true)
      ? formatDuration(initialNeedOffsetForDisplay(characterName, needKey, need)).replace(/\s+/g, '') : '');
    return `<span class="ls-inline-chip${stageClass}"><span>${escapeHtml(NEED_LABELS[needKey] || needKey)}</span><b>${escapeHtml(stageLabel)}</b>${duration ? `<small>${escapeHtml(duration)}</small>` : ''}</span>`;
  }

  function buildInlineReproductiveChips(reproductive, characterName = '') {
    if (!isPlainObject(reproductive)) return [];
    const chips = [];
    const cycle = reproductive.menstrual_cycle;
    if (isPlainObject(cycle)) {
      const value = Number.isFinite(Number(cycle.cycle_day)) ? `第${Math.round(Number(cycle.cycle_day))}天` : displayReproductiveValue('cyclePhase', cycle.phase || '周期未知');
      chips.push(`<span class="ls-inline-chip"><span>周期</span><b>${escapeHtml(value)}</b></span>`);
    }
    const conception = reproductive.conception;
    if (isPlainObject(conception)) {
      const value = displayReproductiveValue('conceptionOutcome', conception.outcome || '待判定');
      chips.push(`<div class="ls-inline-pregnancy"><span class="ls-inline-chip"><span>受孕风险</span><b>${escapeHtml(value)}</b></span>${buildPregnancyAwarenessMarkup(characterName, conception, 'conception')}</div>`);
    }
    const pregnancy = reproductive.pregnancy;
    if (isPlainObject(pregnancy)) {
      const value = Number.isFinite(Number(pregnancy.gestation_days))
        ? formatGestationDays(pregnancy.gestation_days)
        : (pregnancy.phase ? displayReproductiveValue('pregnancyPhase', pregnancy.phase) : displayReproductiveValue('pregnancyConfirmation', pregnancy.confirmation || '待确认'));
      chips.push(`<div class="ls-inline-pregnancy"><span class="ls-inline-chip"><span>孕期</span><b>${escapeHtml(value)}</b></span>${buildPregnancyAwarenessMarkup(characterName, pregnancy)}</div>`);
    }
    return chips;
  }

  function buildInlineEffectsMarkup(effects) {
    const entries = Object.entries(isPlainObject(effects) ? effects : {}).filter(([, effect]) => isPlainObject(effect));
    if (entries.length === 0) return '';
    const rows = entries.map(([key, effect]) => {
      const notes = String(effect.notes || '').trim();
      return `<div class="ls-inline-effect"><strong>${escapeHtml(effectLabel(key, effect))}${key === CYCLE_PRESENCE_KEY ? ' · 内置' : ''}</strong><span>${escapeHtml(notes || '影响持续中')}</span></div>`;
    }).join('');
    return `<div class="ls-inline-effects">${rows}</div>`;
  }

  function buildInlineCharacterMarkup(name, character) {
    const retained = character?.mode === 'retained';
    const chips = NEED_KEYS
      .map((needKey) => [needKey, character?.needs?.[needKey]])
      .filter(([, need]) => isPlainObject(need))
      .map(([needKey, need]) => buildInlineNeedChip(name, needKey, need));
    chips.push(...buildInlineReproductiveChips(character?.reproductive, name));
    const effectCount = Object.values(character?.effects || {}).filter(isPlainObject).length;
    if (effectCount > 0) chips.push(`<span class="ls-inline-chip"><span>持续影响</span><b>${effectCount}</b></span>`);
    const desireProfile = runtime.sexualDesireProfiles?.[name];
    if (!retained && effectiveRuntimeModules().sexual_desire && desireProfile) {
      chips.push(`<span class="ls-inline-chip"><span>性欲</span><b>${escapeHtml(desireProfile.stage)}</b></span>`);
    }
    if (effectiveRuntimeModules().stamina && runtime.staminaProfiles?.[name]) { const stamina = runtime.staminaProfiles[name]; chips.push(`<span class="ls-inline-chip" title="${escapeHtml(stamina.reason || '')}"><span>体力</span><b>${Math.round(stamina.score)} · ${stamina.issue ? '未结算' : escapeHtml(staminaStage(stamina.score))}</b></span>`); }
    if (chips.length === 0) chips.push('<span class="ls-inline-chip"><span>暂无可显示项目</span></span>');
    const modern = runtime.uiStyle === UI_STYLES.MODERN;
    const detailsOpen = runtime.inlineDetails.has(name);
    const detailsButton = modern ? `<button class="ls-modern-detail-toggle" type="button" data-action="inline-details" data-character-name="${escapeHtml(name)}" aria-expanded="${String(detailsOpen)}">详情 ${detailsOpen ? '⌃' : '⌄'}</button>` : '';
    return `<article class="ls-inline-character${retained ? ' ls-inline-retained' : ''}"><div class="ls-inline-character-head"><span class="ls-inline-name">${escapeHtml(name)}</span><span class="ls-inline-mode">${retained ? '简要记录' : '详细记录'}</span>${detailsButton}</div><div class="ls-inline-chips">${chips.join('')}</div>${buildInlineEffectsMarkup(character?.effects)}${modern && detailsOpen ? buildModernInlineDetails(name, character) : ''}</article>`;
  }

  function buildInlineStateMarkup(snapshot, expanded = runtime.inlineExpanded) {
    const entries = isPlainObject(snapshot?.characters) ? Object.entries(snapshot.characters) : [];
    const playLabels = activePlayCategoryLabels();
    const countLabel = `${entries.length > 0 ? `${entries.length} 人` : '暂无角色'}${playLabels.length > 0 ? `｜玩法：${playLabels.join('、')}` : ''}`;
    const playStatus = playLabels.length > 0
      ? `<div class="ls-inline-play-status"><span>当前玩法：<strong>${escapeHtml(playLabels.join('、'))}</strong></span><button type="button" data-action="clear-play-injection">清空玩法注入</button><small>已建立状态保留</small></div>`
      : '';
    const characters = entries.length > 0
      ? `<div class="ls-inline-characters">${entries.map(([name, character]) => buildInlineCharacterMarkup(name, character)).join('')}</div>`
      : '<div class="ls-inline-empty-copy">当前无重要角色追踪</div>';
    return `<div class="ls-inline-shell"><header class="ls-inline-head"><button class="ls-inline-toggle" type="button" data-action="inline-toggle" aria-expanded="${String(expanded)}"><span class="ls-inline-dot" aria-hidden="true"></span><span class="ls-inline-title">身体状态</span><span class="ls-inline-count">${escapeHtml(countLabel)}</span><span class="ls-inline-chevron" aria-hidden="true">⌄</span></button><button class="ls-inline-settings" type="button" data-action="inline-settings" title="打开完整面板" aria-label="打开完整面板">⚙</button></header>${buildStateUpdateMarkup()}<div class="ls-inline-body" aria-hidden="${String(!expanded)}">${playStatus}${characters}</div></div>`;
  }

  function findLatestAssistantMessageElement(document = runtime.hostDocument || getHostDocument()) {
    const chat = document?.querySelector?.('#chat');
    if (!chat) return null;
    const messages = Array.from(chat.querySelectorAll('.mes')).filter((element) => (
      element.getAttribute('is_user') === 'false' && element.getAttribute('is_system') !== 'true'
    ));
    return messages.at(-1) || null;
  }

  function removeInlineStatePanel(document = runtime.hostDocument || getHostDocument()) {
    document?.getElementById(CONFIG.inlinePanelId)?.remove();
    runtime.inlineRenderSignature = '';
  }

  function disconnectInlineObserver() {
    runtime.inlineObserver?.disconnect?.();
    runtime.inlineObserver = null;
    runtime.inlineObservedChat = null;
  }

  function scheduleInlineStatePanelRender(document = runtime.hostDocument || getHostDocument(), snapshot = runtime.snapshot) {
    const clearTimer = document?.defaultView?.clearTimeout || root.clearTimeout || clearTimeout;
    const setTimer = document?.defaultView?.setTimeout || root.setTimeout || setTimeout;
    if (runtime.inlineRenderTimer !== null) clearTimer(runtime.inlineRenderTimer);
    runtime.inlineRenderTimer = setTimer(() => {
      runtime.inlineRenderTimer = null;
      renderInlineStatePanel(snapshot, document);
    }, 40);
  }

  function ensureInlineObserver(document = runtime.hostDocument || getHostDocument()) {
    const chat = document?.querySelector?.('#chat');
    if (!chat || runtime.inlineObservedChat === chat) return;
    disconnectInlineObserver();
    const Observer = document?.defaultView?.MutationObserver || root.MutationObserver;
    if (typeof Observer !== 'function') return;
    runtime.inlineObservedChat = chat;
    runtime.inlineObserver = new Observer((mutations) => {
      const messageListChanged = mutations.some((mutation) => {
        if (mutation.target === chat) return true;
        const nodes = [...mutation.addedNodes, ...mutation.removedNodes];
        return nodes.some((node) => node?.nodeType === 1 && (node.matches?.('.mes') || node.querySelector?.('.mes')));
      });
      if (messageListChanged) scheduleInlineStatePanelRender(document);
    });
    runtime.inlineObserver.observe(chat, { childList: true, subtree: true });
  }

  function ensureInlineStatePanel(document = runtime.hostDocument || getHostDocument()) {
    if (!document?.body) return null;
    let panel = document.getElementById(CONFIG.inlinePanelId);
    if (panel) return panel;
    panel = document.createElement('section');
    panel.id = CONFIG.inlinePanelId;
    panel.setAttribute('aria-label', '正文下角色生理状态');
    bindConceptionResultDetails(panel);
    panel.addEventListener('click', (event) => {
      const button = event.target.closest?.('[data-action]');
      if (!button) return;
      if (button.dataset.action === 'pregnancy-awareness') {
        queuePregnancyAwarenessChange(button, event);
      } else if (button.dataset.action === 'conception-result') {
        queueConceptionResultChange(button,event);
      } else if (handleModernUiAction(button, event, panel.ownerDocument)) {
        return;
      } else if (handleFormatRepairAction(button, event, panel.ownerDocument)) {
        return;
      } else if (button.dataset.action === 'inline-toggle') {
        runtime.inlineExpanded = !runtime.inlineExpanded;
        renderInlineStatePanel(runtime.snapshot, panel.ownerDocument);
      } else if (button.dataset.action === 'state-return') {
        openStateReturn(button.dataset.messageId).catch(error => logStateError('state_return_view_failed', error));
      } else if (button.dataset.action === 'inline-settings') {
        openSettingsPage('home', panel.ownerDocument);
      } else if (button.dataset.action === 'clear-play-injection') {
        runtime.queue = runtime.queue
          .then(() => clearPlayInjection(runtime.adapter))
          .catch((error) => logStateError('play_injection_clear_failed', error, 'error'));
      }
    });
    return panel;
  }

  function renderInlineStatePanel(snapshot, document = runtime.hostDocument || getHostDocument()) {
    if (runtime.displayMode !== DISPLAY_MODES.INLINE) {
      removeInlineStatePanel(document);
      disconnectInlineObserver();
      return null;
    }
    ensureInlineObserver(document);
    const message = findLatestAssistantMessageElement(document);
    const target = message?.querySelector?.('.mes_block');
    if (!target) {
      removeInlineStatePanel(document);
      return null;
    }
    const panel = ensureInlineStatePanel(document);
    if (!panel) return null;
    panel.classList.toggle('ls-modern', runtime.uiStyle === UI_STYLES.MODERN);
    panel.dataset.uiTheme = normalizeUiTheme(runtime.uiTheme);
    if (panel.parentElement !== target) target.appendChild(panel);
    const entries = isPlainObject(snapshot?.characters) ? Object.keys(snapshot.characters) : [];
    const markup = buildInlineStateMarkup(snapshot, runtime.inlineExpanded);
    const signature = `${message.getAttribute('mesid') || ''}|${String(runtime.inlineExpanded)}|${markup}`;
    panel.classList.toggle('ls-inline-open', runtime.inlineExpanded);
    panel.classList.toggle('ls-inline-empty', entries.length === 0);
    if (runtime.inlineRenderSignature !== signature || panel.innerHTML !== markup) {
      panel.innerHTML = markup;
      runtime.inlineRenderSignature = signature;
    }
    return panel;
  }

  function getPanelViewport(panel) {
    const document = panel?.ownerDocument || runtime.hostDocument;
    const view = document?.defaultView || root;
    return {
      width: Math.max(0, document?.documentElement?.clientWidth || view?.innerWidth || 0),
      height: Math.max(0, document?.documentElement?.clientHeight || view?.innerHeight || 0),
    };
  }

  function syncMobileViewport(panel) {
    const document = panel?.ownerDocument || runtime.hostDocument;
    const view = document?.defaultView || root;
    const viewport = getPanelViewport(panel);
    if (viewport.width > 720) return;
    const visible = view?.visualViewport;
    const height = visible?.height || viewport.height;
    const safe = height < 400 ? { top: 8, bottom: 8 } : getPanelSafeInsets(panel, viewport);
    const values = {
      '--ls-viewport-width': visible?.width || viewport.width,
      '--ls-viewport-height': height,
      '--ls-viewport-top': visible?.offsetTop || 0,
      '--ls-viewport-left': visible?.offsetLeft || 0,
      '--ls-mobile-top': safe.top,
      '--ls-mobile-bottom': safe.bottom,
    };
    for (const id of [CONFIG.panelId, CONFIG.dailyPanelId, CONFIG.externalResponsePanelId]) {
      const target = document?.getElementById(id);
      if (target) for (const [key, value] of Object.entries(values)) target.style.setProperty(key, `${value}px`);
    }
  }

  function getPanelSafeInsets(panel, viewport) {
    const document = panel?.ownerDocument || runtime.hostDocument;
    const view = document?.defaultView || root;
    if (viewport.width > 720 || typeof view?.getComputedStyle !== 'function') {
      return { top: 8, bottom: 8 };
    }
    const styles = view.getComputedStyle(document.documentElement);
    const topBar = Number.parseFloat(styles.getPropertyValue('--topBarBlockSize')) || 0;
    const bottomForm = Number.parseFloat(styles.getPropertyValue('--bottomFormBlockSize')) || 0;
    return {
      top: Math.max(8, topBar + 8),
      bottom: Math.max(8, bottomForm + 8),
    };
  }

  function clampPanelPosition(panel, left, top) {
    const margin = 8;
    const rect = panel.getBoundingClientRect();
    const viewport = getPanelViewport(panel);
    const safe = getPanelSafeInsets(panel, viewport);
    const maxLeft = Math.max(margin, viewport.width - rect.width - margin);
    const usableHeight = Math.max(0, viewport.height - safe.top - safe.bottom);
    const maxTop = Math.max(safe.top, viewport.height - safe.bottom - Math.min(rect.height, usableHeight));
    return {
      left: Math.min(Math.max(Number(left) || 0, margin), maxLeft),
      top: Math.min(Math.max(Number(top) || 0, safe.top), maxTop),
    };
  }

  function applyPanelPosition(panel, position, persist = false) {
    if (!panel || !isPlainObject(position)) return false;
    const next = clampPanelPosition(panel, position.left, position.top);
    panel.style.left = `${next.left}px`;
    panel.style.top = `${next.top}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    panel.style.transform = 'none';
    panel.dataset.userPositioned = 'true';
    delete panel.dataset.defaultPositioned;
    if (persist) {
      try {
        root.localStorage?.setItem(CONFIG.panelPositionKey, JSON.stringify(next));
      } catch (error) {
        logStateError('panel_position_save_failed', error);
      }
    }
    return true;
  }

  function restorePanelPosition(panel) {
    let saved = null;
    try {
      const raw = root.localStorage?.getItem(CONFIG.panelPositionKey);
      if (raw) saved = JSON.parse(raw);
    } catch (error) {
      logStateError('panel_position_load_failed', error);
    }
    if (!isPlainObject(saved) || !Number.isFinite(saved.left) || !Number.isFinite(saved.top)) return false;
    return applyPanelPosition(panel, saved, false);
  }

  function applyDefaultMobilePanelPosition(panel) {
    if (!panel) return false;
    const viewport = getPanelViewport(panel);
    if (viewport.width <= 0 || viewport.height <= 0 || viewport.width > 720) return false;
    const rect = panel.getBoundingClientRect();
    const safe = getPanelSafeInsets(panel, viewport);
    const right = 10;
    const usableHeight = Math.max(0, viewport.height - safe.top - safe.bottom);
    const travel = Math.max(0, usableHeight - rect.height);
    const next = clampPanelPosition(
      panel,
      viewport.width - rect.width - right,

      safe.top + travel * 0.68,
    );
    panel.style.left = `${next.left}px`;
    panel.style.top = `${next.top}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    panel.style.transform = 'none';
    panel.dataset.defaultPositioned = 'true';
    return true;
  }

  function clearDefaultPanelPosition(panel) {
    if (!panel || panel.dataset.defaultPositioned !== 'true') return;
    panel.style.removeProperty('left');
    panel.style.removeProperty('top');
    panel.style.removeProperty('right');
    panel.style.removeProperty('bottom');
    panel.style.removeProperty('transform');
    delete panel.dataset.defaultPositioned;
  }

  function schedulePanelClamp(panel = runtime.hostDocument?.getElementById(CONFIG.panelId)) {
    if (!panel) return;
    const view = panel.ownerDocument?.defaultView || root;
    const run = () => {
      if (!panel.isConnected) return;
      syncMobileViewport(panel);

      if (getPanelViewport(panel).width <= 720 && panel.classList.contains('ls-open')) return;
      if (panel.dataset.userPositioned === 'true') {
        const rect = panel.getBoundingClientRect();
        applyPanelPosition(panel, { left: rect.left, top: rect.top }, false);
        return;
      }
      if (getPanelViewport(panel).width <= 720) applyDefaultMobilePanelPosition(panel);
      else clearDefaultPanelPosition(panel);
    };
    if (typeof view?.requestAnimationFrame === 'function') view.requestAnimationFrame(run);
    else setTimeout(run, 0);
  }

  function bindPanelDragging(panel) {
    const handle = panel?.querySelector('.ls-bar');
    if (!handle || panel.dataset.dragBound === 'true') return;
    panel.dataset.dragBound = 'true';
    const view = panel.ownerDocument?.defaultView || root;

    let drag = null;
    const finish = (event) => {
      if (!drag || event.pointerId !== drag.pointerId) return;
      if (drag.moved) {
        const rect = panel.getBoundingClientRect();
        applyPanelPosition(panel, { left: rect.left, top: rect.top }, true);
        runtime.suppressToggleUntil = Date.now() + 450;
      }
      panel.classList.remove('ls-dragging');
      try { handle.releasePointerCapture?.(drag.pointerId); } catch (_) {   }
      drag = null;
    };

    handle.addEventListener('pointerdown', (event) => {
      if (event.target.closest?.('.ls-pregnancy-awareness, input, select, textarea, [contenteditable="true"]')) return;
      if (getPanelViewport(panel).width <= 720 && panel.classList.contains('ls-open')) return;
      if (event.button !== undefined && event.button !== 0) return;
      if (!event.target.closest?.('.ls-summary, .ls-mobile-icon, .ls-modern-header-brand')) return;
      const rect = panel.getBoundingClientRect();
      drag = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        startLeft: rect.left,
        startTop: rect.top,
        moved: false,
      };

    });

    const onPointerMove = (event) => {
      if (!drag || event.pointerId !== drag.pointerId) return;
      const deltaX = event.clientX - drag.startX;
      const deltaY = event.clientY - drag.startY;
      if (!drag.moved && Math.hypot(deltaX, deltaY) < 4) return;
      if (!drag.moved) {
        drag.moved = true;
        panel.classList.add('ls-dragging');
        try { handle.setPointerCapture?.(event.pointerId); } catch (_) {   }
      }
      event.preventDefault();
      applyPanelPosition(panel, {
        left: drag.startLeft + deltaX,
        top: drag.startTop + deltaY,
      }, false);
    };

    view?.addEventListener?.('pointermove', onPointerMove);
    view?.addEventListener?.('pointerup', finish);
    view?.addEventListener?.('pointercancel', finish);
    runtime.unsubscribers.push(() => {
      view?.removeEventListener?.('pointermove', onPointerMove);
      view?.removeEventListener?.('pointerup', finish);
      view?.removeEventListener?.('pointercancel', finish);
    });
    const onResize = () => schedulePanelClamp(panel);
    view?.addEventListener?.('resize', onResize);
    runtime.unsubscribers.push(() => view?.removeEventListener?.('resize', onResize));
    const onVisibleResize = () => {
      schedulePanelClamp(panel);
      view?.requestAnimationFrame?.(() => {
        const field = panel.ownerDocument?.activeElement;
        const body = panel.querySelector('.ls-body');
        if (getPanelViewport(panel).width > 720 || !body?.contains(field) || !field.matches?.('input, textarea, select')) return;
        const bounds = body.getBoundingClientRect();
        const rect = field.getBoundingClientRect();
        if (rect.bottom > bounds.bottom - 12) body.scrollTop += rect.bottom - bounds.bottom + 12;
        else if (rect.top < bounds.top + 12) body.scrollTop -= bounds.top + 12 - rect.top;
      });
    };
    view?.visualViewport?.addEventListener?.('resize', onVisibleResize);
    view?.visualViewport?.addEventListener?.('scroll', onResize);
    runtime.unsubscribers.push(() => {
      view?.visualViewport?.removeEventListener?.('resize', onVisibleResize);
      view?.visualViewport?.removeEventListener?.('scroll', onResize);
    });
  }

  function buildDailyPickerMarkup(modules = runtime.modules) {
    const selected = new Set(normalizeModules(modules).daily_needs);
    const labels = { drink: '饮水', meal: '进食', urination: '排尿', bowel_movement: '排便', sleep: '睡眠' };
    return `<button class="ls-daily-backdrop" type="button" data-action="daily-dismiss" aria-label="关闭日常追踪面板"></button><section class="ls-daily-dialog" role="dialog" aria-modal="true" aria-labelledby="life-state-daily-title"><header class="ls-daily-head"><h2 class="ls-daily-title" id="life-state-daily-title">日常追踪 ${selected.size}/5</h2><button class="ls-daily-close" type="button" data-action="daily-close" aria-label="关闭日常追踪">关闭</button></header><div class="ls-daily-content"><div class="ls-daily-grid">${NEED_KEYS.map((key) => `<button class="ls-daily-choice" type="button" data-action="daily-need" data-need-key="${key}" aria-pressed="${String(selected.has(key))}">${labels[key]}</button>`).join('')}</div><div class="ls-daily-bulk-row"><button class="ls-daily-bulk" type="button" data-action="daily-all">全部开启</button><button class="ls-daily-bulk" type="button" data-action="daily-none">全部关闭</button></div></div></section>`;
  }

  function closeDailyPicker(document = runtime.hostDocument || getHostDocument()) {
    if (!runtime.dailyPickerOpen) return;
    runtime.dailyPickerOpen = false;
    renderStatePanel(runtime.snapshot, document);
    document?.querySelector?.(`#${CONFIG.panelId} .ls-daily-toggle`)?.focus?.();
  }

  function ensureDailyPickerPanel(document = runtime.hostDocument || getHostDocument()) {
    if (!document?.body) return null;
    let overlay = document.getElementById(CONFIG.dailyPanelId);
    if (overlay) return overlay;
    overlay = document.createElement('div');
    overlay.id = CONFIG.dailyPanelId;
    overlay.setAttribute('aria-hidden', 'true');
    overlay.addEventListener('click', (event) => {
      const button = event.target.closest?.('[data-action]');
      if (!button) return;
      if (button.dataset.action === 'daily-close' || button.dataset.action === 'daily-dismiss') {
        closeDailyPicker(document);
      } else if (button.dataset.action === 'daily-need') {
        const key = button.dataset.needKey;
        const selected = new Set(normalizeModules(runtime.modules).daily_needs);
        if (selected.has(key)) selected.delete(key); else if (NEED_KEYS.includes(key)) selected.add(key);
        runtime.queue = runtime.queue
          .then(() => setDailyNeeds([...selected], runtime.adapter))
          .catch((error) => logStateError('daily_toggle_failed', error, 'error'));
      } else if (button.dataset.action === 'daily-all' || button.dataset.action === 'daily-none') {
        runtime.queue = runtime.queue
          .then(() => setDailyNeeds(button.dataset.action === 'daily-all' ? NEED_KEYS : [], runtime.adapter))
          .catch((error) => logStateError('daily_toggle_failed', error, 'error'));
      }
    });
    const onKeyDown = (event) => {
      if (event.key === 'Escape' && runtime.dailyPickerOpen) {
        event.preventDefault();
        closeDailyPicker(document);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    runtime.unsubscribers.push(() => document.removeEventListener('keydown', onKeyDown));
    document.body.appendChild(overlay);
    return overlay;
  }

  function renderDailyPickerPanel(document = runtime.hostDocument || getHostDocument()) {
    const overlay = ensureDailyPickerPanel(document);
    if (!overlay) return null;
    overlay.classList.toggle('ls-daily-open', runtime.dailyPickerOpen);
    overlay.setAttribute('aria-hidden', String(!runtime.dailyPickerOpen));
    overlay.innerHTML = runtime.dailyPickerOpen ? buildDailyPickerMarkup(runtime.modules) : '';
    syncMobileViewport(overlay);
    return overlay;
  }

  function buildExternalResponseMarkup(entry = runtime.externalLastResponse) {
    if (!entry) {
      return '<button class="ls-external-response-backdrop" type="button" data-action="external-response-dismiss" aria-label="关闭最近响应"></button><section class="ls-external-response-dialog" role="dialog" aria-modal="true" aria-labelledby="life-state-external-response-title"><header class="ls-external-response-head"><h2 id="life-state-external-response-title">最近一次外接响应</h2><button type="button" data-action="external-response-close">关闭</button></header><div class="ls-external-response-empty">还没有外接响应。</div></section>';
    }
    const success = entry.phase === 'response';
    const stateResult = entry.state_result === 'updated' ? '已更新'
      : entry.state_result === 'not_saved' ? '未保存'
        : entry.state_result === 'checking' ? '待校验与保存' : '';
    const meta = [
      success ? '已解析' : '请求或解析失败',
      stateResult,
      entry.kind || '',
      entry.status ? `HTTP ${entry.status}` : '',
      entry.api_format || '',
      entry.transport === 'tavern' ? '酒馆代发' : entry.transport === 'direct' ? '浏览器直连' : '',
      entry.finish_reason ? `finish_reason: ${entry.finish_reason}` : '',
      entry.model || '',
      String(entry.captured_at || '').replace('T', ' ').replace(/\.\d{3}Z$/, 'Z'),
    ].filter(Boolean).map((item) => `<span>${escapeHtml(item)}</span>`).join('');
    const readable = typeof entry.response_text === 'string' && entry.response_text.trim()
      ? `<section><h3>识别到的正文</h3><pre>${escapeHtml(entry.response_text)}</pre></section>`
      : `<section><h3>识别到的正文</h3><div class="ls-external-response-empty">没有识别到可用正文。</div></section>`;
    const rawValue = entry.raw_response !== null && entry.raw_response !== undefined
      ? JSON.stringify(entry.raw_response, null, 2)
      : String(entry.raw_response_text || '');
    const raw = rawValue
      ? `<section><h3>接口原始返回</h3><pre>${escapeHtml(rawValue)}</pre></section>`
      : '<section><h3>接口原始返回</h3><div class="ls-external-response-empty">本次没有可显示的响应正文。</div></section>';
    const failureMessage = [!success ? entry.message : '', entry.state_message].filter(Boolean).filter((text, index, all) => all.indexOf(text) === index).join('；');
    const error = failureMessage
      ? `<div class="ls-external-response-error">${escapeHtml(failureMessage)}</div>` : '';
    return `<button class="ls-external-response-backdrop" type="button" data-action="external-response-dismiss" aria-label="关闭最近响应"></button><section class="ls-external-response-dialog" role="dialog" aria-modal="true" aria-labelledby="life-state-external-response-title"><header class="ls-external-response-head"><div><h2 id="life-state-external-response-title">最近一次外接响应</h2><div class="ls-external-response-meta">${meta}</div></div><div><button type="button" data-action="external-response-copy">复制</button><button type="button" data-action="external-response-close">关闭</button></div></header>${error}<div class="ls-external-response-body">${readable}${raw}</div></section>`;
  }

  function scanReturnReportText(view = runtime.characterProfileScanReport) {
    if (!view) return '';
    return [view.source + ' · 人物扫描返回', '失败原因：' + (view.error || '无'),
      view.redacted ? '已隐藏与当前外接配置一致的密钥。' : '',
      view.serialized ? '宿主返回的是对象，以下为对象的 JSON 展示。' : '',
      view.repair_status ? '格式修复：' + (view.repair_status === 'repaired' ? '已通过格式与资料保全检查' : '未采用') + '\n原格式问题：' + view.validation_error : '',
      '── 模型实际返回 ──', view.raw || '未取得可展示的模型回复。',
      view.repair_status ? '── 格式修复返回 ──\n' + (view.repair_raw || '未取得可展示的修复回复。') : ''].filter(Boolean).join('\n\n');
  }

  function buildScanReturnMarkup(view = runtime.scanReturnView) {
    if (!view) return '';
    const repaired = view.repair_status === 'repaired';
    const repair = view.repair_status ? `<section><h3>格式修复返回${repaired ? '（已通过检查）' : '（未采用）'}</h3><p class="ls-external-response-empty">原格式问题：${escapeHtml(view.validation_error || '')}</p><pre data-scan-repair-text style="font-size:14px;line-height:1.65;white-space:pre-wrap;overflow-wrap:anywhere">${escapeHtml(view.repair_raw || '未取得可展示的修复回复。')}</pre></section>` : '';
    return `<button class="ls-external-response-backdrop" type="button" data-action="external-response-dismiss" aria-label="关闭扫描返回"></button><section class="ls-external-response-dialog" role="dialog" aria-modal="true" aria-labelledby="life-state-external-response-title"><header class="ls-external-response-head"><div><h2 id="life-state-external-response-title">人物扫描返回</h2><div class="ls-external-response-meta">${escapeHtml(view.source)}</div></div><div><button type="button" data-action="scan-return-copy">复制返回内容</button><button type="button" data-action="external-response-close">关闭</button></div></header><div class="ls-external-response-body" style="grid-template-columns:minmax(0,1fr)"><section><h3>${view.error ? '失败原因' : '处理结果'}</h3><div class="${view.error ? 'ls-external-response-error' : 'ls-external-response-empty'}">${escapeHtml(view.error || (repaired ? '格式已修复，人物资料保留；请自行选择建档。' : '扫描完成'))}</div><p class="ls-external-response-empty">仅展示本次模型回复，不包含发送的请求或角色资料。回复本身可能包含人物信息，转发前请检查。记录仅临时保留，刷新或切换聊天后清除。</p><p class="ls-external-response-empty" data-scan-copy-status role="status" aria-live="polite"></p></section><section><h3>模型实际返回${view.serialized ? '（宿主对象转为 JSON 展示）' : ''}</h3>${view.redacted ? '<p class="ls-external-response-empty">已隐藏与当前外接配置一致的密钥。</p>' : ''}${view.raw ? `<pre data-scan-return-text style="font-size:14px;line-height:1.65;white-space:pre-wrap;overflow-wrap:anywhere">${escapeHtml(view.raw)}</pre>` : '<p class="ls-external-response-empty">未取得可展示的模型回复；可能在连接、读取资料或接收结果前失败。</p>'}</section>${repair}</div></section>`;
  }

  async function copyScanReturn(document = runtime.hostDocument || getHostDocument()) {
    const view = runtime.scanReturnView;
    if (!view) return;
    const content = scanReturnReportText(view);
    let copied = false;
    try { if (root.navigator?.clipboard?.writeText) { await root.navigator.clipboard.writeText(content); copied = true; } } catch (_) {   }
    if (runtime.scanReturnView !== view) return;
    if (!copied && document?.body) {
      const field = document.createElement('textarea');
      field.value = content; field.readOnly = true;
      field.style.cssText = 'position:fixed;left:0;top:0;opacity:0;font-size:16px';
      document.body.appendChild(field);
      try { field.select(); field.setSelectionRange(0, content.length); copied = document.execCommand?.('copy') === true; } catch (_) {   }
      finally { field.remove(); }
    }
    const overlay = document?.getElementById(CONFIG.externalResponsePanelId);
    const notice = overlay?.querySelector('[data-scan-copy-status]');
    if (notice) notice.textContent = copied ? '已复制返回内容和处理结果。' : '自动复制未成功，请长按或选中下方返回内容复制。';
    overlay?.querySelector('[data-action="scan-return-copy"]')?.focus?.();
  }

