          renderStatePanel(runtime.snapshot);
        }
      } else if (button.dataset.action === 'select-clamp-weight') {
        if (runtime.playDraft?.kind === 'clamp_pressure' && runtime.playDraft.pendant_variant === '砝码坠') {
          runtime.playDraft = { ...runtime.playDraft, weight: button.dataset.weight || '' };
          renderStatePanel(runtime.snapshot);
        }
      } else if (button.dataset.action === 'append-clamp-reference') {
        if (runtime.playDraft?.kind === 'clamp_pressure') {
          const found = findPlayLibraryEntry(CLAMP_PRESSURE_SELECTABLE_SECTIONS, runtime.playDraft.entry_id);
          const reference = found ? (CLAMP_PRESSURE_DESIGN_REFERENCE.entries[found.entry.label] || [])[Number(button.dataset.referenceIndex)] : null;
          if (reference?.text) {
            const current = sanitizePlayDetail(runtime.playDraft.detail, 500);
            const next = current.includes(reference.text) ? current : [current, reference.text].filter(Boolean).join('；');
            runtime.playDraft = { ...runtime.playDraft, detail: sanitizePlayDetail(next, 500) };
            renderStatePanel(runtime.snapshot);
          }
        }
      } else if (handleRestraintAction(button)) {
        return;
      } else if (button.dataset.action === 'select-play-character') {
        if (runtime.playDraft) {
          runtime.playDraft = { ...runtime.playDraft, character: button.dataset.characterName || '' };
          renderStatePanel(runtime.snapshot);
        }
      } else if (button.dataset.action === 'apply-play-combination') {
        if (runtime.playDraft) {
          const draft = cloneJson(runtime.playDraft);
          const editingId = runtime.playEditingId;
          const applicationAdapter = runtime.adapter;
          const applicationChat = operationChatIdentity(applicationAdapter);
          const hasInputDraft = ['restraint', 'marking', 'body_modification'].includes(draft.kind);
          if (hasInputDraft && runtime.restraintApplying) return;
          if (hasInputDraft) { runtime.restraintApplying = true; button.disabled = true; }
          runtime.queue = runtime.queue
            .then(() => {
              if (hasInputDraft) assertOperationChatUnchanged(applicationAdapter, applicationChat);
              return applyPlayCombination(draft, hasInputDraft ? applicationAdapter : runtime.adapter, editingId);
            })
            .catch((error) => {
              logStateError('play_combination_apply_failed', error, 'error');
              if (hasInputDraft && operationChatIdentity(applicationAdapter) === applicationChat) { runtime.playFeedback = error.message; renderStatePanel(runtime.snapshot); }
            })
            .finally(() => { if (hasInputDraft) runtime.restraintApplying = false; });
        }
      } else if (button.dataset.action === 'complete-play-combination') {
        runtime.queue = runtime.queue
          .then(() => completePlayCombination(button.dataset.combinationId, runtime.adapter))
          .catch((error) => logStateError('play_combination_complete_failed', error, 'error'));
      } else if (button.dataset.action === 'cancel-play-draft') {
        runtime.playDraft = null;
        runtime.playEditingId = '';
        renderStatePanel(runtime.snapshot);
      } else if (button.dataset.action === 'edit-play-combination') {
        const combination = sanitizePlayCombinations(runtime.playCombinations).find((item) => item.id === button.dataset.combinationId && item.active !== false);
        if (combination) {
          runtime.playDraft = cloneJson(combination);
          runtime.playEditingId = combination.id;
          runtime.playLibraryPage = combination.kind === 'restraint' ? 'restraint' : (NARRATIVE_LIBRARY_PLAY_KINDS.includes(combination.kind) ? 'tools' : combination.kind);
          runtime.playLibrarySearch = '';
          renderStatePanel(runtime.snapshot);
        }
      } else if (button.dataset.action === 'remove-play-combination') {
        runtime.queue = runtime.queue
          .then(() => setPlayCombinationActive(button.dataset.combinationId, false, runtime.adapter))
          .catch((error) => logStateError('play_combination_remove_failed', error, 'error'));
      } else if (button.dataset.action === 'clear-play-combinations') {
        runtime.queue = runtime.queue
          .then(() => clearActivePlayCombinations(runtime.adapter))
          .catch((error) => logStateError('play_combination_clear_failed', error, 'error'));
      } else if (button.dataset.action === 'clear-play-injection') {
        runtime.queue = runtime.queue
          .then(() => clearPlayInjection(runtime.adapter))
          .catch((error) => logStateError('play_injection_clear_failed', error, 'error'));
      } else if (button.dataset.action === 'restore-archive') {
        const names = availableArchiveNames();
        const selected = names[Number(button.dataset.archiveIndex)];
        if (selected) {
          runtime.queue = runtime.queue
            .then(() => requestArchiveRestore(selected, runtime.adapter))
            .catch((error) => logStateError('archive_restore_failed', error, 'error'));
        }
      } else if (button.dataset.action === 'delete-archive') {
        const names = availableArchiveNames();
        const selected = names[Number(button.dataset.archiveIndex)];
        if (selected) {
          runtime.queue = runtime.queue
            .then(() => deleteReproductiveArchive(selected, runtime.adapter))
            .catch((error) => logStateError('archive_delete_failed', error, 'error'));
        }
      }
    });

    panel.addEventListener('toggle', (event) => {
      if (!panel.contains(event.target)) return;
      if (event.target.matches?.('.ls-cleaning-rule-list')) runtime.externalCleaningUI.rulesOpen = event.target.open;
      const sampleId = event.target.dataset?.cleaningSample;
      if (sampleId) {
        const ui = runtime.externalCleaningUI;
        ui.openSamples = event.target.open ? [...new Set([...ui.openSamples, sampleId])] : ui.openSamples.filter(id => id !== sampleId);
      }
    }, true);

    panel.addEventListener('change', (event) => {
      if (event.target.matches?.('.ls-external-model-list')) {
        const selected = event.target.value;
        const editor = event.target.closest('.ls-external-settings');
        if (selected && runtime.externalModelCatalog.models.includes(selected)) {
          const input = editor.querySelector('.ls-external-model');
          input.value = selected;
          rememberEditorDraft({ target: input });
        }
        return;
      }
      const cleaningRule = event.target.closest?.('[data-cleaning-rule]');
      if (cleaningRule) {
        toggleExternalCleaningRule(cleaningRule.dataset.cleaningRule, cleaningRule.checked);
        return;
      }
      const sexSelect = event.target.closest?.('[data-role="character-profile-sex"]');
      if (!sexSelect) return;
      const editor = sexSelect.closest('.ls-character-profile-setup');
      syncCharacterProfileEditor(editor);
    });

    panel.addEventListener('input', rememberEditorDraft);
    panel.addEventListener('change', rememberEditorDraft);
    panel.addEventListener('compositionstart', event => {
      if (event.target.closest?.('[data-draft-key]')) runtime.composingEditor = event.target;
    });
    panel.addEventListener('compositionend', finishEditorComposition);
    panel.addEventListener('focusout', finishEditorComposition);

    panel.addEventListener('input', (event) => {
      if (updateRestraintDraftInput(event, panel)) return;
      if (event.target.matches?.('[data-role="cleaning-feedback"]')) {
        runtime.externalCleaningUI.feedback = event.target.value.slice(0, 2000);
        return;
      }
      const markingDetail = event.target.closest?.('[data-role="marking-detail"]');
      if (markingDetail && runtime.playDraft?.kind === 'marking') {
        runtime.playDraft = { ...runtime.playDraft, detail: String(markingDetail.value || '').slice(0, 500) };
        const preview = panel.querySelector('[data-role="play-input-preview"]');
        if (preview) preview.textContent = playInputDraft(runtime.playDraft) || '选择人物并补全设置后生成。';
        return;
      }
      const detail = event.target.closest?.('[data-role="bodymod-detail"]');
      if (detail && runtime.playDraft?.kind === 'body_modification') {
        const details = cloneJson(runtime.playDraft.details || { base: '', jewelry: '', accessories: {}, extensions: {} });
        if (!isPlainObject(details.accessories)) details.accessories = {};
        if (!isPlainObject(details.extensions)) details.extensions = {};
        const value = String(detail.value || '').slice(0, 240);
        if (detail.dataset.detailKind === 'base') details.base = value;
        else if (detail.dataset.detailKind === 'jewelry') details.jewelry = value;
        else if (detail.dataset.detailKind === 'accessory' && detail.dataset.entryId) details.accessories[detail.dataset.entryId] = value;
        else if (detail.dataset.detailKind === 'extension' && detail.dataset.entryId) details.extensions[detail.dataset.entryId] = value;
        runtime.playDraft = { ...runtime.playDraft, details };
        const preview = panel.querySelector('[data-role="play-input-preview"]');
        if (preview) preview.textContent = playInputDraft(runtime.playDraft) || '选择人物并补全设置后生成。';
        return;
      }
      const clampDetail = event.target.closest?.('[data-role="clamp-detail"]');
      if (clampDetail && runtime.playDraft?.kind === 'clamp_pressure') {
        runtime.playDraft = { ...runtime.playDraft, detail: String(clampDetail.value || '').slice(0, 500) };
        return;
      }
      const largeEquipmentDetail = event.target.closest?.('[data-role="large-equipment-detail"]');
      const connectionDetail = event.target.closest?.('[data-role="equipment-connection-detail"]');
      if (connectionDetail && NARRATIVE_LIBRARY_PLAY_KINDS.includes(runtime.playDraft?.kind)) {
        const entry = narrativeOnlyPlayLibrary(runtime.playDraft.kind)?.entries.find((item) => item.id === runtime.playDraft.entry_id);
        if (entry?.connection) runtime.playDraft = { ...runtime.playDraft, connection_detail: String(connectionDetail.value || '').slice(0, 500) };
        return;
      }
      if (largeEquipmentDetail && NARRATIVE_LIBRARY_PLAY_KINDS.includes(runtime.playDraft?.kind)) {
        runtime.playDraft = { ...runtime.playDraft, detail: String(largeEquipmentDetail.value || '').slice(0, 500) };
        return;
      }
      const input = event.target.closest?.('[data-role="play-library-search"]');
      if (!input) return;
      runtime.playLibrarySearch = String(input.value || '').trim();
      const needle = runtime.playLibrarySearch.toLowerCase();
      for (const entry of panel.querySelectorAll('.ls-play-library-entry[data-play-search]')) {
        const hidden = Boolean(needle) && !String(entry.dataset.playSearch || '').includes(needle);
        entry.classList.toggle('ls-search-hidden', hidden);
        if (needle && !hidden) {
          let section = entry.closest('details.ls-play-library-section');
          while (section) { section.open = true; section = section.parentElement?.closest('details.ls-play-library-section'); }
        }
      }
    });

    document.body.appendChild(panel);
    bindPanelDragging(panel);
    restorePanelPosition(panel);
    return panel;
  }

  function updatePanelOpenState(panel = runtime.hostDocument?.getElementById(CONFIG.panelId)) {
    if (!panel) return;
    panel.classList.toggle('ls-open', runtime.expanded);
    const toggle = panel.querySelector('.ls-toggle');
    const body = panel.querySelector('.ls-body');
    toggle?.setAttribute('aria-expanded', String(runtime.expanded));
    body?.setAttribute('aria-hidden', String(!runtime.expanded));
    schedulePanelClamp(panel);
  }

  function refreshDebugPanel() {
    const panel = runtime.hostDocument?.getElementById(CONFIG.panelId);
    if (!panel) return;
    panel.classList.toggle('ls-debug-on', runtime.debug);
    panel.querySelector('.ls-debug-toggle')?.setAttribute('aria-pressed', String(runtime.debug));
    const debug = panel.querySelector('.ls-debug');
    if (debug) {
      debug.textContent = runtime.logs.length
        ? runtime.logs.map((item) => `[${item.time}] ${item.code}: ${item.message}`).join('\n')
        : '暂无调试记录';
    }
  }

  function renderStatePanel(snapshot, document = runtime.hostDocument || getHostDocument()) {
    snapshot = reconcileCyclePresence(snapshot, snapshot, runtime.cyclePresenceEnabled, effectiveRuntimeModules());
    const panel = ensureStatePanel(document);
    if (!panel) return null;
    if (runtime.composingEditor?.isConnected && panel.contains(runtime.composingEditor)) {
      runtime.editorRefreshDeferred = true;
      return panel;
    }
    const editorView = captureEditorView(panel);
