      dailyButton.textContent = `日常追踪 ${effectiveDailyCount}/5${effectiveDailyCount > dailyCount ? ' · 联动' : ''}`;
      dailyButton.title = '打开日常追踪选择；点击项目立即保存，不自动发送';
