      reproductiveButton.textContent = reproductiveEffective ? `生殖 ●${runtime.modules.reproductive ? '' : ' · 联动'}` : '生殖 ○';
      reproductiveButton.title = runtime.modules.reproductive ? '生殖模块已开启；点击关闭但保留长期档案' : '生殖模块已关闭；点击开启并按长期档案恢复';
