  function refreshStatePanel() {
    if (runtime.destroyed || runtime.externalStaging) return;
    return renderStatePanel(runtime.snapshot);
  }

  function normalizeUiStyle(value) {
    return value === UI_STYLES.CLASSIC ? UI_STYLES.CLASSIC : UI_STYLES.MODERN;
  }

  function loadUiStyle(storage) {
    try { return normalizeUiStyle((storage ?? root.localStorage)?.getItem(CONFIG.uiStyleKey)); }
    catch (_) { return UI_STYLES.MODERN; }
  }

  function normalizeUiTheme(value) {
    return Object.values(UI_THEMES).includes(value) ? value : UI_THEMES.SUNNY;
  }

  function loadUiTheme(storage) {
    try { return normalizeUiTheme((storage ?? root.localStorage)?.getItem(CONFIG.uiThemeKey)); }
    catch (_) { return UI_THEMES.SUNNY; }
  }

  function setUiTheme(value, document = runtime.hostDocument || getHostDocument(), storage) {
    runtime.uiTheme = normalizeUiTheme(value);
    try { (storage ?? root.localStorage)?.setItem(CONFIG.uiThemeKey, runtime.uiTheme); }
    catch (error) { logStateError('ui_theme_save_failed', error, 'warn'); }
    setUiStyle(UI_STYLES.MODERN, document, storage);
    return runtime.uiTheme;
  }

  function setUiStyle(value, document = runtime.hostDocument || getHostDocument(), storage) {
    const style = normalizeUiStyle(value);
    runtime.uiStyle = style;
    runtime.modernPage = 'settings';
    runtime.settingsPage = 'appearance';
    try { (storage ?? root.localStorage)?.setItem(CONFIG.uiStyleKey, style); }
    catch (error) { logStateError('ui_style_save_failed', error, 'warn'); }
    renderStatePanelKeepingDrafts(document);
    return style;
  }

  function renderStatePanelKeepingDrafts(document) {
    return renderStatePanel(runtime.snapshot, document);
  }

  function editorFieldKey(field) {
    if (!field?.matches?.('input, select, textarea')) return '';
    if (field.hasAttribute('data-profile-cycle-input')) return 'cycle-input';
    if (field.hasAttribute('data-profile-sex-choice')) return `sex-choice:${field.value}`;
    if (field.hasAttribute('data-profile-stage-choice')) return `stage-choice:${field.closest('.ls-pe-stage-field')?.querySelector('select')?.dataset.needKey}:${field.value}`;
    return `${field.dataset.role || field.className}:${field.dataset.needKey || ''}`;
  }

  function clearEditorDrafts(prefix = '') {

    const focused = (runtime.hostDocument || getHostDocument())?.activeElement;
    if (focused?.closest?.('[data-draft-key]')?.dataset.draftKey.startsWith(prefix)) focused.blur();
    for (const key of runtime.editorDrafts.keys()) if (key.startsWith(prefix)) runtime.editorDrafts.delete(key);
    if (!prefix) { runtime.composingEditor = null; runtime.editorRefreshDeferred = false; setManualSaveNotice(''); runtime.contentDefaultsNotice = ''; runtime.contentDefaultsError = false; }
  }

  function rememberEditorDraft(event) {
    const editor = event.target.closest?.('[data-draft-key]');
    if (!editor || !editorFieldKey(event.target)) return;
    const fields = {};
    for (const field of editor.querySelectorAll('input, select, textarea')) {
      fields[editorFieldKey(field)] = { value: field.value, checked: field.checked,
        invalid: field.dataset.profileCycleInvalid === 'true' };
    }
    runtime.editorDrafts.set(editor.dataset.draftKey, fields);
    if (editor.dataset.draftKey === 'api') updateExternalConfigFeedback(editor);
  }

  function finishEditorComposition(event) {
    if (runtime.composingEditor !== event.target) return;
    runtime.composingEditor = null;
    rememberEditorDraft(event);
    if (runtime.editorRefreshDeferred) {
      runtime.editorRefreshDeferred = false;
      (root.setTimeout || setTimeout)(() => { if (!runtime.destroyed) refreshStatePanel(); }, 0);
    }
  }

  function captureEditorView(panel) {
    const focused = panel.ownerDocument.activeElement;
    const owner = focused?.closest?.('[data-draft-key]');
    return { scrollTop: panel.querySelector('.ls-body')?.scrollTop || 0,
      focus: owner && panel.contains(owner) ? { owner: owner.dataset.draftKey, field: editorFieldKey(focused),
        start: focused.selectionStart, end: focused.selectionEnd, scrollTop: focused.scrollTop } : null,
      details: [...panel.querySelectorAll('[data-draft-key] details')].map(item => ({ owner: item.closest('[data-draft-key]').dataset.draftKey, className: item.className, open: item.open })) };
  }

  function restoreEditorDrafts(panel, view) {
    for (const editor of panel.querySelectorAll('[data-draft-key]')) {
      const draft = runtime.editorDrafts.get(editor.dataset.draftKey);
      for (const field of editor.querySelectorAll('input, select, textarea')) {
        const value = draft?.[editorFieldKey(field)];
        if (!value || field.closest('[data-profile-cycle-locked="true"]')) continue;
        if (field.tagName === 'SELECT' && ![...field.options].some(option => option.value === value.value)) continue;
        field.value = value.value;
        if (typeof value.checked === 'boolean') field.checked = value.checked;
        if (value.invalid) {
          field.dataset.profileCycleInvalid = 'true';
          field.setCustomValidity('请输入 1 至 28 之间的整数，或选择随机／保持当前。');
          field.setAttribute('aria-invalid', 'true');
        }
      }
      if (editor.matches('.ls-character-profile-setup')) syncCharacterProfileEditor(editor);
      if (editor.dataset.draftKey === 'api') updateExternalConfigFeedback(editor);
      for (const detail of editor.querySelectorAll('details')) {
        const saved = view.details.find(item => item.owner === editor.dataset.draftKey && item.className === detail.className);
        if (saved) detail.open = saved.open;
      }
      if (view.focus?.owner === editor.dataset.draftKey) {
        const field = [...editor.querySelectorAll('input, select, textarea')].find(item => editorFieldKey(item) === view.focus.field);
        if (field && !field.disabled && field.getClientRects().length) {
          field.focus({ preventScroll: true });
          if (Number.isInteger(view.focus.start) && field.setSelectionRange) {
            try { field.setSelectionRange(view.focus.start, view.focus.end); } catch (_) {   }
          }
          field.scrollTop = view.focus.scrollTop;
        }
      }
    }
    const body = panel.querySelector('.ls-body');
    if (body) body.scrollTop = view.scrollTop;
  }

