  function syncSettingsNavigation(panel) {
    const page = SETTINGS_PAGES.some(item => item[0] === runtime.settingsPage) ? runtime.settingsPage : 'home';
    panel.dataset.settingsPage = page;
    const summaries = settingsSummaries();
    const nav = panel.querySelector('.ls-settings-nav');
    if (nav) nav.innerHTML = SETTINGS_PAGES.map(([id, title, icon, hint]) => `<button type="button" class="ls-settings-entry" data-action="settings-page" data-settings-page="${id}" aria-current="${page === id ? 'page' : 'false'}">${modernUiIcon(icon)}<span><strong>${title}</strong><small>${escapeHtml(summaries[id])}</small><span class="ls-settings-entry-hint">${hint}</span></span><span aria-hidden="true">›</span></button>`).join('');
    for (const pane of panel.querySelectorAll('[data-settings-pane]')) pane.hidden = pane.dataset.settingsPane !== page;
    const title = panel.querySelector('.ls-settings-title');
    if (title) title.textContent = SETTINGS_PAGES.find(item => item[0] === page)?.[1] || '设置';
    const back = panel.querySelector('[data-action="settings-home"]');
    if (back) back.hidden = page === 'home';
  }

  function openSettingsPage(page = 'home', document = runtime.hostDocument || getHostDocument()) {
    runtime.settingsPage = SETTINGS_PAGES.some(item => item[0] === page) ? page : 'home';
    runtime.modernPage = 'settings'; runtime.expanded = true;
    runtime.characterProfilePickerOpen = false; runtime.archivePickerOpen = false;
    runtime.playPickerOpen = false; runtime.dailyPickerOpen = false; runtime.debugCenterOpen = false;
    if (page === 'cleaning') runtime.externalCleaningUI.open = true;
    renderStatePanelKeepingDrafts(document);
    const panel = document?.getElementById(CONFIG.panelId);
    if (panel) {
      panel.querySelector('.ls-body').scrollTop = 0;
      panel.querySelector('.ls-settings-title')?.focus({ preventScroll: true });
    }
  }

  function currentModernPage() {
    return runtime.debugUnlocked && runtime.debugCenterOpen ? 'debug'
      : runtime.archivePickerOpen ? 'people'
        : runtime.characterProfilePickerOpen ? 'people'
          : runtime.playPickerOpen ? 'play' : runtime.modernPage;
  }

  function syncModernUi(panel) {
    const modern = runtime.uiStyle === UI_STYLES.MODERN;
    panel.dataset.uiTheme = normalizeUiTheme(runtime.uiTheme);
    const page = currentModernPage();
    panel.dataset.uiPage = page;
    syncSettingsNavigation(panel);
    const classicSettings = panel.querySelector('.ls-settings-toggle');
    if (classicSettings) {
      classicSettings.dataset.action = page === 'settings' ? 'settings-status' : 'settings-open';
      classicSettings.textContent = page === 'settings' ? '状态' : '设置';
    }
    panel.querySelectorAll('[data-action="modern-page"]').forEach(button => {
      button.setAttribute('aria-current', button.dataset.uiPage === page ? 'page' : 'false');
    });
    for (const id of [CONFIG.dailyPanelId, CONFIG.externalResponsePanelId]) {
      const overlay = panel.ownerDocument.getElementById(id);
      overlay?.classList.toggle('ls-modern', modern);
      if (overlay) overlay.dataset.uiTheme = normalizeUiTheme(runtime.uiTheme);
    }
    if (modern) {
      const label = { status: '状态概览', people: '人物档案', play: '玩法库', settings: '设置', archive: '长期档案', debug: '调试中心' }[page];
      const count = Object.keys(runtime.snapshot?.characters || {}).length;
      const summary = panel.querySelector('.ls-summary');
      if (summary) summary.textContent = `${label || '角色手册'} · ${count} 人`;
    }
  }

  function handleModernUiAction(button, event, document) {
    const action = button.dataset.action;
    if (action === 'settings-status') {
      event.preventDefault(); runtime.modernPage = 'status';
      runtime.characterProfilePickerOpen = false; runtime.playPickerOpen = false; runtime.archivePickerOpen = false;
      renderStatePanelKeepingDrafts(document);
      return true;
    }
    if (action === 'state-external-action') {
      event.preventDefault();
      const allowed = ['external-update-now', 'external-stop-inline', 'external-retry', 'external-response'];
      if (allowed.includes(button.dataset.externalAction)) document?.getElementById(CONFIG.panelId)?.querySelector(`[data-settings-pane="mode"] [data-action="${button.dataset.externalAction}"]`)?.click();
      return true;
    }
    if (['settings-page', 'settings-home', 'settings-open'].includes(action)) {
      event.preventDefault();
      openSettingsPage(action === 'settings-page' ? button.dataset.settingsPage : 'home', document);
      return true;
    }
    if (['ui-modern','ui-plum','ui-sunny','ui-classic'].includes(action)) {
      event.preventDefault();
      if(action === 'ui-classic')setUiStyle(UI_STYLES.CLASSIC, document);
      else setUiTheme(action === 'ui-sunny' ? UI_THEMES.SUNNY : action === 'ui-plum' ? UI_THEMES.PLUM : UI_THEMES.INK, document);
      document.getElementById(CONFIG.panelId)?.querySelector(`[data-action="${action}"]`)?.focus?.({ preventScroll: true });
      return true;
    }
    if (action === 'inline-details') {
      const name = button.dataset.characterName;
      if (!Object.prototype.hasOwnProperty.call(runtime.snapshot?.characters || {}, name)) return true;
      if (runtime.inlineDetails.has(name)) runtime.inlineDetails.delete(name);
      else runtime.inlineDetails.add(name);
      renderInlineStatePanel(runtime.snapshot, document);
      [...(document.getElementById(CONFIG.inlinePanelId)?.querySelectorAll('[data-action="inline-details"]') || [])]
        .find(item => item.dataset.characterName === name)?.focus?.({ preventScroll: true });
      return true;
    }
    if (!['modern-page', 'modern-edit-character'].includes(action)) return false;
    event.preventDefault();
    const page = action === 'modern-edit-character' ? 'people' : button.dataset.uiPage;
    if (!['status', 'people', 'play', 'settings'].includes(page)) return true;
    if (page === 'settings') { openSettingsPage('home', document); return true; }
    runtime.modernPage = page === 'settings' ? 'settings' : 'status';
    runtime.characterProfilePickerOpen = page === 'people';
    runtime.playPickerOpen = page === 'play';
    runtime.archivePickerOpen = false;
    runtime.dailyPickerOpen = false;
    runtime.debugCenterOpen = false;
    runtime.expanded = true;
    if (action === 'modern-edit-character') {
      clearEditorDrafts('profile:');
      const name = button.dataset.characterName;
      if (Object.prototype.hasOwnProperty.call(runtime.snapshot?.characters || {}, name)) {
        runtime.activeCharacter = name;
        runtime.characterProfileSetupName = name;
        runtime.characterProfileCustomOpen = false;
      }
    }
    renderStatePanelKeepingDrafts(document);
    const panel = document.getElementById(CONFIG.panelId);
    if (panel?.querySelector('.ls-body')) panel.querySelector('.ls-body').scrollTop = 0;
    return true;
  }

  function buildModernNeedRow(name, key, need) {
    const stage = NEED_STAGES.has(need.stage) ? need.stage : '';
