    const labels = { drink: '上次饮水', meal: '上次进食', urination: '上次排尿', bowel_movement: '上次排便', sleep: '起床时间' };
    const duration = inlineNeedDuration(key, need);
    const meta = [anchor ? `${labels[key]} · ${anchor}` : '', duration ? `${key === 'sleep' ? '清醒' : '已过'} ${duration}` : ''].filter(Boolean);
    if (key === 'sleep' && need.sleeping) meta.splice(0, meta.length, '正在睡眠');
    if (!meta.length) meta.push(`初始状态 · ${formatDuration(initialNeedOffsetForDisplay(name, key, need))}`);
    const notes = [need.notes, need.sleep_information].filter(Boolean).join(' · ');
    return `<article class="ls-modern-need" data-need="${key}" data-stage="${NEED_STAGE_ROUTE_IDS[stage] || ''}"><span class="ls-modern-need-icon">${modernUiIcon(key)}</span><div class="ls-modern-need-copy"><strong>${escapeHtml(NEED_LABELS[key])}</strong><div class="ls-modern-need-meta">${escapeHtml(meta.join(' · '))}</div>${notes ? `<p>${escapeHtml(notes)}</p>` : ''}</div><span class="ls-modern-stage">${escapeHtml(stage || '未定')}</span><span class="ls-need-echo" aria-hidden="true">${modernUiIcon('echo_'+key)}</span></article>`;
  }

  function buildModernInlineDetails(name, character) {
    const needs = NEED_KEYS.filter(key => isPlainObject(character.needs?.[key]));
    return `<div class="ls-modern-inline-details"><div class="ls-modern-inline-needs">${needs.map(key => buildModernNeedRow(name, key, character.needs[key])).join('')}</div><button class="ls-modern-edit" type="button" data-action="modern-edit-character" data-character-name="${escapeHtml(name)}">${modernUiIcon('edit')}编辑档案</button></div>`;
