  async function requestEffectModeChange(mode, adapter = runtime.adapter, document = runtime.hostDocument || getHostDocument()) {
    const nextMode = normalizeEffectMode(mode);
    const current = adapter?.getStore ? await adapter.getStore() : undefined;
