  function buildRestraintDraftEditor() {
    const draft = runtime.playDraft?.kind === 'restraint' ? runtime.playDraft : null;
    const entry = draft ? restraintEntry(draft.entry_id) : null;
    if (!entry) return '';
    const selected = entry.variants.find(item => item.id === draft.variant_id) || entry.variants[0];
    const material = entry.variants.length > 1 ? `<div class="ls-play-draft-group"><strong>绳材</strong><div class="ls-play-choice-row">${entry.variants.map(item => `<button type="button" data-action="select-restraint-material" data-variant-id="${escapeHtml(item.id)}" aria-pressed="${draft.variant_id === item.id}">${escapeHtml(item.label)}</button>`).join('')}</div></div>` : '';
    const partner = entry.pair ? `<div class="ls-play-draft-group"><label class="ls-play-detail"><span>另一位人物</span><input type="text" maxlength="120" data-role="restraint-partner" value="${escapeHtml(draft.partner_character || '')}" placeholder="输入名字，也可点击下方已有角色"></label><div class="ls-play-choice-row">${playApplicationCharacters().filter(name => name !== draft.character).map(name => `<button type="button" data-action="select-restraint-partner" data-character-name="${escapeHtml(name)}" aria-pressed="${draft.partner_character === name}">${escapeHtml(name)}</button>`).join('')}</div><small>共用同一套搭配，已建档人物分别记录状态；填写名字不会自动建档。</small></div>` : '';
    const custom = entry.id === 'custom';
    const preview = restraintInputDraft(draft);
    return `<section class="ls-play-draft ls-restraint-editor"><h4>${escapeHtml(selected?.source.display_title || entry.label)}</h4>${material}${partner}<div class="ls-play-draft-group"><label class="ls-play-detail"><span>${custom ? '本次安排' : '本次补充（选填）'}</span><textarea maxlength="500" data-role="restraint-detail" placeholder="${custom ? '写清材料、固定位置、人物姿态，以及哪些部位仍能活动。' : '可补充外观和本次细节；整套位置关系不同，可选自定义设置。'}">${escapeHtml(draft.detail || '')}</textarea></label></div><details class="ls-play-plain-guide"><summary>输入草稿预览</summary><p data-role="restraint-input-preview">${escapeHtml(preview || '选好人物并补全设置后生成。')}</p></details>${selected ? `<details class="ls-play-plain-guide"><summary>查看所选原文</summary><div>${escapeHtml(selected.source.full_body)}</div></details>` : ''}<section class="ls-play-draft-footer"><h4>应用角色</h4>${buildPlayCharacterChoices(draft)}<small>应用后自动填入聊天输入框，不发送；已有输入保留，持续状态由后续剧情确认。</small><div class="ls-play-draft-actions"><button type="button" data-action="cancel-play-draft">取消</button><button type="button" data-action="apply-play-combination"${normalizeRestraintDraft(draft) ? '' : ' disabled'}>应用并填入草稿</button></div></section></section>`;
  }

  function buildRestraintPlayPage() {
    const furnitureOnly = runtime.restraintFurnitureOnly === true;
    const groups = furnitureOnly ? ['家具固定'] : ['绳缚', '布带与薄膜', '成品束具', '家具固定'];
    const sections = groups.map(group => {
      const entries = RESTRAINT_LIBRARY.entries.filter(entry => entry.group === group);
      const cards = entries.map(entry => {
        const selected = runtime.playDraft?.kind === 'restraint' && runtime.playDraft.entry_id === entry.id;
        const hidden = runtime.playLibrarySearch && !entry.search.includes(runtime.playLibrarySearch.toLowerCase());
        return `<article class="ls-play-library-entry${hidden ? ' ls-search-hidden' : ''}" data-play-search="${escapeHtml(entry.search)}"><button type="button" data-action="select-restraint-entry" data-entry-id="${escapeHtml(entry.id)}" aria-pressed="${selected}"><strong>${escapeHtml(entry.label)}</strong><small>${escapeHtml(entry.posture)}${entry.variants.length > 1 ? ` · ${entry.variants.length}种绳材` : ''}</small></button></article>`;
      }).join('');
      return `<details class="ls-play-library-section"${furnitureOnly || runtime.playLibrarySearch || entries.some(entry => entry.id === runtime.playDraft?.entry_id) ? ' open' : ''}><summary><strong>${group}</strong><span>${entries.length}种</span></summary><div class="ls-play-library-list">${cards}</div></details>`;
    }).join('');
    return `<div class="ls-restraint-page">${buildPlaySearchMarkup()}<div class="ls-play-choice-row"><button type="button" data-action="restraint-filter" data-furniture-only="false" aria-pressed="${!furnitureOnly}">全部束具</button><button type="button" data-action="restraint-filter" data-furniture-only="true" aria-pressed="${furnitureOnly}">家具固定</button><button type="button" data-action="select-restraint-entry" data-entry-id="custom">自定义设置</button></div>${buildRestraintDraftEditor()}<div class="ls-play-library-sections">${sections}</div></div>`;
  }

  function handleRestraintAction(button) {
    const action = button.dataset.action;
    if (action === 'restraint-filter') {
      runtime.restraintFurnitureOnly = button.dataset.furnitureOnly === 'true';
      runtime.playLibraryPage = 'restraint';
      runtime.playLibrarySearch = '';
    } else if (action === 'select-restraint-entry') {
      const entry = restraintEntry(button.dataset.entryId);
      if (!entry) return false;
      const previous = runtime.playDraft?.kind === 'restraint' ? runtime.playDraft : null;
      const same = previous?.entry_id === entry.id;
      runtime.playDraft = same ? previous : { kind: 'restraint', entry_id: entry.id, variant_id: entry.variants[0]?.id || '', character: previous?.character || playApplicationCharacters()[0] || '', partner_character: '', detail: '' };
      if (!same) runtime.playEditingId = '';
    } else if (action === 'select-restraint-material') {
      const draft = runtime.playDraft;
      if (draft?.kind !== 'restraint' || !restraintEntry(draft.entry_id)?.variants.some(item => item.id === button.dataset.variantId)) return false;
      runtime.playDraft = { ...draft, variant_id: button.dataset.variantId };
    } else if (action === 'select-restraint-partner') {
      if (runtime.playDraft?.kind !== 'restraint') return false;
      runtime.playDraft = { ...runtime.playDraft, partner_character: button.dataset.characterName || '' };
    } else if (action === 'insert-restraint-draft' || action === 'insert-play-input-draft') {
      const combination = runtime.playCombinations.find(item => item.id === button.dataset.combinationId && ['restraint', 'marking', 'body_modification'].includes(item.kind));
      if (!combination) return false;
      const result = appendPlayInputDraft(combination, runtime.hostDocument, runtime.adapter, true);
      runtime.playFeedback = result === 'unavailable' ? '没有找到聊天输入框；请先打开聊天。' : '草稿已在聊天输入框中，尚未发送。';
    } else return false;
    renderStatePanel(runtime.snapshot);
    return true;
  }

  function updateRestraintDraftInput(event, panel) {
    const field = event.target;
    if (runtime.playDraft?.kind !== 'restraint') return false;
    if (field.matches?.('[data-role="restraint-detail"]')) runtime.playDraft = { ...runtime.playDraft, detail: field.value.slice(0, 500) };
    else if (field.matches?.('[data-role="restraint-partner"]')) runtime.playDraft = { ...runtime.playDraft, partner_character: field.value.slice(0, 120) };
    else return false;
    const preview = panel.querySelector('[data-role="restraint-input-preview"]');
    if (preview) preview.textContent = restraintInputDraft(runtime.playDraft) || '选好人物并补全设置后生成。';
    const apply = panel.querySelector('[data-action="apply-play-combination"]');
    if (apply) apply.disabled = !normalizeRestraintDraft(runtime.playDraft);
    return true;
  }

