      logStateError('branch_scan_unavailable', '找不到当前分支消息读取接口；暂时回退聊天变量缓存。');
      await loadAndRefresh(adapter);
      return { found: runtime.hasSnapshot, snapshot: runtime.snapshot, source: 'cache' };
    }

    let messages = options.messages;
    if (!Array.isArray(messages)) {
      try {
        messages = await adapter.listMessages();
      } catch (error) {
        if (isCancelledStateOperation(error)) throw error;
        logStateError('branch_scan_failed', error);
        await loadAndRefresh(adapter);
        showStateUpdateFailure(null, 'branch_scan_failed', adapter);
        return { found: runtime.hasSnapshot, snapshot: runtime.snapshot, source: 'cache' };
      }
    }

    const assistantMessages = (Array.isArray(messages) ? messages : [])
      .filter((message) => message?.role === 'assistant' && typeof message.message === 'string')
      .sort((left, right) => Number(left.message_id) - Number(right.message_id));

    let manualLimit = Infinity;
    if (options.excludeLastAssistant && assistantMessages.length > 0) {
      const excluded = assistantMessages.pop();
      manualLimit = Number(excluded.message_id) - 1;
      logStateError(
        'branch_generation_exclusion',
        `生成类型 ${options.generationType || 'unknown'}：已排除末尾助手楼层 ${excluded.message_id}，避免注入被重生成回复自身的状态。`,
        'info',
      );
    }

    const stored = await readStoreWithContentDefaults(adapter);
    restoreFormatRepairPreferences(stored);
    runtime.cyclePresenceEnabled = stored?.cycle_presence_enabled === true;
    runtime.externalAnalysisMode = normalizeExternalAnalysisMode(stored?.external_analysis_mode);
    runtime.externalContentCleaning = normalizeExternalCleaning(stored?.external_content_cleaning);
    const rebuildModules = modulesFromStore(stored, adapter?.getStoreSource?.() || 'vnext');
    const rebuildPlayIds = normalizeActivePlayIds(stored?.active_play_routes);
    const rebuildPlayLibraryEnabled = stored?.play_library_enabled === true;
    const rebuildPlayCombinations = sanitizePlayCombinations(stored?.play_combinations);
    const rebuildEffectMode = normalizeEffectMode(stored?.effect_mode);
    const rebuildWorkflowMode = normalizeWorkflowMode(stored?.state_workflow_mode);
    const rebuildExternalPreflightEnabled = stored?.external_preflight_enabled === true;
    const rebuildUserTrackingEnabled = stored?.user_tracking_enabled === true;
    const rebuildTrackedUserName = normalizeTrackedUserName(stored?.tracked_user_name);
    const manualContext = manualReplayContext(stored);
    const manualRecords = manualHistory(stored);
    const manualIndex = manualBranchIndex(messages);
    const manualPendingStart = Math.min(Infinity,...sanitizeExternalPendingQueue(stored?.external_pending_queue).filter(row=>externalMessageMatches(messages.find(m=>m.message_id===row.message_id),row)).map(row=>row.message_id));
    const manualRows = manualRecords.filter(row => manualRowActive(row, manualIndex, Math.min(manualLimit,manualPendingStart-1)))
      .sort((a,b)=>(a.anchor?.message_id??-1)-(b.anchor?.message_id??-1)||a.seq-b.seq);
    let manualCursor = 0;
    let rebuildCharacterProfiles = sanitizeCharacterProfiles(manualContext.character_profiles);
    for (const profile of Object.values(rebuildCharacterProfiles)) delete profile.observation_paused;
    let allowedNames = modelCharacterNames(stored);
    const manualSeedNames = new Set(Object.keys(stored?.snapshot?.characters || {}));
    const firstWholeManual = new Map();
    for (const row of manualRecords) for (const patch of row.patches) {
      if(patch.path[0]!=='snapshot') continue;
      const name=patch.path[2];
      if(patch.before_exists) manualSeedNames.add(name);
      if(patch.path.length===3 && !firstWholeManual.has(name)) firstWholeManual.set(name,patch.before_exists);
    }
    for(const [name,existed] of firstWholeManual) if(!existed) manualSeedNames.delete(name);
    runtime.autoProfileEnabled = stored?.auto_profile_enabled !== false;
    const rebuildPregnancyAwarenessEdits = Object.fromEntries(
      Object.entries(sanitizePregnancyAwarenessEdits(stored?.pregnancy_awareness_edits)).filter(([, edit]) => assistantMessages.some((message) =>
        Number(message.message_id) === edit.source_message_id
        && (Number.isInteger(message.swipe_id) ? message.swipe_id : null) === edit.source_swipe_id
        && sha256Hex(message.message || '') === edit.content_sha256)),
    );
    const rebuildExternalStateLedger = sanitizeExternalStateLedger(stored?.external_state_ledger);
    const branchMessageKeys = new Set((Array.isArray(messages) ? messages : []).map((message) => `${Number(message?.message_id)}:${Number.isInteger(message?.swipe_id) ? message.swipe_id : 'main'}`));
    const rebuildExternalPendingQueue = sanitizeExternalPendingQueue(stored?.external_pending_queue).filter((entry) => {
      const message = (Array.isArray(messages) ? messages : []).find((item) => Number(item?.message_id) === entry.message_id && (Number.isInteger(item?.swipe_id) ? item.swipe_id : null) === entry.swipe_id);
      return message && sha256Hex(message.message || '') === entry.content_sha256;
    });
    const rebuildEffectiveModules = modulesWithPlayRequirements(rebuildModules, playNarrativeRouteIds(rebuildPlayIds, stored?.snapshot));
    runtime.formatBoostAutoActive = rebuildWorkflowMode === WORKFLOW_MODES.INLINE && !hasValidSnapshotAfterFirstUser(messages, {
      excludeLastAssistant: options.excludeLastAssistant, modules: rebuildEffectiveModules,
      inlineFormatRepairs: stored?.inline_format_repairs || {},
    });
    runtime.missingStateReminder = missingStateReminderForBranch(messagesForGenerationScan(messages, Boolean(options.excludeLastAssistant)), stored || {});
    const rebuildCycleEnabled = rebuildEffectiveModules.reproductive;
    runtime.modules = rebuildModules;
    runtime.activePlayIds = rebuildPlayIds;
    runtime.playLibraryEnabled = rebuildPlayLibraryEnabled;
    runtime.playCombinations = rebuildPlayCombinations;
    runtime.effectMode = rebuildEffectMode;
    runtime.workflowMode = rebuildWorkflowMode;
    runtime.externalPreflightEnabled = rebuildExternalPreflightEnabled;
    runtime.userTrackingEnabled = rebuildUserTrackingEnabled;
    runtime.trackedUserName = rebuildTrackedUserName;
    runtime.characterProfiles = rebuildCharacterProfiles;
    runtime.externalStateLedger = rebuildExternalStateLedger;
    runtime.externalPendingQueue = rebuildExternalPendingQueue;
    runtime.externalStatus = 'idle';
    runtime.externalError = '';
    runtime.externalPendingMessageId = rebuildExternalPendingQueue[0]?.message_id ?? null;
    runtime.externalPreflightResult = null;
    runtime.cycleEnabled = rebuildCycleEnabled;
    let archives = {};

    let dailyAnchorArchives = Object.fromEntries(Object.entries(sanitizeDailyAnchorArchives(stored?.daily_anchor_archives)).filter(([, entry]) => !entry.observation_paused));
    for (const row of manualRecords) for (const patch of row.patches) {
      if (patch.path[0] === 'snapshot' && (patch.path.length === 3 || patch.path[3] === 'needs')) delete dailyAnchorArchives[patch.path[2]];
    }
    let archiveTombstones = Object.fromEntries(
      Object.entries(sanitizeArchiveTombstones(stored?.archive_tombstones)).filter(([, entry]) => entry.manual),
    );
    let effectDismissals = sanitizeEffectDismissals(manualContext.effect_dismissals);
    let conceptionDecisionLedger = Object.fromEntries(Object.entries(sanitizeConceptionDecisionLedger(stored?.conception_decision_ledger)).filter(([, entry])=>!entry.manual));
    const storedConceptionEvents = Object.fromEntries(Object.entries(sanitizeConceptionEventLedger(stored?.conception_event_ledger))
      .filter(([, entry]) => !entry.branch_source_key || branchMessageKeys.has(entry.branch_source_key))
      .map(([key, entry]) => {
        if (entry.scene_override_source_key && !branchMessageKeys.has(entry.scene_override_source_key)) {
          entry.scene_override_percent = null;
          entry.scene_override_source_key = null;
          entry.closed = false;
          entry.resolution = '';
        }
        return [key, entry];
      }));
    const pendingConceptionNoticeKeys = new Set(Object.entries(storedConceptionEvents).filter(([, entry]) => entry.notice_pending).map(([key]) => key));

    let conceptionEventLedger = {};
    let activeConceptionDecisions = {};
    const sexualDesireBaselines = sanitizeSexualDesireBaselines(stored?.sexual_desire_baselines);
    let sexualDesireProfiles = {};
    let staminaProfiles = {};
    let branchSession = { counter: 0, current: null };
    let latest = null;
    let previousValidSnapshot = null;
    let lastCheckedResult = null;
    const replayManual = (snapshot, boundary, inclusive) => {
      if(manualCursor>=manualRows.length) return {snapshot,changed:false};
      const view = { ...stored, snapshot:cloneJson(snapshot), modules: rebuildModules, character_profiles: rebuildCharacterProfiles,
        effect_dismissals: effectDismissals, archives, daily_anchor_archives: dailyAnchorArchives,
        conception_event_ledger: conceptionEventLedger, conception_decision_ledger: conceptionDecisionLedger,
        active_conception_decisions: activeConceptionDecisions, stamina_profiles: staminaProfiles };
      let changed = false;
      while (manualCursor < manualRows.length) {
        const row = manualRows[manualCursor], id = row.anchor?.message_id ?? -1;
        if (inclusive ? id > boundary : id >= boundary) break;
        applyManualRow(view,row);
        for(const patch of row.patches) if(patch.path[0]==='snapshot' && patch.path.length===3 && !patch.after_exists) manualSeedNames.delete(patch.path[2]);
        manualCursor++; changed = true;
      }
      if (changed) {
        normalizeManualProjection(view,snapshot);
        rebuildCharacterProfiles = sanitizeCharacterProfiles(view.character_profiles);
        effectDismissals = sanitizeEffectDismissals(view.effect_dismissals);
        archives = sanitizeArchiveMap(view.archives);
        dailyAnchorArchives = sanitizeDailyAnchorArchives(view.daily_anchor_archives);
        conceptionEventLedger = sanitizeConceptionEventLedger(view.conception_event_ledger);
        conceptionDecisionLedger = sanitizeConceptionDecisionLedger(view.conception_decision_ledger);
        activeConceptionDecisions = sanitizeActiveConceptionDecisions(view.active_conception_decisions,conceptionDecisionLedger);
        staminaProfiles = sanitizeStaminaProfiles(view.stamina_profiles);
        runtime.characterProfiles = rebuildCharacterProfiles;
      }
      return {snapshot:view.snapshot,changed};
    };
    for (const message of assistantMessages) {
      const beforeManual = replayManual(previousValidSnapshot,Number(message.message_id),false);
      previousValidSnapshot = beforeManual.snapshot;
      if (beforeManual.changed && latest) latest.result.snapshot = previousValidSnapshot;
      if (manualRecords.length) {
        allowedNames = modelCharacterNames({ ...stored, snapshot:previousValidSnapshot, character_profiles:rebuildCharacterProfiles });
        if(allowedNames) for(const name of manualSeedNames) allowedNames.add(name);
      }
      const provenance = {
        source_message_id: Number(message.message_id),
        source_swipe_id: Number.isInteger(message.swipe_id) ? message.swipe_id : null,
      };
      const externalLedgerEntry = externalLedgerEntryForMessage(message, rebuildExternalStateLedger, messages);
      const externalStateText = externalLedgerEntry?.raw_state_block || '';
      const stateSourceText = externalStateText || inlineStateText(message, stored, messages);
      const rawArchive = extractRawReproductiveArchiveState(stateSourceText, allowedNames);
      if (rawArchive.ok) {
        logCleanupWarnings(rawArchive.warnings, `分支原始生殖楼层 ${message.message_id}`);
        const rawOperations = applyArchiveOperations(
          archives,
          archiveTombstones,
          rawArchive.snapshot,
          rawArchive.archiveDeletions,
          provenance,
          rawArchive.reproductiveModuleDeletions,
        );
        archives = rawOperations.archives;
        archiveTombstones = rawOperations.tombstones;
      }
      const result = processLifeStateTextFlexible(stateSourceText, rebuildEffectiveModules, previousValidSnapshot, allowedNames, dailyAnchorArchives);
      lastCheckedResult = result;
      if (!result.ok) {
        if (result.code !== 'missing_block') {
          logStateError('branch_snapshot_skipped', `楼层 ${message.message_id}：${result.error}`);
        }
        const manual = replayManual(previousValidSnapshot,Number(message.message_id),true);
        previousValidSnapshot = manual.snapshot;
        if (manual.changed && latest) latest.result.snapshot = previousValidSnapshot;
        continue;
      }
      if (result.blockCount > 1) {
        logStateError('multiple_blocks', `楼层 ${message.message_id} 检测到 ${result.blockCount} 个状态块；重建时采用最后一个。`);
      }
      manualSeedNames.clear();
      rebuildCharacterProfiles = reconcileProfileObservation(rebuildCharacterProfiles, result.snapshot, externalLedgerEntry?.change_evidence || null);
      runtime.characterProfiles = rebuildCharacterProfiles;
      logCleanupWarnings(result.warnings, `分支楼层 ${message.message_id}`);
      const sceneWarnings = [];
      const sceneResult = reconcileSceneSession(result.snapshot, {
        nsfw_session_counter: branchSession.counter,
        nsfw_session_id: branchSession.current,
      }, sceneWarnings);
      result.snapshot = sceneResult.snapshot;
      branchSession = { counter: sceneResult.counter, current: sceneResult.current };
      logCleanupWarnings(sceneWarnings, `分支楼层 ${message.message_id}`);
      result.snapshot = preserveDormantCycleRecords(
        result.snapshot,
        previousValidSnapshot || result.snapshot,
        rebuildCycleEnabled,
        result.archiveDeletions,
      );
      const progressWarnings = [];
      const needAnchorUpdates = collectNeedAnchorUpdates(previousValidSnapshot, result.snapshot);
      result.snapshot = reconcileNeedTimes(result.snapshot, previousValidSnapshot, progressWarnings);
      result.snapshot = applyNeedStageFloors(result.snapshot, progressWarnings);
      dailyAnchorArchives = updateDailyAnchorArchives(
        dailyAnchorArchives,
        result.snapshot,
        result.detectedModules || rebuildModules,
        provenance,
        { pruneMissing: true },
      );
      const conceptionTurn = reconcileConceptionTurn(
        result.snapshot, previousValidSnapshot, conceptionEventLedger,
        conceptionDecisionLedger, activeConceptionDecisions,
        provenance, progressWarnings, (externalLedgerEntry?.conception_updates || []).filter(item => !allowedNames || allowedNames.has(item.character)), options.randomFn || randomUnit,
        result.reproductiveModuleDeletions,
      );
      conceptionEventLedger = conceptionTurn.eventLedger;
      const decided = { snapshot: conceptionTurn.snapshot, ledger: conceptionTurn.decisionLedger, active: conceptionTurn.activeDecisions, notices: conceptionTurn.notices };
      logCleanupWarnings(progressWarnings, `分支楼层 ${message.message_id}`);
      result.snapshot = applyPregnancyAwarenessEdits(decided.snapshot, rebuildPregnancyAwarenessEdits, message, conceptionEventLedger);
      result.snapshot = reconcileCyclePresence(result.snapshot, previousValidSnapshot, stored?.cycle_presence_enabled === true, rebuildEffectiveModules);
      conceptionDecisionLedger = decided.ledger;
      activeConceptionDecisions = decided.active;
      conceptionEventLedger = reconcileConceptionAwarenessLedger(conceptionEventLedger, result.snapshot, decided.notices);
      if (result.detectedModules?.sexual_desire === true) {
        const sexualDesireState = reconcileSexualDesireProfiles(
          sexualDesireProfiles,
          sexualDesireBaselines,
          result.snapshot,
          previousValidSnapshot,
          result.sexualDesireUpdates,
          provenance,
          rebuildCycleEnabled,
        );
        sexualDesireProfiles = sexualDesireState.profiles;
      }
      const receipt = staminaReplayReceipt(stored, message, manualIndex, result, externalLedgerEntry);
      if (receipt) staminaProfiles = settleStamina(staminaProfiles, result.snapshot, previousValidSnapshot, receipt.updates, receipt.modules, receipt.identity.prefix_sha256, progressWarnings);
      logCleanupWarnings(progressWarnings.filter(warning => warning.includes('体力未结算')), `分支楼层 ${message.message_id}`);
      result.snapshot = replayManual(result.snapshot,Number(message.message_id),true).snapshot;
      if (rebuildModules.reproductive) {
        const activeOperations = applyArchiveOperations(
          archives,
          archiveTombstones,
          result.snapshot,
          result.archiveDeletions,
          provenance,
          result.reproductiveModuleDeletions,
        );
        archives = activeOperations.archives;
        archiveTombstones = activeOperations.tombstones;
      }
      const timelineDeltaHours = calculateTimelineDelta(previousValidSnapshot?.timeline, result.snapshot?.timeline);
      latest = { message, result, provenance, timelineDeltaHours, needAnchorUpdates };
      previousValidSnapshot = result.snapshot;
    }

    const tailManual = replayManual(previousValidSnapshot,manualLimit,true);
    previousValidSnapshot = tailManual.snapshot;
    if (tailManual.changed && latest) latest.result.snapshot = previousValidSnapshot;
    const feedbackIssue = branchStateUpdateIssue(assistantMessages.at(-1), lastCheckedResult, messages);
    if (latest) {
      for (const [key, entry] of Object.entries(conceptionEventLedger)) {
        if (pendingConceptionNoticeKeys.has(key)) entry.notice_pending = true;
      }
      const restoreWarnings = [];
      let rebuiltSnapshot = snapshotForModules(latest.result.snapshot, rebuildEffectiveModules);
      rebuiltSnapshot = restoreDailyAnchorsIntoSnapshot(rebuiltSnapshot, dailyAnchorArchives, rebuildEffectiveModules, restoreWarnings);
      rebuiltSnapshot = ensureActiveCharacterProfiles(rebuiltSnapshot, rebuildCharacterProfiles, rebuildEffectiveModules, stored?.snapshot);
      logCleanupWarnings(restoreWarnings, '分支重建日常锚点');
      if (rebuildEffectiveModules.sexual_desire) {
        sexualDesireProfiles = reconcileSexualDesireProfiles(
          sexualDesireProfiles,
          sexualDesireBaselines,
          rebuiltSnapshot,
          rebuiltSnapshot,
          {},
          latest.provenance,
          rebuildEffectiveModules.reproductive,
        ).profiles;
      }
      const saved = await saveLastValidSnapshot(rebuiltSnapshot, adapter, latest.provenance, {
        clearManualPending: true, manualProjectionLimit: manualLimit, projectManualPending: manualPendingStart!==Infinity && manualLimit===Infinity,
        cyclePresencePreviousSnapshot: rebuiltSnapshot,
        archives,
        dailyAnchorArchives,
        archiveTombstones,
        effectDismissals,
        effectMode: rebuildEffectMode,
        conceptionDecisionLedger,
        conceptionEventLedger,
        activeConceptionDecisions,
        sexualDesireProfiles,
        sexualDesireBaselines,
        timelineDeltaHours: latest.timelineDeltaHours,
        staminaProfiles,
        modules: rebuildModules,
        activePlayIds: rebuildPlayIds,
        playLibraryEnabled: rebuildPlayLibraryEnabled,
        playCombinations: rebuildPlayCombinations,
        externalPendingQueue: rebuildExternalPendingQueue,
        sessionState: branchSession,
        workflowMode: rebuildWorkflowMode,
        externalPreflightEnabled: rebuildExternalPreflightEnabled,
        userTrackingEnabled: rebuildUserTrackingEnabled,
        trackedUserName: rebuildTrackedUserName,
        externalStateLedger: rebuildExternalStateLedger,
        characterProfiles: rebuildCharacterProfiles,
        pregnancyAwarenessEdits: rebuildPregnancyAwarenessEdits,
      });
      runtime.snapshot = saved;
      runtime.hasSnapshot = true;
      runtime.stateUpdateFeedback = { sourceMessageId: Number(latest.message.message_id), issue: feedbackIssue };
      runtime.needAnchorUpdates = latest.needAnchorUpdates;
      refreshStatePanel();
      return {
        found: true,
        snapshot: saved,
        messageId: Number(latest.message.message_id),
        swipeId: Number.isInteger(latest.message.swipe_id) ? latest.message.swipe_id : null,
        source: 'active_chat',
      };
    }

    const manualSnapshot = previousValidSnapshot || ensureActiveCharacterProfiles(null, rebuildCharacterProfiles, rebuildEffectiveModules, manualRecords.length ? null : stored?.snapshot);
    if (manualSnapshot !== null) {
      const saved = await saveLastValidSnapshot(manualSnapshot, adapter, {}, {
        clearManualPending: true, manualProjectionLimit: manualLimit, projectManualPending: manualPendingStart!==Infinity && manualLimit===Infinity,
        archives, dailyAnchorArchives, archiveTombstones, effectDismissals, effectMode: rebuildEffectMode,
        conceptionDecisionLedger, conceptionEventLedger, activeConceptionDecisions, sexualDesireProfiles, sexualDesireBaselines,
        staminaProfiles,
        modules: rebuildModules, activePlayIds: rebuildPlayIds, playLibraryEnabled: rebuildPlayLibraryEnabled,
        playCombinations: rebuildPlayCombinations, externalPendingQueue: rebuildExternalPendingQueue,
        userTrackingEnabled: rebuildUserTrackingEnabled, trackedUserName: rebuildTrackedUserName,
        characterProfiles: rebuildCharacterProfiles,
      });
      runtime.snapshot = saved;
      runtime.hasSnapshot = true;
      runtime.stateUpdateFeedback = { sourceMessageId: null, issue: feedbackIssue };
      runtime.needAnchorUpdates = [];
      refreshStatePanel();
      return { found: true, snapshot: saved, source: 'manual_profiles' };
    }
    const pendingManualSnapshot = await saveNoValidSnapshot(adapter, { clearManualPending: true, manualProjectionLimit: manualLimit, projectManualPending: manualPendingStart!==Infinity && manualLimit===Infinity, archives, dailyAnchorArchives, archiveTombstones, effectDismissals, effectMode: rebuildEffectMode, conceptionDecisionLedger, conceptionEventLedger, activeConceptionDecisions, sexualDesireProfiles, sexualDesireBaselines, staminaProfiles, modules: rebuildModules, activePlayIds: rebuildPlayIds, playLibraryEnabled: rebuildPlayLibraryEnabled, playCombinations: rebuildPlayCombinations, externalPendingQueue: rebuildExternalPendingQueue, userTrackingEnabled: rebuildUserTrackingEnabled, trackedUserName: rebuildTrackedUserName, characterProfiles: rebuildCharacterProfiles });
    runtime.snapshot = pendingManualSnapshot || null;
    runtime.hasSnapshot = Boolean(pendingManualSnapshot);
    runtime.stateUpdateFeedback = { sourceMessageId: null, issue: feedbackIssue };
    runtime.needAnchorUpdates = [];
    refreshStatePanel();
    return { found: runtime.hasSnapshot, snapshot: runtime.snapshot, source: 'active_chat' };
  }

  async function findLatestBranchSnapshot(adapter = runtime.adapter, options = {}) {
    if (!adapter?.listMessages) return { found: false, unavailable: true, messages: [] };
    const messages = await adapter.listMessages();
    const stored = await readStoreWithContentDefaults(adapter);
    const ledger = sanitizeExternalStateLedger(stored?.external_state_ledger || runtime.externalStateLedger);
    const storedModules = modulesFromStore(stored, adapter?.getStoreSource?.() || 'vnext');
    const scanModules = modulesWithPlayRequirements(storedModules, normalizeActivePlayIds(stored?.active_play_routes));
    const assistantMessages = (Array.isArray(messages) ? messages : [])
      .filter((message) => message?.role === 'assistant' && typeof message.message === 'string')
      .sort((left, right) => Number(left.message_id) - Number(right.message_id));
    if (options.excludeLastAssistant && assistantMessages.length > 0) assistantMessages.pop();
    let feedbackIssue = null;
    for (let index = assistantMessages.length - 1; index >= 0; index -= 1) {
      const message = assistantMessages[index];
      const result = processLifeStateTextFlexible(externalLedgerEntryForMessage(message, ledger, assistantMessages)?.raw_state_block || inlineStateText(message, stored, messages), scanModules, null, modelCharacterNames(stored));
      if (index === assistantMessages.length - 1) feedbackIssue = branchStateUpdateIssue(message, result, messages);
      if (!result.ok) continue;
      return {
        found: true,
        result,
        message,
        messages,
        messageId: Number(message.message_id),
        swipeId: Number.isInteger(message.swipe_id) ? message.swipe_id : null,
        feedbackIssue,
      };
    }
    return { found: false, messages, feedbackIssue };
  }

  async function resolveSnapshotForGeneration(adapter = runtime.adapter, options = {}) {
    let latest;
    try {
      latest = await findLatestBranchSnapshot(adapter, options);
    } catch (error) {
      logStateError('branch_tail_scan_failed', error);
      return rebuildSnapshotFromActiveChat(adapter, options);
    }
    const loaded = await loadLastValidSnapshot(adapter);
    const archiveIndexMatches = loaded.archiveIndexSourceMessageId === loaded.sourceMessageId;
    const currentStore = await adapter.getStore() || {};
    const manualCacheMatches = !manualHistory(currentStore).length || currentStore.manual_projection_key === manualProjectionKey(currentStore,latest.messages,
      options.excludeLastAssistant ? Math.max(-1,...latest.messages.filter(row=>row.role==='assistant').map(row=>row.message_id)) - 1 : Infinity);
    const sameSource = latest.found
      && loaded.hasSnapshot
      && latest.messageId === loaded.sourceMessageId
      && latest.swipeId === loaded.sourceSwipeId
      && archiveIndexMatches;
    const sameEmptySource = !latest.found && !loaded.hasSnapshot && loaded.archiveIndexSourceMessageId === null;
    const staminaSourceMessage = latest.messages.find(message => Number(message.message_id) === latest.messageId);
    const savedStaminaReceipt = staminaSourceMessage && currentStore.stamina_receipts?.[externalLedgerKey(staminaSourceMessage.message_id, staminaSourceMessage.swipe_id)];
    const staminaCacheMatches = !savedStaminaReceipt || Boolean(staminaReceipt(currentStore, staminaSourceMessage, manualBranchIndex(latest.messages)));
    if ((sameSource || sameEmptySource) && manualCacheMatches && staminaCacheMatches) {
      runtime.hasSnapshot = loaded.hasSnapshot;
      runtime.snapshot = loaded.snapshot;
      if (!loaded.hasSnapshot) runtime.needAnchorUpdates = [];
      runtime.archives = loaded.archives;
      runtime.dailyAnchorArchives = loaded.dailyAnchorArchives;
      runtime.archiveTombstones = loaded.archiveTombstones;
      runtime.effectDismissals = loaded.effectDismissals;
      runtime.effectMode = loaded.effectMode;
      runtime.conceptionDecisionLedger = loaded.conceptionDecisionLedger;
      runtime.conceptionEventLedger = loaded.conceptionEventLedger;
      runtime.activeConceptionDecisions = loaded.activeConceptionDecisions;
      runtime.sexualDesireProfiles = loaded.sexualDesireProfiles;
      runtime.sexualDesireBaselines = loaded.sexualDesireBaselines;
      runtime.characterProfiles = loaded.characterProfiles;
      runtime.pendingRestore = loaded.pendingRestore;
      runtime.formatBoostPending = loaded.formatBoostPending;
      runtime.formatBoostAlwaysOn = loaded.formatBoostAlwaysOn;
      runtime.nsfwEnhancementEnabled = loaded.nsfwEnhancementEnabled;
      runtime.bodyExpressionEnabled = loaded.bodyExpressionEnabled;
      runtime.modules = loaded.modules;
      runtime.activePlayIds = loaded.activePlayIds;
      runtime.playLibraryEnabled = loaded.playLibraryEnabled;
      runtime.playCombinations = loaded.playCombinations;
      runtime.cycleEnabled = loaded.cycleEnabled;
      runtime.nsfwSessionCounter = loaded.nsfwSessionCounter;
      runtime.nsfwSession = loaded.nsfwSession;
      runtime.workflowMode = loaded.workflowMode;
      runtime.externalPreflightEnabled = loaded.externalPreflightEnabled;
      runtime.userTrackingEnabled = loaded.userTrackingEnabled;
      runtime.autoProfileEnabled = loaded.autoProfileEnabled !== false;
