  function installDisplayRegexWhenReady() {
    const task = runtime.displayRegexInstallation;
    if (!task || runtime.destroyed || task.ready) return Promise.resolve();
    if (task.promise) return task.promise;
    if (task.timer !== null) { clearTimeout(task.timer); task.timer = null; }
    const isActive = () => !runtime.destroyed && runtime.displayRegexInstallation === task;
    task.promise = Promise.resolve().then(async () => {
      if (!isActive()) return;
      const result = await runtime.adapter.ensureDisplayStateRegex?.(isActive);
      if (!isActive()) return;
      task.ready = result?.listReady !== false;
      if (!task.ready) task.error = '正文隐藏规则已写入，正则列表尚未同步';
    }).catch(error => {
      task.error = error.message || String(error);
    }).finally(() => {
      task.promise = null;
      if (!isActive() || task.ready) return;

      if (task.retries < 5) {
        task.timer = setTimeout(() => {
          task.timer = null;
          installDisplayRegexWhenReady();
        }, 1000 * 2 ** task.retries++);
      } else {
        logStateError('display_regex_install_failed', `${task.error}；可重新启用脚本重试。`, 'error');
      }
    });
    return task.promise;
  }

  function registerHostEvents(adapter) {
    const register = (name, listener) => {
      try {
        runtime.unsubscribers.push(adapter.on(name, listener));
        return true;
      } catch (error) {
        logStateError(`event_${name}_unavailable`, error);
        return false;
      }
    };

    const scheduleBranchRebuild = () => {
      if (runtime.externalBackgroundJob) {
        invalidateStateOperations();
        runtime.externalStatus = 'error'; runtime.externalError = '聊天内容已变化，后台分析已停止；请检查后重新更新。';
      }
      const scopedAdapter = guardStateAdapter(adapter);
      resetFormatRepairFeedback();
      if (runtime.stateReturnView) closeExternalResponse(runtime.hostDocument);
      const identity = operationChatIdentity(adapter);
      const promptCleanup = releasePromptRequest(adapter);
      if (runtime.displayMode === DISPLAY_MODES.INLINE) removeInlineStatePanel(runtime.hostDocument);
      runtime.queue = runtime.queue
        .then(() => promptCleanup)
        .then(() => rebuildSnapshotFromActiveChat(scopedAdapter))
        .then(async (result) => {
          assertStateOperation(scopedAdapter);
          runtime.generationActive = false;
          runtime.generationMode = null;
          runtime.requestedWorkflowMode = null;
          await refreshStoryClockContext(scopedAdapter);
          if (runtime.workflowMode === WORKFLOW_MODES.EXTERNAL) await syncExternalPendingFromBranch(scopedAdapter);
