          if (runtime.displayMode === DISPLAY_MODES.INLINE) scheduleInlineStatePanelRender(runtime.hostDocument);
          return result;
        });
      runtime.queue = runtime.queue.catch(error => {
        if (isCancelledStateOperation(error)) return;
        logStateError('branch_rebuild_failed', error, 'error');
        showStateUpdateFailure(null, 'branch_rebuild_failed', adapter, identity);
      });
      return runtime.queue;
    };

    register('MESSAGE_RECEIVED', (messageId) => enqueueMessage(Number(messageId)));
    register('GENERATION_AFTER_COMMANDS', (generationType, _option, dryRun) => injectBeforeGeneration(adapter, generationType, dryRun));


    register('GENERATE_BEFORE_COMBINE_PROMPTS', capturePromptAnchors);

    register('GENERATE_AFTER_DATA', (data, dryRun) => {
      if (!ownsBodyPrompt(data?.prompt)) return;
      if (typeof dryRun === 'boolean' && dryRun !== runtime.promptRequest.dryRun) return;
      return clearPublishedPrompt(adapter);
    });
    register('GENERATION_STOPPED', () => {
      releasePromptRequest(adapter).catch(() => {});
      runtime.generationActive = false;
    });
    try {
      runtime.unsubscribers.push(adapter.on('GENERATION_ENDED', () => {
        const scopedAdapter = guardStateAdapter(adapter);
        releasePromptRequest(adapter).catch(() => {});
