    register('MESSAGE_SWIPED', scheduleBranchRebuild);
    register('MESSAGE_EDITED', scheduleBranchRebuild);
    register('MESSAGE_UPDATED', scheduleBranchRebuild);
    register('MESSAGE_DELETED', scheduleBranchRebuild);
